// Data grammar-n2 — dihasilkan otomatis (lihat scripts/fetch-data.mjs).
export default [{"pattern":"A あるいは B","meaning":"Indicates alternatives; 'A or B', 'either A or B'.","formation":"Phrase A + あるいは + Phrase B","examples":[{"jp":"今日は映画を見るあるいはショッピングをする予定です。","en":"Today, I plan to either watch a movie or go shopping.","romaji":"Kyou wa eiga wo miru aruiwa shoppingu wo suru yotei desu."},{"jp":"彼女は英語あるいはドイツ語で話すことができます。","en":"She can speak either English or German.","romaji":"Kanojo wa eigo aruiwa doitsugo de hanasu koto ga dekimasu."},{"jp":"僕らはコーヒーあるいは紅茶を飲むのが好きです。","en":"We like to drink either coffee or tea.","romaji":"Bokura wa koohii aruiwa koucha wo nomu no ga suki desu."},{"jp":"この仕事は正社員あるいは契約社員として働くことができます。","en":"You can work as either a full-time employee or a contract employee in this job.","romaji":"Kono shigoto wa seishain aruiwa keiyaku shain toshite hataraku koto ga dekimasu."}],"example":"今日は映画を見るあるいはショッピングをする予定です。","exampleMeaning":"Today, I plan to either watch a movie or go shopping."},{"pattern":"A。おまけに B。","meaning":"Expresses that in addition to A, there is also B; 'moreover', 'besides', 'not only', 'but also'.","formation":"Sentence A + おまけに  + Sentence B","examples":[{"jp":"彼は遅刻した。おまけに宿題も忘れた。","en":"He was late. Moreover, he forgot his homework.","romaji":"Kare wa chikoku shita. Omake ni shukudai mo wasureta."},{"jp":"このアパートは狭い。おまけに家賃が高い。","en":"This apartment is small. Besides, the rent is high.","romaji":"Kono apaato wa semai. Omake ni yachin ga takai."},{"jp":"彼女は仕事が忙しい。おまけに子供も小さい。","en":"She is busy with work. Not only that, her children are also small.","romaji":"Kanojo wa shigoto ga isogashii. Omake ni kodomo mo chiisai."},{"jp":"昨日は雨が降った。おまけに風も強かった。","en":"Yesterday it rained. In addition, the wind was strong.","romaji":"Kinou wa ame ga futta. Omake ni kaze mo tsuyokatta."}],"example":"彼は遅刻した。おまけに宿題も忘れた。","exampleMeaning":"He was late. Moreover, he forgot his homework."},{"pattern":"A。さて B。(A. Sate B.)","meaning":"Indicates a sudden change or shift in the topic or situation; 'now then', 'well', 'so'.","formation":"A + さて + B","examples":[{"jp":"今日の仕事が終わった。さて、これから帰るか。","en":"Today's work is done. Now then, shall we go home?","romaji":"Kyou no shigoto ga owatta. Sate, kore kara kaeru ka."},{"jp":"話がちょっと長くなったね。さて、もっと喜美子さんのことを教えてください。","en":"The conversation got a bit lengthy. Well, please tell me more about Kimiko.","romaji":"Hanashi ga chotto nagaku natta ne. Sate, motto Kimiko-san no koto wo oshiete kudasai."},{"jp":"映画を見て楽しかった。さて、何を食べに行こう。","en":"Watching the movie was fun. So, what shall we go eat?","romaji":"Eiga wo mite tanoshikatta. Sate, nani wo tabe ni ikou."},{"jp":"マラソンが終わった！さて、少し休んでからシャワーを浴びよう。","en":"The marathon is over! Now then, let's rest a bit and then take a shower.","romaji":"Marason ga owatta! Sate, sukoshi yasunde kara shawaa wo abiyou."}],"example":"今日の仕事が終わった。さて、これから帰るか。","exampleMeaning":"Today's work is done. Now then, shall we go home?"},{"pattern":"A。しかも B。(A. Shikamo B.)","meaning":"Expressing additional information; 'moreover', 'besides', 'furthermore'.","formation":"Statement A + 。しかも + Statement B。","examples":[{"jp":"この料理は美味しいです。しかも、安いです。","en":"This dish is delicious. Moreover, it is cheap.","romaji":"Kono ryouri wa oishii desu. Shikamo, yasui desu."},{"jp":"彼は優秀な学生です。しかも、スポーツが得意です。","en":"He is an excellent student. Besides, he is good at sports.","romaji":"Kare wa yuushuu na gakusei desu. Shikamo, supootsu ga tokui desu."},{"jp":"彼女は歌が上手です。しかも、ダンスも上手です。","en":"She is good at singing. Furthermore, she is also good at dancing.","romaji":"Kanojo wa uta ga jouzu desu. Shikamo, dansu mo jouzu desu."},{"jp":"このカフェは雰囲気がいいです。しかも、コーヒーも美味しいです。","en":"This cafe has a nice atmosphere. Moreover, the coffee is also delicious.","romaji":"Kono kafe wa fun'iki ga ii desu. Shikamo, koohii mo oishii desu."}],"example":"この料理は美味しいです。しかも、安いです。","exampleMeaning":"This dish is delicious. Moreover, it is cheap."},{"pattern":"A。したがって B。(A. Shitagatte B.)","meaning":"Express a cause-and-effect relationship; 'therefore', 'consequently', 'so'.","formation":"A + したがって + B","examples":[{"jp":"今日は雨が降っています。したがって、傘を持って行きましょう。","en":"It is raining today. Therefore, let's bring an umbrella.","romaji":"Kyou wa ame ga futteimasu. Shitagatte, kasa wo motte ikimashou."},{"jp":"彼は忙しいです。したがって、彼に連絡するのはやめましょう。","en":"He is busy. Consequently, let's not contact him.","romaji":"Kare wa isogashii desu. Shitagatte, kare ni renraku suru no wa yamemashou."},{"jp":"そのレストランは人気があります。したがって、予約しないと席がないかもしれません。","en":"That restaurant is popular. Therefore, there might be no seats if you don't make a reservation.","romaji":"Sono resutoran wa ninki ga arimasu. Shitagatte, yoyaku shinai to seki ga nai kamoshiremasen."},{"jp":"試験が近いです。したがって、勉強に集中しましょう。","en":"The exam is coming up soon. Consequently, let's focus on studying.","romaji":"Shiken ga chikai desu. Shitagatte, benkyou ni shuuchuu shimashou."}],"example":"今日は雨が降っています。したがって、傘を持って行きましょう。","exampleMeaning":"It is raining today. Therefore, let's bring an umbrella."},{"pattern":"A すなわち B。","meaning":"Express that A is equivalent to B; 'in other words', 'namely', 'that is to say'.","formation":"Phrase A + すなわち + Phrase B","examples":[{"jp":"私は立派な成果を出したい、すなわち、成功したいのです。","en":"I want to achieve great results, in other words, I want to succeed.","romaji":"Watashi wa rippana seika wo dashitai, sunawachi, seikou shitai no desu."},{"jp":"彼は言葉に詰まった、すなわち、何も言えなかった。","en":"He was at a loss for words, that is to say, he couldn't say anything.","romaji":"Kare wa kotoba ni tsumatta, sunawachi, nani mo ienakatta."},{"jp":"彼女は自分の目標に向かって努力し続けている、すなわち、彼女は非常に頑張っている。","en":"She keeps working hard towards her goals, namely, she is trying very hard.","romaji":"Kanojo wa jibun no mokuhyou ni mukatte doryoku shi tsudzukete iru, sunawachi, kanojo wa hijou ni ganbatte iru."},{"jp":"この店はお客様の満足を一番大事にしています、すなわち、サービスが良いということです。","en":"This store values customer satisfaction above all else, in other words, it has good service.","romaji":"Kono mise wa okyakusama no manzoku o ichiban daiji ni shiteimasu, sunawachi, saabisu ga yoi to iu koto desu."}],"example":"私は立派な成果を出したい、すなわち、成功したいのです。","exampleMeaning":"I want to achieve great results, in other words, I want to succeed."},{"pattern":"A。すると B。","meaning":"Indicates that when action A is done, action or event B follows; 'then', 'when', 'if'.","formation":"A (Sentence) + すると + B (Sentence)","examples":[{"jp":"電話をかけると、彼女が出ました。","en":"When I made the phone call, she answered.","romaji":"Denwa wo kakeru to, kanojo ga demashita."},{"jp":"このボタンを押すと、ドアが開きます。","en":"If you press this button, the door will open.","romaji":"Kono botan wo osu to, doa ga hirakimasu."},{"jp":"コンビニに行くと、たまたま友達に会いました。","en":"When I went to the convenience store, I happened to meet my friend.","romaji":"Konbini ni iku to, tamatama tomodachi ni aimashita."},{"jp":"彼が家を出ると、すぐに雨が降り始めました。","en":"As soon as he left the house, it started to rain.","romaji":"Kare ga ie wo deru to, sugu ni ame ga furihajimemashita."}],"example":"電話をかけると、彼女が出ました。","exampleMeaning":"When I made the phone call, she answered."},{"pattern":"A。そういえば B。","meaning":"Recalling something related to A; 'speaking of which', 'by the way', 'now that you mention it'.","formation":"A + そういえば + B","examples":[{"jp":"映画。そういえば、彼は映画館で働いているんだ。","en":"Movies. Speaking of which, he works at a movie theater.","romaji":"Eiga. Souieba, kare wa eigakan de hataraite irun da."},{"jp":"山田さん。そういえば、彼女は今週末旅行しています。","en":"Ms. Yamada. By the way, she is traveling this weekend.","romaji":"Yamada-san. Souieba, kanojo wa konshuumatsu ryokou shite imasu."},{"jp":"そのレストラン。そういえば、次の週末そこでパーティーがあるんだ。","en":"That restaurant. Now that you mention it, there's a party there next weekend.","romaji":"Sono resutoran. Souieba, tsugi no shuumatsu soko de paatii ga arun da."},{"jp":"寒い。そういえば、明日雪が降るらしいよ。","en":"It's cold. Speaking of which, it seems like it will snow tomorrow.","romaji":"Samui. Souieba, ashita yuki ga furu rashii yo."}],"example":"映画。そういえば、彼は映画館で働いているんだ。","exampleMeaning":"Movies. Speaking of which, he works at a movie theater."},{"pattern":"A。そこで B。","meaning":"Expresses 'therefore' or 'because of that'.","formation":"A + そこで + B","examples":[{"jp":"明日は試験があります。そこで今晩勉強しようと思います。","en":"There is an exam tomorrow. Therefore, I plan to study tonight.","romaji":"Ashita wa shiken ga arimasu. Soko de konban benkyou shiyou to omoimasu."},{"jp":"このレストランは混んでいます。そこで別の場所でランチを食べましょう。","en":"This restaurant is crowded. Therefore, let's eat lunch at a different place.","romaji":"Kono resutoran wa kondeimasu. Soko de betsu no basho de ranchi wo tabemashou."},{"jp":"彼女はアレルギーがある。そこで彼女のために別の料理を作ります。","en":"She has an allergy. Therefore, I'll cook a different dish for her.","romaji":"Kanojo wa arerugii ga aru. Soko de kanojo no tame ni betsu no ryouri wo tsukurimasu."},{"jp":"傘を持っていない。そこで雨が止むまで待ちます。","en":"I don't have an umbrella. Therefore, I'll wait until the rain stops.","romaji":"Kasa wo motte inai. Soko de ame ga yamu made machimasu."}],"example":"明日は試験があります。そこで今晩勉強しようと思います。","exampleMeaning":"There is an exam tomorrow. Therefore, I plan to study tonight."},{"pattern":"A。それがB。","meaning":"Expressing 'that's exactly what A is; in other words, B'.","formation":"A (Statement)。それが B (Restatement or explanation of A)。","examples":[{"jp":"彼は勉強ができる。それが天才というものだ。","en":"He can study well. That's what you call a genius.","romaji":"Kare wa benkyou ga dekiru. Sore ga tensai to iu mono da."},{"jp":"美味しい料理を作る。それが私の趣味なんです。","en":"I make delicious food. That's my hobby.","romaji":"Oishii ryouri wo tsukuru. Sore ga watashi no shumi nan desu."},{"jp":"彼女は私を助けてくれる。それが友達というものだ。","en":"She helps me. That's what a friend is.","romaji":"Kanojo wa watashi wo tasukete kureru. Sore ga tomodachi to iu mono da."},{"jp":"一人で長い旅をする。それが自由というものだ。","en":"Traveling alone for a long time. That's what freedom is.","romaji":"Hitori de nagai tabi wo suru. Sore ga jiyuu to iu mono da."}],"example":"彼は勉強ができる。それが天才というものだ。","exampleMeaning":"He can study well. That's what you call a genius."},{"pattern":"A。それで B。","meaning":"Express a sequence of events or cause-and-effect; 'and then', 'so', 'because of that'.","formation":"Sentence A +。それで+ Sentence B。","examples":[{"jp":"昨日は雨が降っていた。それで公園に行かなかった。","en":"It was raining yesterday. So, I didn't go to the park.","romaji":"Kinou wa ame ga futte ita. Sore de kouen ni ikanakatta."},{"jp":"試験に落ちた。それで再試験を受けなければならない。","en":"I failed the exam. So, I have to take a re-exam.","romaji":"Shiken ni ochita. Sore de sai shiken wo ukenakereba naranai."},{"jp":"部屋が寒かった。それで暖房をつけた。","en":"The room was cold. So, I turned on the heater.","romaji":"Heya ga samukatta. Sore de danbou wo tsuketa."},{"jp":"今日は休みだ。それで映画を見に行く。","en":"Today is a holiday. So, I'm going to watch a movie.","romaji":"Kyou wa yasumi da. Sore de eiga wo mi ni iku."}],"example":"昨日は雨が降っていた。それで公園に行かなかった。","exampleMeaning":"It was raining yesterday. So, I didn't go to the park."},{"pattern":"A。それでも B。","meaning":"Expresses 'even so', 'nevertheless', 'still', or 'but'; used to contrast two statements.","formation":"A (situation) + 。それでも + B (action or thought)","examples":[{"jp":"今日は日曜日です。それでも、仕事に行かなければなりません。","en":"Today is Sunday. Nevertheless, I have to go to work.","romaji":"Kyou wa nichiyoubi desu. Sore demo, shigoto ni ikanakereba narimasen."},{"jp":"彼は若いです。それでも、経験が豊富です。","en":"He is young. Even so, he has a lot of experience.","romaji":"Kare wa wakai desu. Sore demo, keiken ga houfu desu."},{"jp":"雨が降っています。それでも、散歩に行きたいです。","en":"It's raining. Still, I want to go for a walk.","romaji":"Ame ga futteimasu. Sore demo, sanpo ni ikitai desu."},{"jp":"試験の結果が悪かったです。それでも、諦めません。","en":"The exam results were bad. But I won't give up.","romaji":"Shiken no kekka ga warukatta desu. Sore demo, akiramenai."}],"example":"今日は日曜日です。それでも、仕事に行かなければなりません。","exampleMeaning":"Today is Sunday. Nevertheless, I have to go to work."},{"pattern":"A。それなのに B。","meaning":"Express contrast or a contradiction between two situations or facts; 'even though', 'despite', 'but still'.","formation":"A。それなのに B。","examples":[{"jp":"彼は頭がいい。それなのに、試験に落ちた。","en":"He is smart. Despite that, he failed the exam.","romaji":"Kare wa atama ga ii. Sore nanoni, shiken ni ochita."},{"jp":"私は早く起きた。それなのに、バスに遅れた。","en":"I woke up early. Even so, I was late for the bus.","romaji":"Watashi wa hayaku okita. Sore nanoni, basu ni okureta."},{"jp":"昨日は晴れていた。それなのに、彼は傘を持っていた。","en":"It was sunny yesterday. Despite that, he had an umbrella.","romaji":"Kinou wa harete ita. Sore nanoni, kare wa kasa wo motte ita."},{"jp":"彼女は運動が苦手だ。それなのに、マラソンを走ることにした。","en":"She is not good at sports. Nevertheless, she decided to run a marathon.","romaji":"Kanojo wa undou ga nigate da. Sore nanoni, marason wo hashiru koto ni shita."}],"example":"彼は頭がいい。それなのに、試験に落ちた。","exampleMeaning":"He is smart. Despite that, he failed the exam."},{"pattern":"A。それなら B。(A. Sore nara B.)","meaning":"Express 'if that's the case, then'; used to show a logical consequence or decision based on a given situation.","formation":"Situation A (sentence) + 。それなら + Situation B (sentence)","examples":[{"jp":"試験が近い。それなら、もっと勉強しなければならない。","en":"The exam is coming soon. If that's the case, I must study more.","romaji":"Shiken ga chikai. Sore nara, motto benkyou shinakereba naranai."},{"jp":"明日は雨が降るだろう。それなら、傘を持って行こう。","en":"It will probably rain tomorrow. In that case, let's bring an umbrella.","romaji":"Ashita wa ame ga furudarou. Sore nara, kasa wo motte ikou."},{"jp":"彼らはもう帰った。それなら、私も帰ろう。","en":"They have already left. If that's the case, I'll go home too.","romaji":"Karera wa mou kaetta. Sore nara, watashi mo kaerou."},{"jp":"あのレストランは予約がいっぱいだ。それなら、別の場所を探そう。","en":"Reservations at that restaurant are full. In that case, let's find another place.","romaji":"Ano resutoran wa yoyaku ga ippai da. Sore nara, betsu no basho wo sagasou."}],"example":"試験が近い。それなら、もっと勉強しなければならない。","exampleMeaning":"The exam is coming soon. If that's the case, I must study more."},{"pattern":"A それはそうと B。","meaning":"Changing the topic; 'by the way', 'speaking of which'.","formation":"Sentence A + それはそうと + Sentence B","examples":[{"jp":"それはそうと、今日の天気はいいですね。","en":"By the way, the weather is nice today, isn't it?","romaji":"Sore wa sou to, kyou no tenki wa ii desu ne."},{"jp":"映画は面白かったです。それはそうと、この店のラーメンはおいしいですよ。","en":"The movie was interesting. Speaking of which, this restaurant's ramen is delicious.","romaji":"Eiga wa omoshirokatta desu. Sore wa sou to, kono mise no raamen wa oishii desu yo."},{"jp":"明日から夏休みですね。それはそうと、新しいカフェがオープンしたみたいです。","en":"Summer vacation starts tomorrow, huh? By the way, it seems a new cafe has opened.","romaji":"Ashita kara natsu yasumi desu ne. Sore wa sou to, atarashii kafe ga oopun shita mitai desu."},{"jp":"昨日の試験は難しかった。それはそうと、週末にパーティーがあるのを知ってますか？","en":"Yesterday's exam was difficult. Speaking of which, do you know there's a party this weekend?","romaji":"Kinou no shiken wa muzukashikatta. Sore wa sou to, shuumatsu ni paatii ga aru no wo shitte masu ka?"}],"example":"それはそうと、今日の天気はいいですね。","exampleMeaning":"By the way, the weather is nice today, isn't it?"},{"pattern":"A。だが B。","meaning":"Expresses contrasting ideas or statements; 'but', 'however'.","formation":"Sentence A + だが + Sentence B","examples":[{"jp":"このレストランは値段が高い。だが、味はとてもいい。","en":"This restaurant is expensive. But, the taste is very good.","romaji":"Kono resutoran wa nedan ga takai. Daga, aji wa totemo ii."},{"jp":"彼は疲れている。だが、仕事を終わらせるまで休まない。","en":"He is tired. However, he will not rest until he finishes work.","romaji":"Kare wa tsukarete iru. Daga, shigoto o owaraseru made yasumanai."},{"jp":"昨日は寒かった。だが、今日は暖かい。","en":"Yesterday was cold. But, today is warm.","romaji":"Kinou wa samukatta. Daga, kyou wa atatakai."},{"jp":"彼女は外見は地味だ。だが、性格が素晴らしい。","en":"Her appearance is plain. However, she has a wonderful personality.","romaji":"Kanojo wa gaiken wa jimi da. Daga, seikaku ga subarashii."}],"example":"このレストランは値段が高い。だが、味はとてもいい。","exampleMeaning":"This restaurant is expensive. But, the taste is very good."},{"pattern":"A。ただB。","meaning":"Express contrast between two situations; 'although', 'but', 'however'.","formation":"Sentence A + ただ + Sentence B","examples":[{"jp":"彼は頭がいい。ただ、努力はあまりしない。","en":"He is smart; however, he doesn't make much effort.","romaji":"Kare wa atama ga ii. Tada, doryoku wa amari shinai."},{"jp":"外は雨が降っている。ただ、家にいると暇だ。","en":"It's raining outside, but I'm bored at home.","romaji":"Soto wa ame ga futte iru. Tada, ie ni iru to hima da."},{"jp":"そのレストランは値段が高い。ただ、サービスが良い。","en":"That restaurant is expensive; however, the service is good.","romaji":"Sono resutoran wa nedan ga takai. Tada, saabisu ga yoi."},{"jp":"テストの結果は良くなかった。ただ、やり直すチャンスがある。","en":"The test results were not good, but there's a chance to retake it.","romaji":"Tesuto no kekka wa yokunakatta. Tada, yarinaosu chansu ga aru."}],"example":"彼は頭がいい。ただ、努力はあまりしない。","exampleMeaning":"He is smart; however, he doesn't make much effort."},{"pattern":"A。ただしB。 (A. Tadashi B)","meaning":"Adding a condition or exception to a statement; 'however', 'provided that', 'but only if'.","formation":"Statement A + ただし + Condition B","examples":[{"jp":"この部屋を使ってもいいです。ただし、使った後で掃除してください。","en":"You can use this room. However, please clean up after you use it.","romaji":"Kono heya wo tsukatte mo ii desu. Tadashi, tsukatta ato de souji shite kudasai."},{"jp":"明日から出張で不在になります。ただし、緊急の場合は携帯に連絡してください。","en":"I'll be away on a business trip starting tomorrow. However, in case of emergency, please contact me on my cell phone.","romaji":"Ashita kara shucchou de fuzai ni narimasu. Tadashi, kinkyuu no baai wa keitai ni renraku shite kudasai."},{"jp":"食事代は全額会社が負担します。ただし、アルコールのみ自己負担となります。","en":"The company will cover the entire meal cost. However, alcohol expenses will be borne by the individual.","romaji":"Shokuji dai wa zengaku kaisha ga futan shimasu. Tadashi, arukooru nomi jiko futan to narimasu."},{"jp":"図書館で本を借りることができます。ただし、期限内に返さなければなりません。","en":"You can borrow books from the library. However, you must return them within the deadline.","romaji":"Toshokan de hon wo kariru koto ga dekimasu. Tadashi, kigen nai ni kaesanakereba narimasen."}],"example":"この部屋を使ってもいいです。ただし、使った後で掃除してください。","exampleMeaning":"You can use this room. However, please clean up after you use it."},{"pattern":"A。だって B。","meaning":"Used to give a reason, express cause or bring up a topic; 'because', 'since', 'it's just that'.","formation":"Verb-casual + だって、い-Adjective + だって、な-Adjective + だって、Noun + だって","examples":[{"jp":"暇だって、映画を見に行こうよ。","en":"Since we are free, let's go watch a movie.","romaji":"Hima datte, eiga wo mi ni ikou yo."},{"jp":"寒いだって、コートを着てください。","en":"Because it's cold, please wear a coat.","romaji":"Samui datte, ko-to wo kite kudasai."},{"jp":"疲れているだって、休んだほうがいい。","en":"Since you're tired, it's better to rest.","romaji":"Tsukarete iru datte, yasunda hou ga ii."},{"jp":"彼女が料理上手だって、みんな彼女の作った料理を楽しみにしています。","en":"Because she is good at cooking, everyone is looking forward to her dishes.","romaji":"Kanojo ga ryouri jouzu datte, minna kanojo no tsukutta ryouri wo tanoshimi ni shiteimasu."}],"example":"暇だって、映画を見に行こうよ。","exampleMeaning":"Since we are free, let's go watch a movie."},{"pattern":"A。ちなみに B。(A. Chinamini B.)","meaning":"Used to give additional information about the topic; 'by the way', 'incidentally'.","formation":"A。ちなみに B。","examples":[{"jp":"今日は授業がありません。ちなみに、明日も休みです。","en":"There's no class today. By the way, tomorrow is also a day off.","romaji":"Kyou wa jugyou ga arimasen. Chinamini, asu mo yasumi desu."},{"jp":"この店のラーメンは美味しいです。ちなみに、餃子もおすすめです。","en":"The ramen at this shop is delicious. By the way, their gyoza is also recommended.","romaji":"Kono mise no ramen wa oishii desu. Chinamini, gyoza mo osusume desu."},{"jp":"彼は今日は遅刻しました。ちなみに、昨日は欠席しました。","en":"He was late today. By the way, he was absent yesterday.","romaji":"Kare wa kyou wa chikoku shimashita. Chinamini, kinou wa kesseki shimashita."},{"jp":"映画は面白かったです。ちなみに、原作の方がもっといいですよ。","en":"The movie was interesting. By the way, the original work is even better.","romaji":"Eiga wa omoshirokatta desu. Chinamini, gensaku no hou ga motto ii desu yo."}],"example":"今日は授業がありません。ちなみに、明日も休みです。","exampleMeaning":"There's no class today. By the way, tomorrow is also a day off."},{"pattern":"A。ということは B。 (A. To iu koto wa B.)","meaning":"Expresses the meaning 'if A, that means B' or 'A implies B'.","formation":"A + ということは + B","examples":[{"jp":"彼女が泣いている。ということは何か悲しいことがあったに違いない。","en":"She is crying. That means something sad must have happened.","romaji":"Kanojo ga naite iru. To iu koto wa nanika kanashii koto ga atta ni chigainai."},{"jp":"このケーキが残っている。ということは、みんなお腹がいっぱいだったのかな。","en":"This cake is left over. That means everyone must have been full, I guess.","romaji":"Kono keeki ga nokotte iru. To iu koto wa, minna onaka ga ippai datta no ka na."},{"jp":"道が渋滞している。ということは、事故があったのかもしれない。","en":"The road is congested. That means there might have been an accident.","romaji":"Michi ga juutai shite iru. To iu koto wa, jiko ga atta no kamoshirenai."},{"jp":"彼が試験に受かった。ということは、勉強がたくさん頑張ったんだね。","en":"He passed the exam. That means he must have studied really hard.","romaji":"Kare ga shiken ni ukatta. To iu koto wa, benkyou ga takusan ganbattan da ne."}],"example":"彼女が泣いている。ということは何か悲しいことがあったに違いない。","exampleMeaning":"She is crying. That means something sad must have happened."},{"pattern":"A。というのは B。","meaning":"Used to give an explanation or provide additional information for A; 'that is to say', 'in other words'.","formation":"[Statement A]。というのは、[Statement B]。","examples":[{"jp":"彼は非常に疲れています。というのは、昨夜、車で遠くまで行ってきたためです。","en":"He is very tired. That is to say, because he went far by car last night.","romaji":"Kare wa hijou ni tsukareteimasu. To iu no wa, sakuya, kuruma de tooku made itte kita tame desu."},{"jp":"このレストランはおすすめです。というのは、料理が美味しいし、雰囲気もいいからです。","en":"I recommend this restaurant. That is to say, because the food is delicious and the atmosphere is nice.","romaji":"Kono resutoran wa osusume desu. To iu no wa, ryouri ga oishii shi, fun'iki mo ii kara desu."},{"jp":"試験に落ちた。というのは、十分に勉強しなかったからです。","en":"I failed the exam. In other words, because I didn't study enough.","romaji":"Shiken ni ochita. To iu no wa, juubun ni benkyou shinakatta kara desu."},{"jp":"彼女は独特な趣味がある。というのは、昆虫収集だ。","en":"She has a unique hobby. Namely, insect collecting.","romaji":"Kanojo wa dokutoku na shumi ga aru. To iu no wa, konchuu shuushuu da."}],"example":"彼は非常に疲れています。というのは、昨夜、車で遠くまで行ってきたためです。","exampleMeaning":"He is very tired. That is to say, because he went far by car last night."},{"pattern":"A。なおB。(A. Nao B.)","meaning":"Provides additional information; 'moreover', 'besides', 'in addition'.","formation":"A (sentence) + なお + B (sentence)","examples":[{"jp":"明日は休みです。なお、月曜日も休みです。","en":"Tomorrow is a holiday. Moreover, Monday is also a holiday.","romaji":"Ashita wa yasumi desu. Nao, getsuyoubi mo yasumi desu."},{"jp":"彼は頭が良いです。なお、スポーツも得意です。","en":"He is smart. Besides, he is also good at sports.","romaji":"Kare wa atama ga yoi desu. Nao, supootsu mo tokui desu."},{"jp":"この本は面白いです。なお、安いです。","en":"This book is interesting. In addition, it is cheap.","romaji":"Kono hon wa omoshiroi desu. Nao, yasui desu."},{"jp":"私は日本語を勉強しています。なお、韓国語も勉強しています。","en":"I am studying Japanese. Moreover, I am also studying Korean.","romaji":"Watashi wa nihongo wo benkyou shiteimasu. Nao, kankokugo mo benkyou shiteimasu."}],"example":"明日は休みです。なお、月曜日も休みです。","exampleMeaning":"Tomorrow is a holiday. Moreover, Monday is also a holiday."},{"pattern":"A。もっとも B。","meaning":"Express contrasting opinions or facts; 'although', 'but', 'however'.","formation":"Clause A + もっとも + Clause B","examples":[{"jp":"彼は頭がいい。もっとも、勉強も大切だ。","en":"He is smart. However, studying is also important.","romaji":"Kare wa atama ga ii. Mottomo, benkyou mo taisetsu da."},{"jp":"このレストランは美味しい。もっとも、値段が高い。","en":"This restaurant is delicious. But, the prices are high.","romaji":"Kono resutoran wa oishii. Mottomo, nedan ga takai."},{"jp":"彼女は綺麗だ。もっとも、性格が悪い。","en":"She is beautiful. Although, her personality is bad.","romaji":"Kanojo wa kirei da. Mottomo, seikaku ga warui."},{"jp":"日本は面白い国だ。もっとも、住むのが大変そうだ。","en":"Japan is an interesting country. But, it seems difficult to live in.","romaji":"Nihon wa omoshiroi kuni da. Mottomo, sumu no ga taihen sou da."}],"example":"彼は頭がいい。もっとも、勉強も大切だ。","exampleMeaning":"He is smart. However, studying is also important."},{"pattern":"A。要するに B。(A. Yousuru ni B.)","meaning":"Expressing 'in short', 'in a nutshell', or 'to sum up' when restating or summarizing A as B.","formation":"A。要するに B。","examples":[{"jp":"このプロジェクトは成功しました。要するに、私たちのチームは素晴らしい仕事をしました。","en":"This project was successful. In short, our team did a great job.","romaji":"Kono purojekuto wa seikou shimashita. Yousuru ni, watashitachi no chiimu wa subarashii shigoto o shimashita."},{"jp":"彼は料理が上手です。要するに、彼は優れたシェフです。","en":"He is good at cooking. In a nutshell, he is an excellent chef.","romaji":"Kare wa ryouri ga jouzu desu. Yousuru ni, kare wa sugureta shefu desu."},{"jp":"昨日はとても忙しかった。要するに、一日中働いていました。","en":"Yesterday was very busy. To sum up, I was working all day.","romaji":"Kinou wa totemo isogashikatta. Yousuru ni, ichinichijuu hataraite imashita."},{"jp":"彼女は新しい仕事が好きです。要するに、彼女は満足しています。","en":"She likes her new job. In short, she is satisfied.","romaji":"Kanojo wa atarashii shigoto ga suki desu. Yousuru ni, kanojo wa manzoku shiteimasu."}],"example":"このプロジェクトは成功しました。要するに、私たちのチームは素晴らしい仕事をしました。","exampleMeaning":"This project was successful. In short, our team did a great job."},{"pattern":"Noun につき (〜ni tsuki)","meaning":"Indicates the reason, cause, or condition for something; 'due to', 'regarding', 'per'.","formation":"Noun + につき","examples":[{"jp":"試験につき、今日は静かにしてください。","en":"Due to the exam, please be quiet today.","romaji":"Shiken ni tsuki, kyou wa shizuka ni shite kudasai."},{"jp":"このエリアは工事中につき、通行止めです。","en":"The area is closed for passage due to construction.","romaji":"Kono eria wa koujichuu ni tsuki, tsuukoudome desu."},{"jp":"博物館は整備中につき、入場料が無料です。","en":"Due to maintenance, admission to the museum is free.","romaji":"Hakubutsukan wa seibichuu ni tsuki, nyuujouryou ga muryou desu."},{"jp":"商品お一つにつき、1000円の割引があります。","en":"There is a 1,000 yen discount per item.","romaji":"Shouhin o hitotsu ni tsuki, sen'en no waribiki ga arimasu."}],"example":"試験につき、今日は静かにしてください。","exampleMeaning":"Due to the exam, please be quiet today."},{"pattern":"Noun にて","meaning":"Expresses location or means; 'at', 'in', 'by', 'with'.","formation":"Noun + にて","examples":[{"jp":"駅前広場にてイベントが開催されます。","en":"An event will be held at the station square.","romaji":"Ekimae hiroba nite ibento ga kaisai saremasu."},{"jp":"ホテルにて会議が行われます。","en":"The meeting will take place at the hotel.","romaji":"Hoteru nite kaigi ga okonawaremasu."},{"jp":"郵便局にて荷物を受け取りました。","en":"I received the package at the post office.","romaji":"Yubinkyoku nite nimotsu wo uketorimashita."},{"jp":"インターネットにて調べたら、答えが見つかりました。","en":"I searched online and found the answer.","romaji":"Intaanetto nite shirabetara, kotae ga mitsukarimashita."}],"example":"駅前広場にてイベントが開催されます。","exampleMeaning":"An event will be held at the station square."},{"pattern":"Noun の ことだから","meaning":"Used to provide a reason or explanation based on one's knowledge about the noun; 'since', 'because', 'knowing'.","formation":"Noun + のことだから","examples":[{"jp":"料理が得意な彼のことだから、美味しい料理を作ってくれるでしょう。","en":"Since he’s good at cooking, he’ll probably make delicious food.","romaji":"Ryouri ga tokui na kare no koto dakara, oishii ryouri wo tsukutte kureru deshou."},{"jp":"いつも遅刻する彼女のことだから、今日も遅れるかもしれない。","en":"Because she’s always late, she might be late again today.","romaji":"Itsumo chikoku suru kanojo no koto dakara, kyou mo okureru kamoshirenai."},{"jp":"安い店のことだから、たくさん売れるはずだ。","en":"Since it’s a cheap store, it should sell a lot.","romaji":"Yasui mise no koto dakara, takusan ureru hazu da."},{"jp":"ドラマ好きな彼のことだから、最新のドラマについて話すといいでしょう。","en":"Knowing he likes dramas, it’d be good to talk about the latest shows.","romaji":"Dorama suki na kare no koto dakara, saishin no dorama ni tsuite hanasu to ii deshou."}],"example":"料理が得意な彼のことだから、美味しい料理を作ってくれるでしょう。","exampleMeaning":"Since he’s good at cooking, he’ll probably make delicious food."},{"pattern":"Noun を はじめ","meaning":"Meaning 'starting with', 'including', 'not only... but also'.","formation":"Noun + をはじめ","examples":[{"jp":"日本料理をはじめ、さまざまな料理がこのレストランで楽しめます。","en":"You can enjoy various dishes in this restaurant, starting with Japanese cuisine.","romaji":"Nihon ryouri wo hajime, samazama na ryouri ga kono resutoran de tanoshimemasu."},{"jp":"彼は絵画をはじめ、彫刻や写真もコレクションしている。","en":"He collects not only paintings but also sculptures and photographs.","romaji":"Kare wa kaiga wo hajime, choukoku ya shashin mo korekushon shite iru."},{"jp":"京都をはじめ、日本のいくつかの都市で伝統的な祭りが行われている。","en":"Traditional festivals are held in several cities in Japan, including Kyoto.","romaji":"Kyouto wo hajime, Nihon no ikutsu ka no toshi de dentouteki na matsuri ga okonawarete iru."},{"jp":"太陽をはじめ、地球や火星などの惑星も太陽系に含まれている。","en":"Not only the Sun, but also planets such as Earth and Mars are included in the solar system.","romaji":"Taiyou wo hajime, chikyuu ya kasei nado no wakusei mo taiyoukei ni fukumarete iru."}],"example":"日本料理をはじめ、さまざまな料理がこのレストランで楽しめます。","exampleMeaning":"You can enjoy various dishes in this restaurant, starting with Japanese cuisine."},{"pattern":"Noun を はじめとして","meaning":"Expresses 'starting with', 'beginning with', or 'including'.","formation":"Noun + をはじめとして","examples":[{"jp":"東京をはじめとして、日本にはたくさんの観光スポットがあります。","en":"There are many tourist spots in Japan, starting with Tokyo.","romaji":"Tōkyō o hajime to shite, Nihon ni wa takusan no kankō supotto ga arimasu."},{"jp":"彼は、ピアノをはじめとして、たくさんの楽器を演奏できます。","en":"He can play many instruments, starting with piano.","romaji":"Kare wa, piano o hajime to shite, takusan no gakki o ensō dekimasu."},{"jp":"この本は手作りのガーゼマスクをはじめとして、便利な生活アイディアが満載です。","en":"This book is packed with useful life hacks, including how to make a handmade gauze mask.","romaji":"Kono hon wa tezukuri no gāze masuku o hajime to shite, benrina seikatsu aidea ga mansai desu."},{"jp":"そのショッピングモールには、ZARAをはじめとして、多くのブランドが集まっています。","en":"Many brands, including ZARA, gather in that shopping mall.","romaji":"Sono shoppingu mōru ni wa, ZARA o hajime to shite, ōku no burando ga atsumatte imasu."}],"example":"東京をはじめとして、日本にはたくさんの観光スポットがあります。","exampleMeaning":"There are many tourist spots in Japan, starting with Tokyo."},{"pattern":"Noun を はじめとする Noun","meaning":"Indicates a representative example of a group; 'starting with', 'including', 'such as'.","formation":"Noun1 を はじめとする Noun2","examples":[{"jp":"彼はフランス語をはじめとする外国語が話せる。","en":"He can speak foreign languages, starting with French.","romaji":"Kare wa furansugo o hajime to suru gaikokugo ga hanaseru."},{"jp":"このコンサートには、BTSをはじめとする人気アーティストが出演する予定です。","en":"This concert is scheduled to feature popular artists, including BTS.","romaji":"Kono konsāto ni wa, BTS o hajime to suru ninki ātisuto ga shutsuen suru yotei desu."},{"jp":"彼女は魚をはじめとする海の幸が大好きだ。","en":"She loves seafood, starting with fish.","romaji":"Kanojo wa sakana o hajime to suru umi no sachi ga daisuki da."},{"jp":"この図書館には、子供向けの本をはじめとするさまざまなジャンルの本があります。","en":"This library has various genres of books, including children's books.","romaji":"Kono toshokan ni wa, kodomomuke no hon o hajime to suru samazama na janru no hon ga arimasu."}],"example":"彼はフランス語をはじめとする外国語が話せる。","exampleMeaning":"He can speak foreign languages, starting with French."},{"pattern":"Noun を めぐって","meaning":"Concerning; with regard to; about","formation":"Noun + を + めぐって","examples":[{"jp":"環境問題をめぐって、多くの議論が行われています。","en":"Many discussions are held concerning environmental issues.","romaji":"Kankyō mondai o megutte, ōku no giron ga okonawarete imasu."},{"jp":"彼の死をめぐって、いくつかの陰謀説が浮かび上がっている。","en":"Several conspiracy theories have emerged regarding his death.","romaji":"Kare no shi o megutte, ikutsuka no inbōsetsu ga ukabiagatte iru."},{"jp":"昇給をめぐって会社と労働組合が話し合いをしています。","en":"The company and the labor union are having discussions about pay raises.","romaji":"Shōkyū o megutte kaisha to rōdō kumiai ga hanashiai o shite imasu."},{"jp":"この映画をめぐって、賛否両論が存在している。","en":"There are both pros and cons regarding this movie.","romaji":"Kono eiga o megutte, sanpi ryōron ga sonzai shite iru."}],"example":"環境問題をめぐって、多くの議論が行われています。","exampleMeaning":"Many discussions are held concerning environmental issues."},{"pattern":"Noun を めぐる Noun","meaning":"Indicate a situation or event revolving around a particular noun; 'concerning', 'regarding', 'pertaining to'.","formation":"Noun1 + を + めぐる + Noun2","examples":[{"jp":"この事件をめぐる議論が続いています。","en":"The debate concerning this incident continues.","romaji":"Kono jiken o meguru giron ga tsudzuite imasu."},{"jp":"環境問題をめぐる国際会議が開かれます。","en":"An international conference regarding environmental issues will be held.","romaji":"Kankyō mondai o meguru kokusai kaigi ga hirakaremasu."},{"jp":"彼の突然の辞任をめぐるうわさが広がっている。","en":"Rumors are spreading concerning his sudden resignation.","romaji":"Kare no totsuzen no jinin o meguru uwasa ga hirogatte iru."},{"jp":"映画祭をめぐる活動が多くなっています。","en":"There are increasing activities surrounding the film festival.","romaji":"Eigashai o meguru katsudō ga ōku natte imasu."}],"example":"この事件をめぐる議論が続いています。","exampleMeaning":"The debate concerning this incident continues."},{"pattern":"Noun を もとに","meaning":"Based on; drawing from; using as a reference.","formation":"Noun + をもとに","examples":[{"jp":"この映画は実話をもとに作られました。","en":"This movie was made based on a true story.","romaji":"Kono eiga wa jitsuwa o moto ni tsukuraremashita."},{"jp":"彼の経験をもとにアドバイスが必要だ。","en":"Advice is needed based on his experience.","romaji":"Kare no keiken o moto ni adobaisu ga hitsuyō da."},{"jp":"データをもとに分析を行いました。","en":"I performed an analysis based on the data.","romaji":"Dēta o moto ni bunseki o okonaimashita."},{"jp":"世界中の美術館をもとにコレクションを作りました。","en":"I created a collection based on art galleries all over the world.","romaji":"Sekaijū no bijutsukan o moto ni korekushon o tsukurimashita."}],"example":"この映画は実話をもとに作られました。","exampleMeaning":"This movie was made based on a true story."},{"pattern":"Noun を もとにして","meaning":"Based on; using; utilizing.","formation":"Noun + をもとにして","examples":[{"jp":"彼の意見をもとにして、計画を変更しました。","en":"Based on his opinion, we changed the plan.","romaji":"Kare no iken o moto ni shite, keikaku o henkō shimashita."},{"jp":"この小説は実話をもとにして書かれています。","en":"This novel is written based on a true story.","romaji":"Kono shōsetsu wa jitsuwa o moto ni shite kakarete imasu."},{"jp":"資料をもとにして、レポートを作成しました。","en":"I created the report based on the materials.","romaji":"Shiryō o moto ni shite, repōto o sakusei shimashita."},{"jp":"過去の成功例をもとにして、新しいプロジェクトを進める予定です。","en":"We plan to proceed with the new project based on past successful examples.","romaji":"Kako no seikōrei o moto ni shite, atarashii purojekuto o susumeru yotei desu."}],"example":"彼の意見をもとにして、計画を変更しました。","exampleMeaning":"Based on his opinion, we changed the plan."},{"pattern":"Verb ことなく","meaning":"Means 'without doing', 'not doing', or 'without happening'.","formation":"Verb-stem + ことなく","examples":[{"jp":"彼女は泣くことなく帰ってしまいました。","en":"She went home without crying.","romaji":"Kanojo wa naku koto naku kaette shimaimashita."},{"jp":"彼は注意することなく突然出かけた。","en":"He suddenly left without giving any warning.","romaji":"Kare wa chūi suru koto naku totsuzen dekaketa."},{"jp":"山田さんは誰にも話すことなく会社を辞めました。","en":"Mr. Yamada quit the company without talking to anyone.","romaji":"Yamada-san wa dare ni mo hanasu koto naku kaisha o yamemashita."},{"jp":"２０年間、病気になることなく働いています。","en":"I have been working for 20 years without getting sick.","romaji":"Nijūnenkan, byōki ni naru koto naku hataraite imasu."}],"example":"彼女は泣くことなく帰ってしまいました。","exampleMeaning":"She went home without crying."},{"pattern":"Verb ないことには Verb ない","meaning":"Express that something cannot be done without meeting a certain condition.","formation":"Verb-ない + ことには + Verb-ない","examples":[{"jp":"薬を飲まないことには、病気が治らない。","en":"Unless you take the medicine, the illness won't get better.","romaji":"Kusuri o nomanai koto ni wa, byōki ga naoranai."},{"jp":"この問題によく考えないことには、解決できない。","en":"Unless you think carefully about this problem, you can't solve it.","romaji":"Kono mondai ni yoku kangaenai koto ni wa, kaiketsu dekinai."},{"jp":"練習をしないことには、スキルが上達しない。","en":"Unless you practice, your skills won't improve.","romaji":"Renshū o shinai koto ni wa, sukiru ga jōtatsu shinai."},{"jp":"手続きをしないことには、新しいパスポートがもらえない。","en":"Unless you go through the procedures, you can't get a new passport.","romaji":"Tetsuzuki o shinai koto ni wa, atarashii pasupōto ga moraenai."}],"example":"薬を飲まないことには、病気が治らない。","exampleMeaning":"Unless you take the medicine, the illness won't get better."},{"pattern":"～あげく","meaning":"Expresses the outcome of a series of actions or events; 'in the end', 'finally', 'after'.","formation":"Verb-た + あげく / Noun + の + あげく","examples":[{"jp":"長い時間待ったあげく、電車が来なかった。","en":"After waiting a long time, in the end, the train didn't come.","romaji":"Nagai jikan matta ageku, densha ga konakatta."},{"jp":"いろいろな方法を試したあげく、成功した。","en":"After trying various methods, I finally succeeded.","romaji":"Iroiro na hōhō o tameshita ageku, seikō shita."},{"jp":"彼は失敗のあげく、会社を辞める決心をした。","en":"In the end, after his failures, he decided to quit the company.","romaji":"Kare wa shippai no ageku, kaisha o yameru kesshin o shita."},{"jp":"彼女は長い間悩んだあげく、その仕事を断った。","en":"After worrying for a long time, she finally turned down the job.","romaji":"Kanojo wa nagai aida nayanda ageku, sono shigoto o kotowatta."}],"example":"長い時間待ったあげく、電車が来なかった。","exampleMeaning":"After waiting a long time, in the end, the train didn't come."},{"pattern":"～あまり (〜amari)","meaning":"Expresses the result of doing something excessively or beyond a certain point.","formation":"Verb-ます stem + あまり, い-Adjective + あまり, な-Adjective + のあまり, Noun + のあまり","examples":[{"jp":"昨日は疲れすぎたあまり、朝まで眠り続けました。","en":"Yesterday, I was so tired that I slept until morning.","romaji":"Kinō wa tsukare-sugita amari, asa made nemuri tsuzukemashita."},{"jp":"彼女はうれしいあまり、泣き出してしまった。","en":"She was so happy that she ended up crying.","romaji":"Kanojo wa ureshii amari, nakidashite shimatta."},{"jp":"彼は安全を確認するあまり、何回もドアをチェックしている。","en":"He is so concerned about safety that he checks the door many times.","romaji":"Kare wa anzen o kakunin suru amari, nankai mo doa o chekku shite iru."},{"jp":"寒さのあまり、彼は震えが止まらなかった。","en":"It was so cold that he couldn't stop shivering.","romaji":"Samusa no amari, kare wa furue ga tomaranakatta."}],"example":"昨日は疲れすぎたあまり、朝まで眠り続けました。","exampleMeaning":"Yesterday, I was so tired that I slept until morning."},{"pattern":"～うちに (〜uchi ni)","meaning":"Expresses doing something while a certain condition still holds; 'while', 'before', 'as long as'.","formation":"Verb-casual + うちに, い-Adjective + うちに, な-Adjective + なうちに, Noun + のうちに","examples":[{"jp":"元気なうちに、旅行を楽しんでください。","en":"Enjoy traveling while you are healthy.","romaji":"Genki na uchi ni, ryokō o tanoshinde kudasai."},{"jp":"若いうちに、いろいろなことを学ぶべきだ。","en":"One should learn various things while they are young.","romaji":"Wakai uchi ni, iroiro na koto o manabu beki da."},{"jp":"子供が寝ているうちに、夕食の準備をしましょう。","en":"Let's prepare dinner while the kids are sleeping.","romaji":"Kodomo ga nete iru uchi ni, yūshoku no junbi o shimashō."},{"jp":"雨が降らないうちに、家に帰りましょう。","en":"Let's go home before it starts raining.","romaji":"Ame ga furanai uchi ni, ie ni kaerimashō."}],"example":"元気なうちに、旅行を楽しんでください。","exampleMeaning":"Enjoy traveling while you are healthy."},{"pattern":"～がい (〜gai)","meaning":"Expresses 'worth doing' for verbs.","formation":"Verb-stem + がい","examples":[{"jp":"この本は読みがいがあります。","en":"This book is worth reading.","romaji":"Kono hon wa yomi-gai ga arimasu."},{"jp":"早起きしがいがあると思いますよ。","en":"I think it's worth waking up early.","romaji":"Hayaoki shigai ga aru to omoimasu yo."},{"jp":"長い時間をかけがいのある仕事だ。","en":"It's a job worth spending a long time on.","romaji":"Nagai jikan o kake-gai no aru shigoto da."},{"jp":"彼とは話しがいがあるでしょう。","en":"It's worth talking to him.","romaji":"Kare to wa hanashi-gai ga aru deshō."}],"example":"この本は読みがいがあります。","exampleMeaning":"This book is worth reading."},{"pattern":"～かいがあって (〜kaiga atte)","meaning":"Used to express that an effort is worth it or has value; 'to be worth the effort' or 'to pay off'.","formation":"Verb-past + かいがあって / Noun + の + かいがあって","examples":[{"jp":"毎日勉強したかいがあって、テストに合格しました。","en":"Studying every day paid off—I passed the test.","romaji":"Mainichi benkyō shita kai ga atte, tesuto ni gōkaku shimashita."},{"jp":"練習のかいがあって、試合に勝つことができた。","en":"The practice paid off, and we were able to win the match.","romaji":"Renshū no kai ga atte, shiai ni katsu koto ga dekita."},{"jp":"雨の中を走ってきたかいがあって、電車に間に合った。","en":"Running in the rain was worth it, as I made it to the train on time.","romaji":"Ame no naka o hashitte kita kai ga atte, densha ni maniatta."},{"jp":"早起きして掃除をしたかいがあって、部屋がきれいになった。","en":"Waking up early to clean paid off; the room is now spotless.","romaji":"Hayaoki shite sōji o shita kai ga atte, heya ga kirei ni natta."}],"example":"毎日勉強したかいがあって、テストに合格しました。","exampleMeaning":"Studying every day paid off—I passed the test."},{"pattern":"～かいもなく (〜kai mo naku)","meaning":"Expresses the meaning of 'without worth', 'in vain', 'fruitless'.","formation":"Verb-た + かいもなく / Noun + の + かいもなく","examples":[{"jp":"長い間苦労したかいもなく、失敗してしまった。","en":"I struggled for a long time, but in the end, it was all in vain and I failed.","romaji":"Nagai aida kurō shita kai mo naku, shippai shite shimatta."},{"jp":"このプロジェクトにたくさん時間をかけたかいもなく、うまくいかなかった。","en":"I spent a lot of time on this project, but it ended fruitlessly.","romaji":"Kono purojekuto ni takusan jikan o kaketa kai mo naku, umaku ikanakatta."},{"jp":"助けを求めたかいもなく、誰も来なかった。","en":"He asked for help, but it was in vain as no one came.","romaji":"Tasuke o motometa kai mo naku, dare mo konakatta."},{"jp":"色々な方法でダイエットを試みたかいもなく、全然痩せなかった。","en":"I tried various diet methods, but it was all for nothing—I didn't lose any weight.","romaji":"Iroirona hōhō de daietto o kokoromita kai mo naku, zenzen yasenakatta."}],"example":"長い間苦労したかいもなく、失敗してしまった。","exampleMeaning":"I struggled for a long time, but in the end, it was all in vain and I failed."},{"pattern":"～かける (〜kakeru)","meaning":"Indicates a process or action is 'in progress' or 'halfway'.","formation":"Verb-stem + かける","examples":[{"jp":"彼女は食べかけのリンゴを置いて出かけた。","en":"She left a partially eaten apple and went out.","romaji":"Kanojo wa tabe-kake no ringo o oite dekaketa."},{"jp":"子供たちはやりかけの宿題を机の上に残した。","en":"The children left their half-finished homework on the desk.","romaji":"Kodomotachi wa yari-kake no shukudai o tsukue no ue ni nokoshita."},{"jp":"読みかけの本を夜になると探す。","en":"I look for the book I started reading once night comes.","romaji":"Yomi-kake no hon o yoru ni naru to sagasu."},{"jp":"オフィスには、作りかけの書類がたくさんある。","en":"There are a lot of documents in the process of being created in the office.","romaji":"Ofisu ni wa, tsukuri-kake no shorui ga takusan aru."}],"example":"彼女は食べかけのリンゴを置いて出かけた。","exampleMeaning":"She left a partially eaten apple and went out."},{"pattern":"～がち (〜gachi)","meaning":"Expresses that something tends to occur frequently or habitually.","formation":"Verb-ます stem + がち / い-Adjective stem + がち / な-Adjective stem + がち","examples":[{"jp":"彼は風邪を引きがちです。","en":"He tends to catch colds easily.","romaji":"Kare wa kaze o hiki-gachi desu."},{"jp":"この地域は雨が降りがちです。","en":"This area tends to get a lot of rain.","romaji":"Kono chiiki wa ame ga furi-gachi desu."},{"jp":"彼女は忘れ物をしがちです。","en":"She tends to forget things.","romaji":"Kanojo wa wasuremono o shi-gachi desu."},{"jp":"私は遅刻しがちなので、もっと早く起きないといけません。","en":"I tend to be late, so I need to wake up earlier.","romaji":"Watashi wa chikoku shi-gachi na no de, motto hayaku okinai to ikemasen."}],"example":"彼は風邪を引きがちです。","exampleMeaning":"He tends to catch colds easily."},{"pattern":"～か～ないかのうちに (〜ka〜naika no uchi ni)","meaning":"Expresses an action that occurs immediately after another action; 'as soon as', 'no sooner than', 'the moment'.","formation":"Verb-casual + か + Verb-negative form + かのうちに","examples":[{"jp":"駅に着くか着かないかのうちに、雨が降り出した。","en":"No sooner had I arrived at the station than it started raining.","romaji":"Eki ni tsuku ka tsukanai ka no uchi ni, ame ga furidashita."},{"jp":"ケータイを買うか買わないかのうちに、新しいモデルが発売された。","en":"As soon as I decided to buy the cell phone, a new model was released.","romaji":"Keitai o kau ka kawanai ka no uchi ni, atarashii moderu ga hatsubai sareta."},{"jp":"彼が家を出るか出ないかのうちに、電話が鳴った。","en":"The moment he left the house, the phone rang.","romaji":"Kare ga ie o deru ka denai ka no uchi ni, denwa ga natta."},{"jp":"パーティーが始まるか始まらないかのうちに、彼女が泣き出した。","en":"As soon as the party began, she started crying.","romaji":"Pātī ga hajimaru ka hajimaranai ka no uchi ni, kanojo ga nakidashita."}],"example":"駅に着くか着かないかのうちに、雨が降り出した。","exampleMeaning":"No sooner had I arrived at the station than it started raining."},{"pattern":"～かねない (〜kane nai)","meaning":"Express the likelihood of a negative outcome or consequence.","formation":"Verb-stem + かねない","examples":[{"jp":"彼はあまりにも無責任で、約束を破りかねない。","en":"He is so irresponsible that he might break his promise.","romaji":"Kare wa amarini mo musekinin de, yakusoku o yaburi-kane nai."},{"jp":"注意しないと、事故を起こしかねない。","en":"If you don't pay attention, you might cause an accident.","romaji":"Chūi shinai to, jiko o okoshi-kane nai."},{"jp":"このアプリはバグが多いので、クラッシュしかねない。","en":"Since this app has many bugs, it might crash.","romaji":"Kono apuri wa bagu ga ōi no de, kurasshu shi-kane nai."},{"jp":"彼女は緊張しているので、失敗しかねない。","en":"She's so nervous that she might fail.","romaji":"Kanojo wa kinchō shite iru no de, shippai shi-kane nai."}],"example":"彼はあまりにも無責任で、約束を破りかねない。","exampleMeaning":"He is so irresponsible that he might break his promise."},{"pattern":"～かねる (〜kaneru)","meaning":"Express inability or impossibility of doing an action (often as a polite refusal).","formation":"Verb-ます stem + かねる","examples":[{"jp":"その問題は難しいので、私には解決しかねます。","en":"Since that problem is difficult, I cannot solve it.","romaji":"Sono mondai wa muzukashii no de, watashi ni wa kaiketsu shi-kanemasu."},{"jp":"彼の言っていることが真実かどうか判断しかねます。","en":"I cannot judge whether what he is saying is true or not.","romaji":"Kare no itte iru koto ga shinjitsu ka dō ka handan shi-kanemasu."},{"jp":"彼女が来るかどうか今すぐには分かりかねます。","en":"I cannot immediately know whether she will come or not.","romaji":"Kanojo ga kuru ka dō ka ima sugu ni wa wakari-kanemasu."},{"jp":"詳しい内容については説明しかねます。","en":"I cannot explain the details.","romaji":"Kuwashii naiyō ni tsuite wa setsumei shi-kanemasu."}],"example":"その問題は難しいので、私には解決しかねます。","exampleMeaning":"Since that problem is difficult, I cannot solve it."},{"pattern":"～かのようだ (〜ka no you da)","meaning":"Express a similarity or comparison; 'as if', 'like', 'as though'.","formation":"Verb-casual + かのようだ, い-Adjective + かのようだ, な-Adjective + であるかのようだ, Noun + であるかのようだ","examples":[{"jp":"彼は犬が怖いかのようだ。","en":"He seems as if he is scared of dogs.","romaji":"Kare wa inu ga kowai ka no you da."},{"jp":"この部屋は寒いかのようだ。","en":"This room feels as if it's cold.","romaji":"Kono heya wa samui ka no you da."},{"jp":"彼女は有名人であるかのようだ。","en":"She acts as though she is a celebrity.","romaji":"Kanojo wa yuumeijin de aru ka no you da."},{"jp":"彼は子供であるかのようだ。","en":"He acts as if he's a child.","romaji":"Kare wa kodomo de aru ka no you da."}],"example":"彼は犬が怖いかのようだ。","exampleMeaning":"He seems as if he is scared of dogs."},{"pattern":"～か～まいか (〜ka 〜maika)","meaning":"Used to express a dilemma or indecision between two options or actions.","formation":"Verb-volitional + か + Verb-volitional + まいか, い-Adjective + であるか + い-Adjective + であるまいか, な-Adjective + であるか + な-Adjective + であるまいか, Noun + であるか + Noun + であるまいか","examples":[{"jp":"このプロジェクトを引き受けようか引き受けまいか、まだ決めていない。","en":"I haven't decided whether to take on this project or not.","romaji":"Kono purojekuto o hikiukeyou ka hikiukemai ka, mada kimete inai."},{"jp":"彼が成功しようか成功するまいか、今は予測できない。","en":"Whether he will succeed or not is unpredictable at the moment.","romaji":"Kare ga seikou shiyou ka seikou suru maika, ima wa yosoku dekinai."},{"jp":"この問題は簡単であるか難しいであるまいか、意見が分かれている。","en":"Opinions are divided on whether this problem is simple or difficult.","romaji":"Kono mondai wa kantan de aru ka muzukashii de aru maika, iken ga wakarete iru."},{"jp":"彼はリーダーであるかフォロワーであるまいか、自分で選ぶべきだ。","en":"He should choose for himself whether he is a leader or a follower.","romaji":"Kare wa riidā de aru ka forowā de aru maika, jibun de erabu beki da."}],"example":"このプロジェクトを引き受けようか引き受けまいか、まだ決めていない。","exampleMeaning":"I haven't decided whether to take on this project or not."},{"pattern":"～からこそ (〜kara koso)","meaning":"Express the emphasis on the reason; 'precisely because', 'it is precisely because'.","formation":"Verb-casual + からこそ, い-Adjective + からこそ, な-Adjective + だからこそ, Noun + だからこそ","examples":[{"jp":"失敗したからこそ、成功の意味がわかる。","en":"It is precisely because I failed that I understand the meaning of success.","romaji":"Shippai shita kara koso, seikou no imi ga wakaru."},{"jp":"苦しかったからこそ、今日の私がある。","en":"It is precisely because I went through hardships that I am who I am today.","romaji":"Kurushikatta kara koso, kyou no watashi ga aru."},{"jp":"彼は親切だからこそ、人気がある。","en":"He is popular precisely because he is kind.","romaji":"Kare wa shinsetsu da kara koso, ninki ga aru."},{"jp":"昔の経験があるからこそ、その問題がよく理解できる。","en":"I can understand that problem well precisely because I have past experience.","romaji":"Mukashi no keiken ga aru kara koso, sono mondai ga yoku rikai dekiru."}],"example":"失敗したからこそ、成功の意味がわかる。","exampleMeaning":"It is precisely because I failed that I understand the meaning of success."},{"pattern":"〜からして (〜kara shite)","meaning":"Expresses that something is exceptional, unusual, or negative based on a particular aspect or point.","formation":"Noun + からして","examples":[{"jp":"彼の顔つきからして、何か悪いことがあったのだろう。","en":"From his facial expression, something bad must have happened.","romaji":"Kare no kaotsuki kara shite, nanika warui koto ga atta no darou."},{"jp":"この料理の見た目からして、おいしくなさそうだ。","en":"Judging from the appearance of this dish, it doesn't look delicious.","romaji":"Kono ryouri no mitame kara shite, oishikunasa sou da."},{"jp":"彼女の試験成績からして、合格するのは難しいでしょう。","en":"Considering her test scores, it will be difficult for her to pass.","romaji":"Kanojo no shiken seiseki kara shite, goukaku suru no wa muzukashii deshou."},{"jp":"その映画のタイトルからして、面白くないと思う。","en":"Judging from the title of the movie, I think it's not interesting.","romaji":"Sono eiga no taitoru kara shite, omoshirokunai to omou."}],"example":"彼の顔つきからして、何か悪いことがあったのだろう。","exampleMeaning":"From his facial expression, something bad must have happened."},{"pattern":"～からすると (〜kara suru to)","meaning":"Expresses a judgment or evaluation based on a certain standard; 'from this perspective', 'considering', 'judging from'.","formation":"Noun + からすると","examples":[{"jp":"経験からすると、この仕事は難しいでしょう。","en":"Considering their experience, this job might be difficult.","romaji":"Keiken kara suru to, kono shigoto wa muzukashii deshou."},{"jp":"評判からすると、あのレストランはとても美味しいです。","en":"Judging from the reputation, that restaurant is very delicious.","romaji":"Hyouban kara suru to, ano resutoran wa totemo oishii desu."},{"jp":"価格からすると、この商品は高品質のものと思われます。","en":"Considering the price, this product seems to be of high quality.","romaji":"Kakaku kara suru to, kono shouhin wa kouhinshitsu no mono to omowaremasu."},{"jp":"このエリアですが、交通の便からすると、便利です。","en":"As for this area, considering the transportation convenience, it's convenient.","romaji":"Kono eria desu ga, koutsuu no ben kara suru to, benri desu."}],"example":"経験からすると、この仕事は難しいでしょう。","exampleMeaning":"Considering their experience, this job might be difficult."},{"pattern":"～からといって (〜kara to itte)","meaning":"Expresses 'just because...doesn't mean' or 'even though...not necessarily'.","formation":"Verb-casual + からといって, い-Adjective + からといって, な-Adjective + だからといって, Noun + だからといって","examples":[{"jp":"雨が降ったからといって、試合が中止になるわけではありません。","en":"Just because it rained doesn't mean the game will be canceled.","romaji":"Ame ga futta kara to itte, shiai ga chuushi ni naru wake de wa arimasen."},{"jp":"彼が有名だからといって、彼の意見がいつも正しいわけではない。","en":"Just because he is famous doesn't mean his opinions are always correct.","romaji":"Kare ga yuumei da kara to itte, kare no iken ga itsumo tadashii wake de wa nai."},{"jp":"このスープが辛いからといって、全ての人が辛いと感じるわけではない。","en":"Just because this soup is spicy doesn't mean everyone will find it spicy.","romaji":"Kono suupu ga karai kara to itte, subete no hito ga karai to kanjiru wake de wa nai."},{"jp":"彼女が泣いているからといって、悲しいわけではないかもしれない。","en":"Just because she is crying doesn't necessarily mean she's sad.","romaji":"Kanojo ga naiteiru kara to itte, kanashii wake de wa nai kamoshirenai."}],"example":"雨が降ったからといって、試合が中止になるわけではありません。","exampleMeaning":"Just because it rained doesn't mean the game will be canceled."},{"pattern":"～から～にかけて (〜kara 〜ni kakete)","meaning":"Expresses a range of time, space, or quantities; 'from...to', 'between...and', 'over'.","formation":"Noun 1 + から + Noun 2 + にかけて","examples":[{"jp":"午前９時から午後５時にかけて、仕事をしています。","en":"I work from 9 in the morning to 5 in the evening.","romaji":"Gozen ku-ji kara gogo go-ji ni kakete, shigoto wo shite imasu."},{"jp":"東京から大阪にかけて、新幹線が走っています。","en":"The bullet train runs from Tokyo to Osaka.","romaji":"Toukyou kara Oosaka ni kakete, shinkansen ga hashitte imasu."},{"jp":"春から夏にかけて、花がたくさん咲いています。","en":"Many flowers bloom between spring and summer.","romaji":"Haru kara natsu ni kakete, hana ga takusan saite imasu."},{"jp":"２０歳から３０歳にかけて、多くの人が大学を卒業し、仕事に就くことが一般的です。","en":"It is common for many people to graduate from university and start working between the ages of 20 and 30.","romaji":"Hatachi kara sanjuu-sai ni kakete, ooku no hito ga daigaku wo sotsugyou shi, shigoto ni tsuku koto ga ippan-teki desu."}],"example":"午前９時から午後５時にかけて、仕事をしています。","exampleMeaning":"I work from 9 in the morning to 5 in the evening."},{"pattern":"～からには (〜kara niwa)","meaning":"Express a sense of responsibility or determination; 'since', 'now that', 'if'.","formation":"Noun + だ + からには, な-Adjective + だ + からには, い-Adjective + からには, Verb-casual + からには","examples":[{"jp":"試験に合格したからには、一所懸命働かなければならない。","en":"Since I passed the exam, I have to work hard.","romaji":"Shiken ni goukaku shita kara niwa, isshokenmei hatarakanakereba naranai."},{"jp":"約束したからには、守らなければなりません。","en":"Since I made a promise, I must keep it.","romaji":"Yakusoku shita kara niwa, mamoranakereba narimasen."},{"jp":"この映画が面白いからには、友達にも見せたい。","en":"Since this movie is interesting, I want to show it to my friends too.","romaji":"Kono eiga ga omoshiroi kara niwa, tomodachi ni mo misetai."},{"jp":"彼女が助けを求めたからには、手伝わなければならない。","en":"Since she asked for help, I must help her.","romaji":"Kanojo ga tasuke wo motometa kara niwa, tetsudawanakereba naranai."}],"example":"試験に合格したからには、一所懸命働かなければならない。","exampleMeaning":"Since I passed the exam, I have to work hard."},{"pattern":"～から見ると (〜kara miru to)","meaning":"Express a perspective or point of view; 'from the standpoint of', 'in terms of', 'from the perspective of'.","formation":"Noun + から見ると","examples":[{"jp":"費用から見ると、このプランはお得です。","en":"In terms of cost, this plan is a good deal.","romaji":"Hiyou kara miru to, kono puran wa otoku desu."},{"jp":"彼女の意見から見ると、社長の決定は理解できる。","en":"From her perspective, the president's decision is understandable.","romaji":"Kanojo no iken kara miru to, shachou no kettei wa rikai dekiru."},{"jp":"実力から見ると、彼はチームで最も優れている。","en":"In terms of ability, he is the best in the team.","romaji":"Jitsuryoku kara miru to, kare wa chiimu de mottomo sugurete iru."},{"jp":"健康面から見ると、この食品は良くない。","en":"From the standpoint of health, this food is not good.","romaji":"Kenkoumen kara miru to, kono shokuhin wa yokunai."}],"example":"費用から見ると、このプランはお得です。","exampleMeaning":"In terms of cost, this plan is a good deal."},{"pattern":"～から言うと (〜kara iuto)","meaning":"Express a judgment or opinion based on a specific criterion; 'speaking from', 'in terms of', 'from the viewpoint of'.","formation":"Noun + から言うと (common), [Verb-casual / Adjective + から言って] (less common)","examples":[{"jp":"値段から言うと、この商品が最もお得です。","en":"Speaking from the viewpoint of price, this product is the best deal.","romaji":"Nedan kara iuto, kono shouhin ga mottomo otoku desu."},{"jp":"味から言って、このレストランはおいしいと思います。","en":"In terms of taste, I think this restaurant is delicious.","romaji":"Aji kara itte, kono resutoran wa oishii to omoimasu."},{"jp":"便利さから言って、このアパートは最適な場所にあります。","en":"Speaking from the perspective of convenience, this apartment is in the best location.","romaji":"Benrisa kara itte, kono apaato wa saiteki na basho ni arimasu."},{"jp":"健康から言うと、毎日運動することが大切です。","en":"From the viewpoint of health, it is important to exercise every day.","romaji":"Kenkou kara iuto, mainichi undou suru koto ga taisetsu desu."}],"example":"値段から言うと、この商品が最もお得です。","exampleMeaning":"Speaking from the viewpoint of price, this product is the best deal."},{"pattern":"～くせに (〜kuse ni)","meaning":"Used to criticize someone for doing something contrary to what one would expect from their nature or situation.","formation":"Verb (casual) + くせに / い-Adjective + くせに / な-Adjective + な(or の) + くせに / Noun + の + くせに","examples":[{"jp":"彼はいつも遅刻してくるくせに、自分が待たされるのが嫌いだ。","en":"He’s always late, yet he hates being kept waiting.","romaji":"Kare wa itsumo chikoku shite kuru kuse ni, jibun ga matasareru no ga kirai da."},{"jp":"悪いなと言ってるくせに、また同じことを繰り返している。","en":"He says he's sorry, yet he keeps doing the same thing.","romaji":"Warui na to itteru kuse ni, mata onaji koto o kurikaeshite iru."},{"jp":"彼は背が高いくせに、バスケが下手だ。","en":"Despite being tall, he's bad at basketball.","romaji":"Kare wa se ga takai kuse ni, basuke ga heta da."},{"jp":"この店は有名なのくせに、サービスが悪い。","en":"Despite being famous, this store has poor service.","romaji":"Kono mise wa yuumei na no kuse ni, saabisu ga warui."}],"example":"彼はいつも遅刻してくるくせに、自分が待たされるのが嫌いだ。","exampleMeaning":"He’s always late, yet he hates being kept waiting."},{"pattern":"～ことから (〜koto kara)","meaning":"Indicates the reason or basis for something; 'because', 'since', 'due to'.","formation":"Verb-casual + ことから / い-Adjective + ことから / な-Adjective + なことから / Noun + のことから","examples":[{"jp":"彼は毎日運動することから、体が丈夫です。","en":"Because he exercises every day, he is physically strong.","romaji":"Kare wa mainichi undou suru koto kara, karada ga joubu desu."},{"jp":"この店のサービスがいいことから、いつも混んでいます。","en":"This store is always crowded because of its good service.","romaji":"Kono mise no saabisu ga ii koto kara, itsumo konde imasu."},{"jp":"彼女は親切なことから、みんなに好かれています。","en":"She’s well-liked by everyone due to her kindness.","romaji":"Kanojo wa shinsetsu na koto kara, minna ni sukarete imasu."},{"jp":"その会社の評判が良いことから、就職先として人気があります。","en":"Because that company’s reputation is good, it’s popular as a place to work.","romaji":"Sono kaisha no hyouban ga yoi koto kara, shuushoku-saki toshite ninki ga arimasu."}],"example":"彼は毎日運動することから、体が丈夫です。","exampleMeaning":"Because he exercises every day, he is physically strong."},{"pattern":"～ことに (〜koto ni)","meaning":"Used to express feelings or emotions about a situation, action, or outcome.","formation":"Verb-casual + ことに / い-Adjective + ことに / な-Adjective + なことに / Noun + のことに","examples":[{"jp":"彼が急に帰国することに驚いた。","en":"I was surprised that he suddenly returned to his home country.","romaji":"Kare ga kyuu ni kikoku suru koto ni odoroita."},{"jp":"彼女が優勝したことに感動した。","en":"I was moved by the fact that she won the championship.","romaji":"Kanojo ga yuushou shita koto ni kandou shita."},{"jp":"彼がいつも遅刻することに腹が立つ。","en":"I get angry that he is always late.","romaji":"Kare ga itsumo chikoku suru koto ni hara ga tatsu."},{"jp":"彼女がこんなに美しいことに気がつかなかった。","en":"I hadn’t realized how beautiful she was.","romaji":"Kanojo ga konna ni utsukushii koto ni ki ga tsukanakatta."}],"example":"彼が急に帰国することに驚いた。","exampleMeaning":"I was surprised that he suddenly returned to his home country."},{"pattern":"～ことになっている (〜koto ni natte iru)","meaning":"Expresses that something is supposed to be or has been decided (rule, plan, custom).","formation":"Verb-plain form + ことになっている / い-Adjective + ことになっている / な-Adjective + だ + ことになっている / Noun + だ + ことになっている","examples":[{"jp":"日本では、左側を運転することになっています。","en":"In Japan, it is decided that people drive on the left side.","romaji":"Nihon de wa, hidarigawa o unten suru koto ni natte imasu."},{"jp":"会社の規則では、制服を着ることになっている。","en":"According to the company rules, we are supposed to wear uniforms.","romaji":"Kaisha no kisoku de wa, seifuku o kiru koto ni natte iru."},{"jp":"彼女は明日結婚することになっています。","en":"She is supposed to get married tomorrow.","romaji":"Kanojo wa ashita kekkon suru koto ni natte imasu."},{"jp":"この商品は高品質だということになっています。","en":"It is said (or generally accepted) that this product is of high quality.","romaji":"Kono shouhin wa kouhinshitsu da to iu koto ni natte imasu."}],"example":"日本では、左側を運転することになっています。","exampleMeaning":"In Japan, it is decided that people drive on the left side."},{"pattern":"～さえ～ば (〜sae ~ba)","meaning":"Expresses that, as long as a certain condition is met, something else will follow; 'if only', 'provided that'.","formation":"Noun + さえ + Verb-conditional / Verb-ますstem + さえすれば / etc. (varies by part of speech)","examples":[{"jp":"お金さえあれば、幸せです。","en":"As long as I have money, I’m happy.","romaji":"Okane sae areba, shiawase desu."},{"jp":"試験に合格しさえすれば、卒業できます。","en":"If only I pass the exam, I can graduate.","romaji":"Shiken ni goukaku shi sae sureba, sotsugyou dekimasu."},{"jp":"野菜さえたくさん食べれば、母は喜びます。","en":"As long as I eat plenty of vegetables, my mother will be happy.","romaji":"Yasai sae takusan tabereba, haha wa yorokobimasu."},{"jp":"交通費さえ支払ってもらえれば、どこへでも行きます。","en":"As long as my transportation costs are covered, I’ll go anywhere.","romaji":"Koutsuuhi sae shiharatte moraereba, doko e demo ikimasu."}],"example":"お金さえあれば、幸せです。","exampleMeaning":"As long as I have money, I’m happy."},{"pattern":"～ざるを得ない (〜zaru wo enai)","meaning":"Have no choice but to; cannot help but.","formation":"Verb-ない form (drop ない) + ざるを得ない","examples":[{"jp":"この仕事は締め切りが近いので、残業せざるを得ない。","en":"Since the deadline is near, I have no choice but to work overtime.","romaji":"Kono shigoto wa shimekiri ga chikai no de, zangyou sezaru wo enai."},{"jp":"電車が遅れたため、タクシーに乗るざるを得なかった。","en":"Because the train was delayed, I had no choice but to take a taxi.","romaji":"Densha ga okureta tame, takushii ni noru zaru wo enakatta."},{"jp":"彼女の説明が納得できなかったが、とりあえず信じざるを得ない。","en":"I couldn’t really accept her explanation, but for now I have no choice but to believe her.","romaji":"Kanojo no setsumei ga nattoku dekinakatta ga, toriaezu shinjizaru wo enai."},{"jp":"この状況では、新しい計画を立て直さざるを得ない。","en":"In this situation, we have no choice but to revise the new plan.","romaji":"Kono joukyou de wa, atarashii keikaku wo tatenaosazaru wo enai."}],"example":"この仕事は締め切りが近いので、残業せざるを得ない。","exampleMeaning":"Since the deadline is near, I have no choice but to work overtime."},{"pattern":"～ずにはいられない (〜zu ni wa irarenai)","meaning":"Cannot help but; cannot resist doing; an irresistible urge.","formation":"Verb-ない form (drop ない) + ずにはいられない","examples":[{"jp":"この曲を聞くと、歌わずにはいられない。","en":"When I hear this song, I can’t help but sing.","romaji":"Kono kyoku o kiku to, utawazu ni wa irarenai."},{"jp":"彼女が泣いているのを見ると、慰めずにはいられない。","en":"When I see her crying, I can’t resist comforting her.","romaji":"Kanojo ga naite iru no o miru to, nagusamezu ni wa irarenai."},{"jp":"この小説は面白いので、読まずにはいられない。","en":"This novel is so interesting that I can’t help but read it.","romaji":"Kono shousetsu wa omoshiroi no de, yomazu ni wa irarenai."},{"jp":"彼はおいしい料理を前にすると、食べずにはいられない。","en":"When he’s faced with delicious food, he can’t help but eat it.","romaji":"Kare wa oishii ryouri o mae ni suru to, tabezu ni wa irarenai."}],"example":"この曲を聞くと、歌わずにはいられない。","exampleMeaning":"When I hear this song, I can’t help but sing."},{"pattern":"～そうにない (〜sou ni nai)","meaning":"Express the unlikelihood of something happening; 'not likely', 'doesn't seem'.","formation":"Verb-stem + そうにない / い-Adjective (drop い) + そうにない / な-Adjective + そうにない","examples":[{"jp":"この雨は止みそうにない。","en":"It doesn't seem like this rain will stop.","romaji":"Kono ame wa yami sou ni nai."},{"jp":"彼が試験に合格しそうにない。","en":"It doesn't look like he'll pass the exam.","romaji":"Kare ga shiken ni goukaku shi sou ni nai."},{"jp":"この料理がおいしそうにない。","en":"This dish doesn't look like it will be tasty.","romaji":"Kono ryouri ga oishisou ni nai."},{"jp":"この部屋はきれいそうにない。","en":"This room doesn't seem likely to be clean.","romaji":"Kono heya wa kirei sou ni nai."}],"example":"この雨は止みそうにない。","exampleMeaning":"It doesn't seem like this rain will stop."},{"pattern":"～たかと思ったら (〜ta ka to omottara)","meaning":"Express a sequence of events happening in quick succession; 'as soon as', 'no sooner than'.","formation":"Verb-た form + かと思ったら","examples":[{"jp":"電話をかけたかと思ったら、すぐに彼女が出た。","en":"No sooner had I called than she picked up.","romaji":"Denwa o kaketa ka to omottara, sugu ni kanojo ga deta."},{"jp":"離陸したかと思ったら、飛行機が揺れ始めた。","en":"As soon as we took off, the plane started shaking.","romaji":"Ririku shita ka to omottara, hikouki ga yure hajimeta."},{"jp":"買い物に行ったかと思ったら、雨が降ってきた。","en":"No sooner had I gone shopping than it began to rain.","romaji":"Kaimono ni itta ka to omottara, ame ga futte kita."},{"jp":"仕事を終わったかと思ったら、上司が追加の仕事を持ってきた。","en":"As soon as I finished work, my boss brought more tasks.","romaji":"Shigoto o owatta ka to omottara, joushi ga tsuika no shigoto o motte kita."}],"example":"電話をかけたかと思ったら、すぐに彼女が出た。","exampleMeaning":"No sooner had I called than she picked up."},{"pattern":"～たきり (〜takiri)","meaning":"Express 'since then' or 'after'; used to indicate that an action occurred once and has not been repeated or that a state has continued since a certain event or time.","formation":"Verb-past + きり","examples":[{"jp":"彼は会社を辞めたきり、連絡がない。","en":"Ever since he quit the company, there's been no contact.","romaji":"Kare wa kaisha o yameta kiri, renraku ga nai."},{"jp":"昨日の朝、メールを送ったきり、返事がない。","en":"I sent an email yesterday morning, and there's been no reply since then.","romaji":"Kinō no asa, mēru o okutta kiri, henji ga nai."},{"jp":"子供のころ海に行ったきりで、もう20年になる。","en":"It's been 20 years since I last went to the sea as a child.","romaji":"Kodomo no koro umi ni itta kiri de, mō nijūnen ni naru."},{"jp":"彼女と別れたきり、彼女のことを考えなくなった。","en":"Ever since I broke up with her, I stopped thinking about her.","romaji":"Kanojo to wakareta kiri, kanojo no koto o kangaenaku natta."}],"example":"彼は会社を辞めたきり、連絡がない。","exampleMeaning":"Ever since he quit the company, there's been no contact."},{"pattern":"～だけあって (〜dake atte)","meaning":"Expresses that something is as expected or deserves its reputation.","formation":"Verb-casual + だけあって, い-Adjective + だけあって, な-Adjective + なだけあって, Noun + だけあって","examples":[{"jp":"彼は日本語が上手だけあって、日本人のように話すことができる。","en":"As expected from his good Japanese skills, he can speak like a native.","romaji":"Kare wa nihongo ga jōzu dake atte, nihonjin no yō ni hanasu koto ga dekiru."},{"jp":"このレストランは有名だけあって、料理がとても美味しい。","en":"No wonder this restaurant is famous; the food is very delicious.","romaji":"Kono resutoran wa yūmei dake atte, ryōri ga totemo oishii."},{"jp":"彼女は経験豊富なだけあって、その問題を簡単に解決できた。","en":"It's natural that she's experienced; she solved the problem easily.","romaji":"Kanojo wa keiken hōfu na dake atte, sono mondai o kantan ni kaiketsu dekita."},{"jp":"彼は優秀な学生だけあって、いつもテストの点数が高い。","en":"As expected of an excellent student, he always scores high on tests.","romaji":"Kare wa yūshū na gakusei dake atte, itsumo tesuto no tensū ga takai."}],"example":"彼は日本語が上手だけあって、日本人のように話すことができる。","exampleMeaning":"As expected from his good Japanese skills, he can speak like a native."},{"pattern":"～だけましだ (〜dake mashi da)","meaning":"Expresses that although the situation isn’t ideal, it could be worse; 'it’s not great, but at least...'.","formation":"Verb-casual + だけましだ, い-Adjective + だけましだ, な-Adjective + だけましだ, Noun + だけましだ","examples":[{"jp":"失敗するだけましだ。もっと大変なことにならなくてよかった。","en":"At least we only failed—it could’ve been much worse.","romaji":"Shippai suru dake mashi da. Motto taihen na koto ni naranakute yokatta."},{"jp":"遅れるだけましだ。来られないよりはいい。","en":"At least I’m only late. It’s better than not being able to come at all.","romaji":"Okureru dake mashi da. Korarenai yori wa ii."},{"jp":"小さな部屋だけましだ。全く部屋がないよりはいい。","en":"At least we have a small room; it’s better than having no room at all.","romaji":"Chīsana heya dake mashi da. Mattaku heya ga nai yori wa ii."},{"jp":"彼が結婚しないだけましだ。大変なことになるところだったよ。","en":"At least he’s not getting married—things could have gotten complicated.","romaji":"Kare ga kekkon shinai dake mashi da. Taihen na koto ni naru tokoro datta yo."}],"example":"失敗するだけましだ。もっと大変なことにならなくてよかった。","exampleMeaning":"At least we only failed—it could’ve been much worse."},{"pattern":"～たところ (〜ta tokoro)","meaning":"Used to describe an action that has just been completed, often followed by a result or observation.","formation":"Verb-past + ところ","examples":[{"jp":"掃除したところ、部屋がずっとキレイになりました。","en":"I just finished cleaning, and the room is so much cleaner now.","romaji":"Sōji shita tokoro, heya ga zutto kirei ni narimashita."},{"jp":"彼に聞いたところ、その質問の答えは分からないみたいです。","en":"I just asked him, and it seems he doesn't know the answer.","romaji":"Kare ni kiita tokoro, sono shitsumon no kotae wa wakaranai mitai desu."},{"jp":"宿題を出したところ、先生が間違いを見つけました。","en":"As soon as I turned in my homework, the teacher found a mistake.","romaji":"Shukudai o dashita tokoro, sensei ga machigai o mitsukemashita."},{"jp":"昼ごはんを食べたところ、気分が良くなりました。","en":"Right after eating lunch, I started feeling better.","romaji":"Hirugohan o tabeta tokoro, kibun ga yoku narimashita."}],"example":"掃除したところ、部屋がずっとキレイになりました。","exampleMeaning":"I just finished cleaning, and the room is so much cleaner now."},{"pattern":"～たとたん (〜ta totan)","meaning":"Express the moment something happens; 'as soon as', 'just when'.","formation":"Verb-past + たとたん","examples":[{"jp":"ドアを開けたとたん、雨が降り始めた。","en":"As soon as I opened the door, it started raining.","romaji":"Doa o aketa totan, ame ga furi-hajimeta."},{"jp":"電話をかけたとたん、バッテリーが切れた。","en":"Just when I made the phone call, the battery died.","romaji":"Denwa o kaketa totan, batterī ga kireta."},{"jp":"彼女に会ったとたん、思い出の歌が流れた。","en":"No sooner had I met her than a nostalgic song started playing.","romaji":"Kanojo ni atta totan, omoide no uta ga nagareta."},{"jp":"テストが終わったとたん、リラックスできた。","en":"The moment the test ended, I was able to relax.","romaji":"Tesuto ga owatta totan, rirakkusu dekita."}],"example":"ドアを開けたとたん、雨が降り始めた。","exampleMeaning":"As soon as I opened the door, it started raining."},{"pattern":"～だらけ (〜darake)","meaning":"Indicates that something is full of or covered with a certain (usually negative) characteristic.","formation":"Noun + だらけ","examples":[{"jp":"彼の部屋はゴミだらけだ。","en":"His room is full of trash.","romaji":"Kare no heya wa gomi darake da."},{"jp":"このビーチは岩だらけで泳ぎにくい。","en":"This beach is full of rocks and is difficult to swim at.","romaji":"Kono bīchi wa iwa darake de oyogi nikui."},{"jp":"彼の顔はしわだらけだ。","en":"His face is covered with wrinkles.","romaji":"Kare no kao wa shiwa darake da."},{"jp":"このリンゴは虫食いだらけだ。","en":"This apple is riddled with wormholes.","romaji":"Kono ringo wa mushikui darake da."}],"example":"彼の部屋はゴミだらけだ。","exampleMeaning":"His room is full of trash."},{"pattern":"～っこない (〜kkonai)","meaning":"Expresses the impossibility or very low probability of something happening; 'no way', 'impossible'.","formation":"Verb-negative stem + っこない","examples":[{"jp":"こんなに雪が降っているんだから、学校に間に合いっこない。","en":"With snow falling this heavily, there's no way we'll make it to school on time.","romaji":"Konna ni yuki ga futteirun dakara, gakkō ni maniai kkonai."},{"jp":"彼は泳げないので、プールの向こう側に泳いで行きっこない。","en":"Since he can’t swim, there’s no way he’ll make it to the other side of the pool.","romaji":"Kare wa oyogenai node, pūru no mukōgawa ni oyoide ikkonai."},{"jp":"彼女はとても怖がりなので、一人で夜の公園に行きっこない。","en":"She’s so timid, there’s no chance she’d go to the park alone at night.","romaji":"Kanojo wa totemo kowagari na node, hitori de yoru no kōen ni ikkonai."},{"jp":"この短い時間で、その本を全部読むことはできっこない。","en":"It's impossible to read the entire book in such a short time.","romaji":"Kono mijikai jikan de, sono hon o zenbu yomu koto wa dekikkonai."}],"example":"こんなに雪が降っているんだから、学校に間に合いっこない。","exampleMeaning":"With snow falling this heavily, there's no way we'll make it to school on time."},{"pattern":"～つつ (〜tsutsu)","meaning":"Shows two actions happening simultaneously or a contrast; 'while', 'although'.","formation":"Verb-stem + つつ","examples":[{"jp":"彼はテレビを見つつ、宿題をしていました。","en":"He was doing his homework while watching TV.","romaji":"Kare wa terebi o mitsutsu, shukudai o shite imashita."},{"jp":"最近忙しいと思いつつ、毎日運動を続けています。","en":"Although I feel busy these days, I still exercise every day.","romaji":"Saikin isogashii to omoi tsutsu, mainichi undō o tsuzukete imasu."},{"jp":"彼女は泣きつつ、笑顔で別れを告げた。","en":"She was crying, yet she said goodbye with a smile on her face.","romaji":"Kanojo wa naki tsutsu, egao de wakare o tsugeta."},{"jp":"雨に濡れつつ、彼は歩き続けました。","en":"He continued walking even though he was getting soaked by the rain.","romaji":"Ame ni nure tsutsu, kare wa aruki tsuzukemashita."}],"example":"彼はテレビを見つつ、宿題をしていました。","exampleMeaning":"He was doing his homework while watching TV."},{"pattern":"～つつある (〜tsutsu aru)","meaning":"Expresses an ongoing process or gradual change.","formation":"Verb-stem + つつある","examples":[{"jp":"地球温暖化は進行しつつある。","en":"Global warming is in progress.","romaji":"Chikyū ondanka wa shinkō shitsutsu aru."},{"jp":"この町は急速に発展しつつある。","en":"This town is rapidly developing.","romaji":"Kono machi wa kyūsoku ni hatten shitsutsu aru."},{"jp":"子供たちは成長しつつある。","en":"The children are growing up.","romaji":"Kodomo-tachi wa seichō shitsutsu aru."},{"jp":"景気が回復しつつある。","en":"The economy is recovering.","romaji":"Keiki ga kaifuku shitsutsu aru."}],"example":"地球温暖化は進行しつつある。","exampleMeaning":"Global warming is in progress."},{"pattern":"～っぱなし (〜ppanashi)","meaning":"Express a continuous action or state; 'left as is', 'non-stop'.","formation":"Verb-ます stem + っぱなし","examples":[{"jp":"窓を開けっぱなしにして、部屋が寒くなってしまった。","en":"I left the window open, and the room got cold.","romaji":"Mado o akeppanashi ni shite, heya ga samuku natte shimatta."},{"jp":"彼は音楽を聴くのが好きで、いつもイヤホンをつけっぱなしです。","en":"He loves listening to music and always has his earphones on.","romaji":"Kare wa ongaku o kiku no ga suki de, itsumo iyahon o tsukeppanashi desu."},{"jp":"子供はおもちゃを床に置きっぱなしで、片付けなかった。","en":"The child left the toys on the floor and didn’t put them away.","romaji":"Kodomo wa omocha o yuka ni okippanashi de, katazukenakatta."},{"jp":"昨夜は忙しかったので、テレビをつけっぱなしにして寝てしまった。","en":"I was busy last night, so I left the TV on and fell asleep.","romaji":"Sakuya wa isogashikatta node, terebi o tsukeppanashi ni shite nete shimatta."}],"example":"窓を開けっぱなしにして、部屋が寒くなってしまった。","exampleMeaning":"I left the window open, and the room got cold."},{"pattern":"～っぽい (〜ppoi)","meaning":"Indicates that something has the appearance, characteristics, or behavior of something else.","formation":"Noun + っぽい, Verb-casual + っぽい, い-Adjective + っぽい, な-Adjective + っぽい","examples":[{"jp":"彼女は大人っぽい服を着ている。","en":"She’s wearing clothes that look mature.","romaji":"Kanojo wa otonappoi fuku o kite iru."},{"jp":"この説明は分かりにくっぽい。","en":"This explanation seems hard to understand.","romaji":"Kono setsumei wa wakari nikuppoi."},{"jp":"彼は疲れたっぽい顔をしている。","en":"He has a face that looks tired.","romaji":"Kare wa tsukareta ppoi kao o shite iru."},{"jp":"この部屋は寒っぽい感じがする。","en":"This room feels kind of chilly.","romaji":"Kono heya wa samuppoi kanji ga suru."}],"example":"彼女は大人っぽい服を着ている。","exampleMeaning":"She’s wearing clothes that look mature."},{"pattern":"～ていられない (〜te irarenai)","meaning":"Expresses that one cannot afford to do something; 'can't keep on', 'unable to continue'.","formation":"Verb-て form + いられない","examples":[{"jp":"こんなに忙しいのに、無理に遊んでいられない。","en":"I'm so busy that I can't afford to just play around.","romaji":"Konna ni isogashii noni, muri ni asonde irarenai."},{"jp":"寒すぎて、外で待っていられない。","en":"It's too cold; I can't keep waiting outside.","romaji":"Samusugite, soto de matte irarenai."},{"jp":"この問題は重要だから、放っておいていられない。","en":"This issue is too important to ignore.","romaji":"Kono mondai wa jūyō dakara, houtte oite irarenai."},{"jp":"彼女の態度が我慢できず、黙っていられない。","en":"I can't stand her attitude, so I can't stay silent.","romaji":"Kanojo no taido ga gaman dekizu, damatte irarenai."}],"example":"こんなに忙しいのに、無理に遊んでいられない。","exampleMeaning":"I'm so busy that I can't afford to just play around."},{"pattern":"～てかなわない (〜te kanawanai)","meaning":"Expresses that something cannot be endured, tolerated, or is unbearable.","formation":"Adjective (〜く / 〜で) + て + かなわない / Verb phrase (reworded to an adjective/negative) + て + かなわない","examples":[{"jp":"こんなに暑くてかなわない。","en":"I can’t stand this heat.","romaji":"Konnani atsukute kanawanai."},{"jp":"彼の話は失礼すぎてかなわない。","en":"His remarks are so rude I can’t put up with them.","romaji":"Kare no hanashi wa shitsurei sugite kanawanai."},{"jp":"映画があまりに感動的で、忘れられなくてかなわない。","en":"The movie was so moving that I can’t stand how it stays on my mind.","romaji":"Eiga ga amari ni kandō-teki de, wasurerarenakute kanawanai."},{"jp":"彼女の笑顔がまぶしくてかなわない。","en":"Her smile is so dazzling that it’s overwhelming.","romaji":"Kanojo no egao ga mabushikute kanawanai."}],"example":"こんなに暑くてかなわない。","exampleMeaning":"I can’t stand this heat."},{"pattern":"～てからでないと (〜te kara denai to)","meaning":"Indicates that something cannot be done before a certain action is completed; 'not until', 'only after'.","formation":"Verb-て + からでないと","examples":[{"jp":"宿題をしてからでないと、遊びに行けません。","en":"You cannot go play until you’ve finished your homework.","romaji":"Shukudai o shite kara denai to, asobi ni ikemasen."},{"jp":"食事をしてからでないと、デザートを食べられません。","en":"You cannot eat dessert until after having a meal.","romaji":"Shokuji o shite kara denai to, dezāto o taberaremasen."},{"jp":"チケットを買ってからでないと、映画を見られません。","en":"You can’t watch the movie until after you buy a ticket.","romaji":"Chiketto o katte kara denai to, eiga o miraremasen."},{"jp":"試験が終わってからでないと、休みを取れません。","en":"You can’t take time off until the exam is over.","romaji":"Shiken ga owatte kara denai to, yasumi o toremasen."}],"example":"宿題をしてからでないと、遊びに行けません。","exampleMeaning":"You cannot go play until you’ve finished your homework."},{"pattern":"～てこそ (〜te koso)","meaning":"Emphasizes the condition; 'only when', 'precisely because'.","formation":"Verb-て form + こそ / い-Adjective + くてこそ / な-Adjective + でこそ / Noun + でこそ","examples":[{"jp":"勉強してこそ、テストに合格できる。","en":"Only when you study can you pass the test.","romaji":"Benkyō shite koso, tesuto ni gōkaku dekiru."},{"jp":"素直になってこそ、相手の気持ちが分かります。","en":"Only when you’re honest can you understand the other person’s feelings.","romaji":"Sunao ni natte koso, aite no kimochi ga wakarimasu."},{"jp":"静かでこそ、心が落ち着く。","en":"Only in silence can one’s mind be at peace.","romaji":"Shizuka de koso, kokoro ga ochitsuku."},{"jp":"友達でこそ、お互いに助け合うのは当然だ。","en":"Precisely because we’re friends, it’s natural to help each other.","romaji":"Tomodachi de koso, otagai ni tasukeau no wa tōzen da."}],"example":"勉強してこそ、テストに合格できる。","exampleMeaning":"Only when you study can you pass the test."},{"pattern":"～でしょうがない (〜deshou ga nai)","meaning":"Expresses an intense emotional or physical state; 'extremely', 'can’t help but'.","formation":"い-Adjective(く) + てしょうがない / な-Adjective + で(は)しょうがない / Verb-て form + しょうがない","examples":[{"jp":"今日は暇で(は)しょうがない。","en":"I’m extremely bored today.","romaji":"Kyō wa hima de shō ga nai."},{"jp":"試験が近いから不安でしょうがない。","en":"I’m so anxious because the exam is coming up.","romaji":"Shiken ga chikai kara fuan deshō ga nai."},{"jp":"頭が痛くてしょうがないから、早退したい。","en":"My head hurts so much I can’t stand it—I want to leave early.","romaji":"Atama ga itakute shō ga nai kara, sōtai shitai."},{"jp":"新しいゲームが気になってしょうがない。","en":"I can’t help but keep thinking about the new game.","romaji":"Atarashii gēmu ga ki ni natte shō ga nai."}],"example":"今日は暇で(は)しょうがない。","exampleMeaning":"I’m extremely bored today."},{"pattern":"～でたまらない (〜de tamaranai)","meaning":"Express extremely strong feelings or sensations; 'can't stand', 'unbearably'.","formation":"い-Adjective (く) + てたまらない / な-Adjective + でたまらない / Verb-て form + たまらない","examples":[{"jp":"この暑さは本当に暑くてたまらない。","en":"This heat is absolutely unbearable.","romaji":"Kono atsusa wa hontō ni atsukute tamaranai."},{"jp":"彼女のことが好きでたまらない。","en":"I like her so much I can hardly stand it.","romaji":"Kanojo no koto ga suki de tamaranai."},{"jp":"この部屋は寒くてたまらない。","en":"This room is unbearably cold.","romaji":"Kono heya wa samukute tamaranai."},{"jp":"彼の態度を見ていると、腹が立ってたまらない。","en":"Seeing his attitude makes me extremely angry.","romaji":"Kare no taido o mite iru to, hara ga tatte tamaranai."}],"example":"この暑さは本当に暑くてたまらない。","exampleMeaning":"This heat is absolutely unbearable."},{"pattern":"～でならない (〜de naranai)","meaning":"Indicates an uncontrollable emotion or feeling; 'can’t help but', 'overwhelmingly'.","formation":"な-Adjective + でならない / い-Adjective (く) + てならない / Verb-て + ならない","examples":[{"jp":"彼の演技が素晴らしくてならない。","en":"I can’t help but be amazed at his wonderful performance.","romaji":"Kare no engi ga subarashikute naranai."},{"jp":"合格発表が気になってならない。","en":"I can’t stop worrying about the exam results.","romaji":"Gōkaku happyō ga ki ni natte naranai."},{"jp":"友達が引っ越してしまって、寂しくてならない。","en":"My friend moved away, and I feel unbearably lonely.","romaji":"Tomodachi ga hikkoshite shimatte, sabishikute naranai."},{"jp":"初めての海外旅行で、不安でならない。","en":"It’s my first trip abroad, and I’m extremely anxious.","romaji":"Hajimete no kaigai ryokō de, fuan de naranai."}],"example":"彼の演技が素晴らしくてならない。","exampleMeaning":"I can’t help but be amazed at his wonderful performance."},{"pattern":"～でばかりはいられない (〜de bakari wa irarenai)","meaning":"Cannot afford to only do something; cannot always rely on it.","formation":"Verb-て form + ばかりはいられない / Noun + ばかりはいられない (with appropriate particles)","examples":[{"jp":"いつも助けてもらってばかりはいられない。","en":"I can’t just keep letting people help me all the time.","romaji":"Itsumo tasukete moratte bakari wa irarenai."},{"jp":"好きな仕事ばかりしてはいられない。","en":"I can’t afford to only do the work I love.","romaji":"Suki na shigoto bakari shite wa irarenai."},{"jp":"親に頼ってばかりはいられない。","en":"I can’t keep depending on my parents forever.","romaji":"Oya ni tayotte bakari wa irarenai."},{"jp":"休んでばかりはいられない。仕事もしなくちゃ。","en":"I can’t just keep taking breaks; I have work to do as well.","romaji":"Yasunde bakari wa irarenai. Shigoto mo shinakucha."}],"example":"いつも助けてもらってばかりはいられない。","exampleMeaning":"I can’t just keep letting people help me all the time."},{"pattern":"～ではないか (〜de wa nai ka)","meaning":"Used to show a strong assertion or emphasis on one’s opinion; 'isn't it?', 'aren't you?', 'right?'.","formation":"Noun + ではないか / い-Adjective + ではないか / な-Adjective + ではないか / Verb-casual + ではないか","examples":[{"jp":"彼は優秀な学生ではないか。","en":"Isn’t he an excellent student?","romaji":"Kare wa yūshū na gakusei de wa nai ka."},{"jp":"この料理は美味しいではないか。","en":"Isn’t this dish delicious?","romaji":"Kono ryōri wa oishii de wa nai ka."},{"jp":"あなたは彼女の友達ではないか。","en":"Aren’t you her friend?","romaji":"Anata wa kanojo no tomodachi de wa nai ka."},{"jp":"明日は休みではないか。","en":"Tomorrow’s a day off, right?","romaji":"Ashita wa yasumi de wa nai ka."}],"example":"彼は優秀な学生ではないか。","exampleMeaning":"Isn’t he an excellent student?"},{"pattern":"～てはならない (〜te wa naranai)","meaning":"Express prohibition; 'must not', 'cannot', 'should not'.","formation":"Verb-て form + はならない","examples":[{"jp":"ここでタバコを吸ってはならない。","en":"You must not smoke here.","romaji":"Koko de tabako o sutte wa naranai."},{"jp":"秘密を他人に話してはならない。","en":"You cannot reveal this secret to others.","romaji":"Himitsu o tanin ni hanashite wa naranai."},{"jp":"この部屋に入ってはならない。","en":"You must not enter this room.","romaji":"Kono heya ni haitte wa naranai."},{"jp":"飲酒運転をしてはならない。","en":"You must not drink and drive.","romaji":"Inshu unten o shite wa naranai."}],"example":"ここでタバコを吸ってはならない。","exampleMeaning":"You must not smoke here."},{"pattern":"～てまで (〜te made)","meaning":"Express the extent someone goes in order to achieve something; 'to the point of', 'even', 'so far as to'.","formation":"Verb-て form + まで","examples":[{"jp":"彼は試験に合格するために、徹夜してまで勉強しました。","en":"He studied to the point of staying up all night in order to pass the exam.","romaji":"Kare wa shiken ni gōkaku suru tame ni, tetsuya shite made benkyō shimashita."},{"jp":"この商品がほしかったので、朝早く起きてまで並んで買いました。","en":"I wanted this product so much that I went so far as to get up early and wait in line to buy it.","romaji":"Kono shōhin ga hoshikatta node, asa hayaku okite made narande kaimashita."},{"jp":"彼女は彼を助けるために、お金を借りてまで手術代を払いました。","en":"In order to help him, she even borrowed money to pay for the surgery.","romaji":"Kanojo wa kare o tasukeru tame ni, okane o karite made shujutsudai o haraimashita."},{"jp":"部長はそのプロジェクトを成功させるために、休日も働いてまで取り組んでいます。","en":"The manager is even working on holidays to make the project a success.","romaji":"Buchō wa sono purojekuto o seikō saseru tame ni, kyūjitsu mo hataraite made torikunde imasu."}],"example":"彼は試験に合格するために、徹夜してまで勉強しました。","exampleMeaning":"He studied to the point of staying up all night in order to pass the exam."},{"pattern":"～て当然だ (〜te tōzen da)","meaning":"Expresses that something is natural or expected.","formation":"Verb-て form + 当然だ","examples":[{"jp":"彼は毎日勉強しているから、試験に合格して当然だ。","en":"Since he studies every day, it's only natural that he passes the exam.","romaji":"Kare wa mainichi benkyō shite iru kara, shiken ni gōkaku shite tōzen da."},{"jp":"そのレストランは料理が美味しいので、予約がいっぱいになって当然だ。","en":"Because that restaurant’s food is delicious, no wonder its reservations are always full.","romaji":"Sono resutoran wa ryōri ga oishii node, yoyaku ga ippai ni natte tōzen da."},{"jp":"彼女は毎晩練習しているので、上手になって当然だ。","en":"She practices every night, so it's natural that she becomes skilled.","romaji":"Kanojo wa maiban renshū shite iru node, jōzu ni natte tōzen da."},{"jp":"彼は仕事で成功していて、お金持ちになって当然だ。","en":"He has succeeded at his job, so it's only natural that he's become wealthy.","romaji":"Kare wa shigoto de seikō shite ite, okanemochi ni natte tōzen da."}],"example":"彼は毎日勉強しているから、試験に合格して当然だ。","exampleMeaning":"Since he studies every day, it's only natural that he passes the exam."},{"pattern":"～というものだ (〜to iu mono da)","meaning":"Expressing a general rule or common sense.","formation":"Sentence + というものだ","examples":[{"jp":"若者の熱情は尊敬に値するというものだ。","en":"The passion of young people is something that deserves respect.","romaji":"Wakamono no netsujō wa sonkei ni ataisuru to iu mono da."},{"jp":"勉強は一日でもサボれば遅れるというものだ。","en":"If you skip even a day of studying, you'll fall behind—that's just how it is.","romaji":"Benkyō wa ichinichi demo saboreba okureru to iu mono da."},{"jp":"成功するためには困難に立ち向かうというものだ。","en":"To succeed, one must face difficulties—that's just the way it is.","romaji":"Seikō suru tame ni wa konnan ni tachimukau to iu mono da."},{"jp":"友情はお金で買えないというものだ。","en":"It is said that friendship cannot be bought with money.","romaji":"Yūjō wa okane de kaenai to iu mono da."}],"example":"若者の熱情は尊敬に値するというものだ。","exampleMeaning":"The passion of young people is something that deserves respect."},{"pattern":"どうにか～ないものか (dō ni ka ~ nai mono ka)","meaning":"Express a strong desire or wish for something to be possible.","formation":"どうにか + Verb-negative form + ないものか","examples":[{"jp":"どうにかこの仕事を終わらせないものか。","en":"Isn't there some way to finish this job?","romaji":"Dō ni ka kono shigoto o owarasenai mono ka."},{"jp":"どうにか次の試験で合格しないものか。","en":"Can't we somehow pass the next exam?","romaji":"Dō ni ka tsugi no shiken de gōkaku shinai mono ka."},{"jp":"どうにか込んでいる電車に乗れないものか。","en":"Is there no way to get on the crowded train somehow?","romaji":"Dō ni ka konde iru densha ni norenai mono ka."},{"jp":"どうにか彼女と仲直りしないものか。","en":"Isn't there some way to make up with her?","romaji":"Dō ni ka kanojo to nakanaori shinai mono ka."}],"example":"どうにかこの仕事を終わらせないものか。","exampleMeaning":"Isn't there some way to finish this job?"},{"pattern":"～とおり (〜toori)","meaning":"Express doing something as instructed or describing how something matches a rule or guideline; 'as', 'according to'.","formation":"Verb-casual + とおり, い-Adjective + とおり, な-Adjective + だとおり, Noun + だとおり","examples":[{"jp":"先生が言ったとおりに宿題をしました。","en":"I did my homework exactly as the teacher said.","romaji":"Sensei ga itta tōri ni shukudai o shimashita."},{"jp":"この地図のとおりに歩いてください。","en":"Please walk according to this map.","romaji":"Kono chizu no tōri ni aruite kudasai."},{"jp":"彼はいつもルールどおりに遊びます。","en":"He always plays by the rules.","romaji":"Kare wa itsumo rūru-dōri ni asobimasu."},{"jp":"その道路は昼間と同じくらい夜も賑やかだというとおりでした。","en":"As I heard, that street was just as lively at night as it is in the daytime.","romaji":"Sono dōro wa hiruma to onaji kurai yoru mo nigiyaka da to iu tōri deshita."}],"example":"先生が言ったとおりに宿題をしました。","exampleMeaning":"I did my homework exactly as the teacher said."},{"pattern":"～とか (〜to ka)","meaning":"Used to list examples or express uncertainty; 'such as', 'like', 'or something like that'.","formation":"Verb-casual + とか, い-Adjective + とか, な-Adjective + だとか, Noun + だとか","examples":[{"jp":"休日は映画を見るとか、買い物に行くとかして過ごします。","en":"On my days off, I do things like watch movies or go shopping.","romaji":"Kyūjitsu wa eiga o miru to ka, kaimono ni iku to ka shite sugoshimasu."},{"jp":"彼女はオーストラリアとかニュージーランドとかに行きたがっています。","en":"She wants to go to places like Australia or New Zealand.","romaji":"Kanojo wa Ōsutoraria to ka Nyūjīrando to ka ni ikitagatte imasu."},{"jp":"今日の天気は晴れたり、曇ったりとかだそうです。","en":"I heard today’s weather is something like sunny at times, cloudy at times.","romaji":"Kyō no tenki wa hare tari, kumottari to ka da sō desu."},{"jp":"彼は野球をしたり、サッカーをしたりとかしています。","en":"He spends his time playing baseball and soccer and such.","romaji":"Kare wa yakyū o shitari, sakkā o shitari to ka shite imasu."}],"example":"休日は映画を見るとか、買い物に行くとかして過ごします。","exampleMeaning":"On my days off, I do things like watch movies or go shopping."},{"pattern":"～ところ (〜tokoro)","meaning":"Express a specific point in time or state; 'when', 'just about', or 'in the middle of'.","formation":"Verb-casual + ところ, い-Adjective + ところ, な-Adjective + なところ, Noun + のところ","examples":[{"jp":"出かけるところです。","en":"I'm just about to go out.","romaji":"Dekakeru tokoro desu."},{"jp":"映画を見ているところです。","en":"I'm in the middle of watching a movie.","romaji":"Eiga o mite iru tokoro desu."},{"jp":"おいしいところで食事をするつもりです。","en":"I plan to have a meal at a good (tasty) place.","romaji":"Oishii tokoro de shokuji o suru tsumori desu."},{"jp":"彼は忙しいところを手伝ってくれました。","en":"He helped me when he himself was busy.","romaji":"Kare wa isogashii tokoro o tetsudatte kuremashita."}],"example":"出かけるところです。","exampleMeaning":"I'm just about to go out."},{"pattern":"～どころか (〜dokoro ka)","meaning":"Express 'far from', 'not just', 'not only', or 'to say nothing of'.","formation":"Verb-casual + どころか, い-Adjective + どころか, な-Adjective + どころか, Noun + どころか","examples":[{"jp":"彼は歌が上手どころか、プロの歌手みたいだ。","en":"Far from just being good at singing, he sounds like a professional singer.","romaji":"Kare wa uta ga jōzu dokoro ka, puro no kashu mitai da."},{"jp":"この料理はおいしいどころか、最高の味だ。","en":"This dish is not just delicious, it’s absolutely the best.","romaji":"Kono ryōri wa oishii dokoro ka, saikō no aji da."},{"jp":"彼女はただの友達どころか、私の親友だ。","en":"She’s far from just a friend; she’s my best friend.","romaji":"Kanojo wa tada no tomodachi dokoro ka, watashi no shin’yū da."},{"jp":"彼は英語ができるどころか、他の3つの言語も話せる。","en":"Not only can he speak English, he also speaks three other languages.","romaji":"Kare wa eigo ga dekiru dokoro ka, hoka no mittsu no gengo mo hanaseru."}],"example":"彼は歌が上手どころか、プロの歌手みたいだ。","exampleMeaning":"Far from just being good at singing, he sounds like a professional singer."},{"pattern":"～どころではない (〜dokoro de wa nai)","meaning":"Not the time/place for; far from; can't possibly.","formation":"Verb-casual + どころではない, い-Adjective + どころではない, な-Adjective + どころではない, Noun + どころではない","examples":[{"jp":"彼の失敗を笑うどころではない。私たちも同じミスをしている。","en":"This is not the time to laugh at his mistakes—we’re making the same ones.","romaji":"Kare no shippai o warau dokoro de wa nai. Watashitachi mo onaji misu o shite iru."},{"jp":"病気で寝ている時は、遊ぶどころではない。","en":"When you’re sick in bed, it's far from the time to play around.","romaji":"Byōki de nete iru toki wa, asobu dokoro de wa nai."},{"jp":"試験が近いので、映画を見るどころではない。","en":"Since the exam is coming up, I can’t possibly watch a movie.","romaji":"Shiken ga chikai node, eiga o miru dokoro de wa nai."},{"jp":"仕事が忙しすぎて、旅行なんて考えるどころではない。","en":"I'm way too busy with work to even think about going on a trip.","romaji":"Shigoto ga isogashisugite, ryokō nante kangaeru dokoro de wa nai."}],"example":"彼の失敗を笑うどころではない。私たちも同じミスをしている。","exampleMeaning":"This is not the time to laugh at his mistakes—we’re making the same ones."},{"pattern":"～としたら (〜to shitara)","meaning":"Express a hypothetical situation; 'if', 'suppose', 'assuming'.","formation":"Verb-casual + としたら, い-Adjective + としたら, な-Adjective + だとしたら, Noun + だとしたら","examples":[{"jp":"明日雨が降るとしたら、傘を持っていきましょう。","en":"If it rains tomorrow, let’s bring umbrellas.","romaji":"Ashita ame ga furu to shitara, kasa o motte ikimashō."},{"jp":"このケーキが美味しくないとしたら、誰も食べないだろう。","en":"If this cake isn’t tasty, probably no one will eat it.","romaji":"Kono kēki ga oishikunai to shitara, dare mo tabenai darō."},{"jp":"彼が病気だとしたら、早めに病院へ行かないといけません。","en":"If he is sick, he needs to go to the hospital soon.","romaji":"Kare ga byōki da to shitara, hayame ni byōin e ikanai to ikemasen."},{"jp":"彼女が学生だとしたら、このレストランは割引があるでしょう。","en":"If she’s a student, there’s probably a discount at this restaurant.","romaji":"Kanojo ga gakusei da to shitara, kono resutoran wa waribiki ga aru deshō."}],"example":"明日雨が降るとしたら、傘を持っていきましょう。","exampleMeaning":"If it rains tomorrow, let’s bring umbrellas."},{"pattern":"～としても (〜to shite mo)","meaning":"Even if, despite, although","formation":"Verb-casual + としても, い-Adjective + としても, な-Adjective + だとしても, Noun + だとしても","examples":[{"jp":"雨が降るとしても、レースは中止しません。","en":"Even if it rains, we won't cancel the race.","romaji":"Ame ga furu to shite mo, rēsu wa chūshi shimasen."},{"jp":"このケーキが美味しくないとしても、私は食べるつもりです。","en":"Even if this cake isn't delicious, I plan on eating it.","romaji":"Kono kēki ga oishikunai to shite mo, watashi wa taberu tsumori desu."},{"jp":"彼女が遅刻するとしても、私たちは待ち続けます。","en":"Even if she is late, we will keep waiting.","romaji":"Kanojo ga chikoku suru to shite mo, watashitachi wa machitsuzukemasu."},{"jp":"忙しいだとしても、友達との約束は守りたい。","en":"Even if I'm busy, I want to keep my promise to my friend.","romaji":"Isogashii da to shite mo, tomodachi to no yakusoku wa mamoritai."}],"example":"雨が降るとしても、レースは中止しません。","exampleMeaning":"Even if it rains, we won't cancel the race."},{"pattern":"～と～ともに (〜to 〜tomoni)","meaning":"Expresses 'together with' or 'along with'; used to describe two events or actions happening simultaneously or in parallel.","formation":"Verb-casual + とともに, い-Adjective + とともに, な-Adjective + とともに, Noun + とともに","examples":[{"jp":"彼が来るとともに、パーティーが始まりました。","en":"The party started as soon as he arrived.","romaji":"Kare ga kuru to tomoni, paatii ga hajimarimashita."},{"jp":"季節が変わるとともに、服のファッションも変わります。","en":"As the seasons change, clothing fashion also changes.","romaji":"Kisetsu ga kawaru to tomoni, fuku no fasshon mo kawarimasu."},{"jp":"成長とともに、いろいろな経験を積むことが大切です。","en":"As you grow, it is important to gain various experiences.","romaji":"Seichou to tomoni, iroirona keiken wo tsumu koto ga taisetsu desu."},{"jp":"技術の進歩とともに、便利なアプリが増えています。","en":"With the advancement of technology, the number of convenient apps is increasing.","romaji":"Gijutsu no shinpo to tomoni, benrina apuri ga fueteimasu."}],"example":"彼が来るとともに、パーティーが始まりました。","exampleMeaning":"The party started as soon as he arrived."},{"pattern":"～とは限らない (〜to wa kagiranai)","meaning":"Expresses that something is not necessarily true; 'not always', 'not necessarily'.","formation":"Verb-casual + とは限らない, い-Adjective + とは限らない, な-Adjective + だとは限らない, Noun + だとは限らない","examples":[{"jp":"いつも勉強しているとは限らない。","en":"It's not always true that I'm studying.","romaji":"Itsumo benkyou shite iru to wa kagiranai."},{"jp":"高い商品がいいとは限らない。","en":"Expensive products are not necessarily good.","romaji":"Takai shouhin ga ii to wa kagiranai."},{"jp":"彼が正しいとは限らない。","en":"It's not necessarily true that he is right.","romaji":"Kare ga tadashii to wa kagiranai."},{"jp":"雨が降るとは限らない。","en":"It's not necessarily going to rain.","romaji":"Ame ga furu to wa kagiranai."}],"example":"いつも勉強しているとは限らない。","exampleMeaning":"It's not always true that I'm studying."},{"pattern":"～ないことはない (〜nai koto wa nai)","meaning":"Express that something is not impossible, meaning it is possible or could be done.","formation":"Verb-ないform + ことはない","examples":[{"jp":"彼が来ないことはない。","en":"It's not that he won't come (it's possible that he will come).","romaji":"Kare ga konai koto wa nai."},{"jp":"あの問題が解けないことはない。","en":"It's not impossible to solve that problem (it can be solved).","romaji":"Ano mondai ga tokenai koto wa nai."},{"jp":"その仕事が難しくないことはない。","en":"That job is not without difficulty (it has some difficulties).","romaji":"Sono shigoto ga muzukashikunai koto wa nai."},{"jp":"彼女が正しくないことはない。","en":"It's not impossible that she is right (she could be right).","romaji":"Kanojo ga tadashikunai koto wa nai."}],"example":"彼が来ないことはない。","exampleMeaning":"It's not that he won't come (it's possible that he will come)."},{"pattern":"～ないこともない (〜nai koto mo nai)","meaning":"Used to express an action or state is 'not impossible', but emphasizes reluctance or doubt.","formation":"Verb-ないForm + こともない, い-adjective + こともない","examples":[{"jp":"この問題は解けないこともないけど、難しいです。","en":"It's not that I can't solve this problem, but it's difficult.","romaji":"Kono mondai wa tokenai koto mo nai kedo, muzukashii desu."},{"jp":"彼に会わないこともないが、あまり話す時間がない。","en":"It's not that I can't meet him, but there's not much time to talk.","romaji":"Kare ni awanai koto mo nai ga, amari hanasu jikan ga nai."},{"jp":"お金がないこともないけれど、節約した方がいい。","en":"It's not that I don't have money, but it's better to save.","romaji":"O-kane ga nai koto mo nai keredo, setsuyaku shita hou ga ii."},{"jp":"このゲームが面白くないこともないが、他のゲームの方が楽しい。","en":"It's not that this game isn't interesting, but other games are more fun.","romaji":"Kono geemu ga omoshirokunai koto mo nai ga, hoka no geemu no hou ga tanoshii."}],"example":"この問題は解けないこともないけど、難しいです。","exampleMeaning":"It's not that I can't solve this problem, but it's difficult."},{"pattern":"～ないではいられない (〜nai de wa irarenai)","meaning":"Cannot help but; cannot avoid; unable to refrain from.","formation":"Verb-ない form + ではいられない or じゃいられない","examples":[{"jp":"この映画はとても感動的で、泣かないではいられなかった。","en":"This movie was so touching, I couldn't help but cry.","romaji":"Kono eiga wa totemo kandouteki de, nakanai de wa irarenakatta."},{"jp":"彼女の笑顔を見ると、笑わないではいられない。","en":"When I see her smile, I can't help but laugh.","romaji":"Kanojo no egao wo miru to, warawanai de wa irarenai."},{"jp":"この部屋はとても寒いので、震えないではいられない。","en":"This room is so cold, I can't help but shiver.","romaji":"Kono heya wa totemo samui node, furuenai de wa irarenai."},{"jp":"彼の話はつまらないが、聞かないではいられない。","en":"His story is boring, but I can't help but listen.","romaji":"Kare no hanashi wa tsumaranai ga, kikanai de wa irarenai."}],"example":"この映画はとても感動的で、泣かないではいられなかった。","exampleMeaning":"This movie was so touching, I couldn't help but cry."},{"pattern":"～ながら (〜nagara)","meaning":"Express doing two things simultaneously or at the same time.","formation":"Verb-stem + ながら","examples":[{"jp":"テレビを見ながら宿題をしています。","en":"I am doing my homework while watching TV.","romaji":"Terebi wo minagara shukudai wo shiteimasu."},{"jp":"彼女は歌いながら料理を作っていました。","en":"She was cooking while singing.","romaji":"Kanojo wa utainagara ryouri wo tsukutte imashita."},{"jp":"電車の中で立ちながら本を読んでいる人が多いです。","en":"There are many people who read books while standing on the train.","romaji":"Densha no naka de tachinagara hon wo yonde iru hito ga ooi desu."},{"jp":"僕は歩きながらスマホを使っています。","en":"I am using my smartphone while walking.","romaji":"Boku wa arukinagara sumaho wo tsukatteimasu."}],"example":"テレビを見ながら宿題をしています。","exampleMeaning":"I am doing my homework while watching TV."},{"pattern":"～にあたり (〜ni atari)","meaning":"Expresses the meaning of 'at the time of', 'in', 'on', or 'upon'.","formation":"Noun + にあたり","examples":[{"jp":"入学にあたり、必要な書類を準備してください。","en":"Please prepare the necessary documents upon entering the school.","romaji":"Nyuugaku ni atari, hitsuyou na shorui wo junbi shite kudasai."},{"jp":"新年にあたり、抱負を立てる人が多いです。","en":"Many people set goals at the time of the new year.","romaji":"Shinnen ni atari, houfu wo tateru hito ga ooi desu."},{"jp":"結婚にあたり、両家は大切な儀式を行います。","en":"Upon getting married, both families conduct an important ceremony.","romaji":"Kekkon ni atari, ryouke wa taisetsu na gishiki wo okonaimasu."},{"jp":"新しい仕事を始めるにあたり、準備が必要です。","en":"In starting a new job, preparation is necessary.","romaji":"Atarashii shigoto wo hajimeru ni atari, junbi ga hitsuyou desu."}],"example":"入学にあたり、必要な書類を準備してください。","exampleMeaning":"Please prepare the necessary documents upon entering the school."},{"pattern":"～において (〜ni oite)","meaning":"Indicates the place, time, or context where an action or event occurs; 'in', 'at', 'on', 'regarding'.","formation":"Noun + において","examples":[{"jp":"この大学において、英語のクラスが一番人気があります。","en":"In this university, English classes are the most popular.","romaji":"Kono daigaku ni oite, eigo no kurasu ga ichiban ninki ga arimasu."},{"jp":"彼の研究において新しい発見がありました。","en":"In his research, there were new discoveries.","romaji":"Kare no kenkyuu ni oite atarashii hakken ga arimashita."},{"jp":"運動会において、彼は大活躍しました。","en":"At the sports festival, he performed exceptionally well.","romaji":"Undoukai ni oite, kare wa daikatsuyaku shimashita."},{"jp":"環境問題においては、みんなが責任を持って行動すべきです。","en":"Regarding environmental issues, everyone should take responsibility and act accordingly.","romaji":"Kankyou mondai ni oite wa, minna ga sekinin wo motte koudou subeki desu."}],"example":"この大学において、英語のクラスが一番人気があります。","exampleMeaning":"In this university, English classes are the most popular."},{"pattern":"～にかかわらず (〜ni kakawarazu)","meaning":"Regardless of; irrespective of; (often used as) 'whether or not'.","formation":"Verb-dictionary form + にかかわらず, い-Adjective + にかかわらず, な-Adjective + にかかわらず, Noun + にかかわらず","examples":[{"jp":"天気にかかわらず、今日の試合は行われます。","en":"The game today will be held, regardless of the weather.","romaji":"Tenki ni kakawarazu, kyou no shiai wa okonawaremasu."},{"jp":"彼は年齢にかかわらず、新しいことを学び続けています。","en":"He continues to learn new things, regardless of his age.","romaji":"Kare wa nenrei ni kakawarazu, atarashii koto wo manabi tsuzukete imasu."},{"jp":"その仕事が難しいかどうかにかかわらず、彼女は努力し続けた。","en":"Regardless of whether the job is difficult or not, she continued to make an effort.","romaji":"Sono shigoto ga muzukashii ka dou ka ni kakawarazu, kanojo wa doryoku shi tsuzuketa."},{"jp":"経験の有無にかかわらず、このプログラムは誰でも利用できます。","en":"Regardless of experience, this program can be used by anyone.","romaji":"Keiken no umu ni kakawarazu, kono puroguramu wa daredemo riyou dekimasu."}],"example":"天気にかかわらず、今日の試合は行われます。","exampleMeaning":"The game today will be held, regardless of the weather."},{"pattern":"～にかけては (〜ni kakete wa)","meaning":"Indicates a specific area or aspect in which someone or something excels.","formation":"Noun + にかけては","examples":[{"jp":"料理の腕前にかけては、彼女は誰にも負けません。","en":"When it comes to cooking skills, she is second to none.","romaji":"Ryouri no udemae ni kakete wa, kanojo wa dare ni mo makemasen."},{"jp":"この町にかけては、彼の店が一番おいしいラーメンを売っています。","en":"As far as this town is concerned, his store sells the most delicious ramen.","romaji":"Kono machi ni kakete wa, kare no mise ga ichiban oishii raamen wo utteimasu."},{"jp":"音楽の知識にかけては、彼は私たちの中で一番詳しいです。","en":"When it comes to music knowledge, he is the most knowledgeable among us.","romaji":"Ongaku no chishiki ni kakete wa, kare wa watashitachi no naka de ichiban kuwashii desu."},{"jp":"スポーツにかけては、彼はどんな競技も得意です。","en":"When it comes to sports, he excels in any competition.","romaji":"Supootsu ni kakete wa, kare wa donna kyogi mo tokui desu."}],"example":"料理の腕前にかけては、彼女は誰にも負けません。","exampleMeaning":"When it comes to cooking skills, she is second to none."},{"pattern":"～にしたがって (〜ni shitagatte)","meaning":"Expresses a natural consequence or a change that occurs according to something else; 'as', 'with', 'in accordance with'.","formation":"Noun + にしたがって","examples":[{"jp":"成長にしたがって、この植物の葉が大きくなります。","en":"As it grows, the leaves of this plant become larger.","romaji":"Seichou ni shitagatte, kono shokubutsu no ha ga ookiku narimasu."},{"jp":"説明書にしたがって、家具を組み立ててください。","en":"Please assemble the furniture according to the instructions.","romaji":"Setsumeisho ni shitagatte, kagu wo kumitatete kudasai."},{"jp":"年齢にしたがって、人の体力は低下します。","en":"As people age, their physical strength declines.","romaji":"Nenrei ni shitagatte, hito no tairyoku wa teika shimasu."},{"jp":"運動にしたがって、心拍数が増加することが一般的です。","en":"It is common for the heart rate to increase with exercise.","romaji":"Undou ni shitagatte, shinpakusuu ga zouka suru koto ga ippan teki desu."}],"example":"成長にしたがって、この植物の葉が大きくなります。","exampleMeaning":"As it grows, the leaves of this plant become larger."},{"pattern":"～にしたら (〜ni shitara)","meaning":"Express a point of view; 'from the perspective of', 'if I were'.","formation":"Noun + にしたら, Pronoun + にしたら","examples":[{"jp":"彼にしたら、早く帰りたいだろう。","en":"From his perspective, he probably wants to go home early.","romaji":"Kare ni shitara, hayaku kaeritai darou."},{"jp":"子供たちにしたら、この話はつまらないかもしれない。","en":"If I were the children, this story might be boring.","romaji":"Kodomo-tachi ni shitara, kono hanashi wa tsumaranai kamoshirenai."},{"jp":"私にしたら、そのプレゼントは素晴らしいと思います。","en":"From my perspective, I think that present is wonderful.","romaji":"Watashi ni shitara, sono purezento wa subarashii to omoimasu."},{"jp":"彼女にしたら、この映画が好きではないでしょう。","en":"If I were her, I would not like this movie.","romaji":"Kanojo ni shitara, kono eiga ga suki dewa nai deshou."}],"example":"彼にしたら、早く帰りたいだろう。","exampleMeaning":"From his perspective, he probably wants to go home early."},{"pattern":"～にしろ～にしろ (〜ni shiro 〜ni shiro)","meaning":"Expresses 'either way', 'in any case', 'be it...', used when presenting two alternatives.","formation":"Verb (dictionary form or negative form) + にしろ, い-Adjective + にしろ, な-Adjective + にしろ, Noun + にしろ","examples":[{"jp":"行くにしろ行かないにしろ、早く決めてください。","en":"Either way, whether you go or not, please decide quickly.","romaji":"Iku ni shiro ikanai ni shiro, hayaku kimete kudasai."},{"jp":"彼が来るにしろ来ないにしろ、パーティーは始めましょう。","en":"Be it if he comes or not, let's start the party either way.","romaji":"Kare ga kuru ni shiro konai ni shiro, paatii wa hajimemashou."},{"jp":"雨が降るにしろ降らないにしろ、傘を持って行ったほうがいいです。","en":"Either way, whether it rains or not, it's better to bring an umbrella.","romaji":"Ame ga furu ni shiro furanai ni shiro, kasa wo motte itta hou ga ii desu."},{"jp":"このレストランが高いにしろ安いにしろ、料理は美味しいです。","en":"In any case, whether this restaurant is expensive or cheap, the food is delicious.","romaji":"Kono resutoran ga takai ni shiro yasui ni shiro, ryouri wa oishii desu."}],"example":"行くにしろ行かないにしろ、早く決めてください。","exampleMeaning":"Either way, whether you go or not, please decide quickly."},{"pattern":"～につけ～につけ (〜ni tsuke 〜ni tsuke)","meaning":"Expresses 'whenever', 'each time', 'whether...or'.","formation":"Verb-casual + につけ, い-Adjective + につけ, な-Adjective + につけ, Noun + につけ","examples":[{"jp":"外国へ行くにつけ、勉強するにつけ、言葉の壁にぶつかる。","en":"Whether I go abroad or study, I always encounter language barriers.","romaji":"Gaikoku e iku ni tsuke, benkyou suru ni tsuke, kotoba no kabe ni butsukaru."},{"jp":"彼と話すにつけ、彼が考えるにつけ、彼の知識に驚かされる。","en":"Whenever I talk to him or hear his thoughts, I'm always amazed by his knowledge.","romaji":"Kare to hanasu ni tsuke, kare ga kangaeru ni tsuke, kare no chishiki ni odorokasareru."},{"jp":"この公園で遊ぶにつけ、散歩するにつけ、子供時代を思い出す。","en":"Each time I play or take a walk in this park, it reminds me of my childhood.","romaji":"Kono kouen de asobu ni tsuke, sanpo suru ni tsuke, kodomo jidai wo omoidasu."},{"jp":"春につけ、秋につけ、彼は母校を訪れる。","en":"Whether in spring or autumn, he visits his alma mater.","romaji":"Haru ni tsuke, aki ni tsuke, kare wa bokou wo otozureru."}],"example":"外国へ行くにつけ、勉強するにつけ、言葉の壁にぶつかる。","exampleMeaning":"Whether I go abroad or study, I always encounter language barriers."},{"pattern":"～につれて (〜ni tsurete)","meaning":"Expresses the idea that as one thing changes, so does another; 'as', 'along with', 'while'.","formation":"Verb (dictionary form) + につれて, Noun + につれて","examples":[{"jp":"年を取るにつれて、健康に気をつけなければなりません。","en":"As you get older, you have to pay more attention to your health.","romaji":"Toshi wo toru ni tsurete, kenkou ni ki wo tsukenakereba narimasen."},{"jp":"春が近づくにつれて、気温が上がる。","en":"As spring approaches, the temperature rises.","romaji":"Haru ga chikazuku ni tsurete, kion ga agaru."},{"jp":"勉強するにつれて、だんだん分かるようになる。","en":"As I study, I gradually come to understand.","romaji":"Benkyou suru ni tsurete, dandan wakaru you ni naru."},{"jp":"経験が増えるにつれて、自信もついてくる。","en":"As your experience increases, so does your confidence.","romaji":"Keiken ga fueru ni tsurete, jishin mo tsuite kuru."}],"example":"年を取るにつれて、健康に気をつけなければなりません。","exampleMeaning":"As you get older, you have to pay more attention to your health."},{"pattern":"～にともなって (〜ni tomonatte)","meaning":"Expresses 'along with' or 'as a result of'; indicates that one event occurs along with another.","formation":"Noun (event) + にともなって, Verb-casual + にともなって","examples":[{"jp":"人口が増えるにともなって、交通渋滞も悪化しています。","en":"As the population increases, traffic congestion is also getting worse.","romaji":"Jinkou ga fueru ni tomonatte, koutsuu juutai mo akka shiteimasu."},{"jp":"季節の変わり目にともなって、体調を崩しやすくなります。","en":"As the seasons change, it's easier to get out of shape.","romaji":"Kisetsu no kawarime ni tomonatte, taichou wo kuzushi yasuku narimasu."},{"jp":"経済の成長にともなって、雇用の機会も増えるでしょう。","en":"As the economy grows, employment opportunities will also increase.","romaji":"Keizai no seichou ni tomonatte, koyou no kikai mo fueru deshou."},{"jp":"彼の昇進にともなって、引っ越しをすることになりました。","en":"As a result of his promotion, we decided to move.","romaji":"Kare no shoushin ni tomonatte, hikkoshi wo suru koto ni narimashita."}],"example":"人口が増えるにともなって、交通渋滞も悪化しています。","exampleMeaning":"As the population increases, traffic congestion is also getting worse."},{"pattern":"～にほかならない (〜ni hoka naranai)","meaning":"Express that something is 'nothing but' or 'none other than'.","formation":"Verb-plain + にほかならない, い-Adjective + にほかならない, な-Adjective + にほかならない, Noun + にほかならない","examples":[{"jp":"彼の成功は努力にほかならない。","en":"His success is nothing but hard work.","romaji":"Kare no seikou wa doryoku ni hoka naranai."},{"jp":"この痛みは寒さにほかならない。","en":"This pain is nothing but the cold.","romaji":"Kono itami wa samusa ni hoka naranai."},{"jp":"彼の失敗の原因は慢心にほかならない。","en":"The cause of his failure is nothing but overconfidence.","romaji":"Kare no shippai no gen'in wa manshin ni hoka naranai."},{"jp":"彼女の笑顔は明るさにほかならない。","en":"Her smile is none other than brightness.","romaji":"Kanojo no egao wa akarusa ni hoka naranai."}],"example":"彼の成功は努力にほかならない。","exampleMeaning":"His success is nothing but hard work."},{"pattern":"～にもかかわらず (〜ni mo kakawarazu)","meaning":"Expresses 'despite', 'in spite of' or 'even though'.","formation":"Verb (any tense/form) + にもかかわらず, い-Adjective + にもかかわらず, な-Adjective (or Noun) + であるにもかかわらず","examples":[{"jp":"忙しいにもかかわらず、彼は毎日運動しています。","en":"Despite being busy, he exercises every day.","romaji":"Isogashii ni mo kakawarazu, kare wa mainichi undou shiteimasu."},{"jp":"雨が降っているにもかかわらず、彼女は散歩に行きました。","en":"Even though it was raining, she went for a walk.","romaji":"Ame ga futteiru ni mo kakawarazu, kanojo wa sanpo ni ikimashita."},{"jp":"車が古いにもかかわらず、まだよく走ります。","en":"In spite of the car being old, it still runs well.","romaji":"Kuruma ga furui ni mo kakawarazu, mada yoku hashirimasu."},{"jp":"結果が良くないにもかかわらず、彼は頑張り続けました。","en":"Despite the results not being good, he continued to do his best.","romaji":"Kekka ga yoku nai ni mo kakawarazu, kare wa ganbari tsuzukemashita."}],"example":"忙しいにもかかわらず、彼は毎日運動しています。","exampleMeaning":"Despite being busy, he exercises every day."},{"pattern":"～により (〜ni yori)","meaning":"Indicates the reason, method, or means by which something happens; 'by', 'through', 'due to'.","formation":"Noun + により, Verb + により","examples":[{"jp":"この事故は運転手の不注意により起こりました。","en":"This accident occurred due to the driver's carelessness.","romaji":"Kono jiko wa untenshu no fuchuui ni yori okorimashita."},{"jp":"その映画は小説により制作されました。","en":"The movie was produced based on the novel.","romaji":"Sono eiga wa shousetsu ni yori seisaku saremashita."},{"jp":"犯人は警察により逮捕されました。","en":"The criminal was arrested by the police.","romaji":"Hannin wa keisatsu ni yori taiho saremashita."},{"jp":"会社の成長は従業員の努力により実現しました。","en":"The company's growth was achieved through the efforts of its employees.","romaji":"Kaisha no seichou wa juugyouin no doryoku ni yori jitsugen shimashita."}],"example":"この事故は運転手の不注意により起こりました。","exampleMeaning":"This accident occurred due to the driver's carelessness."},{"pattern":"～にわたって (〜ni watatte)","meaning":"Indicates a range or extent; 'over', 'throughout', 'across'.","formation":"Noun + にわたって","examples":[{"jp":"彼女は一年にわたって日本語を勉強しました。","en":"She studied Japanese for over a year.","romaji":"Kanojo wa ichinen ni watatte nihongo wo benkyou shimashita."},{"jp":"このプロジェクトは50キロにわたって道路を建設します。","en":"This project will construct roads across 50 kilometers.","romaji":"Kono purojekuto wa gojukiro ni watatte douro wo kensetsu shimasu."},{"jp":"彼の著作は数多くの国にわたって読まれている。","en":"His writings are read throughout numerous countries.","romaji":"Kare no chosaku wa kazu ooku no kuni ni watatte yomarete iru."},{"jp":"その秘密は世代にわたって保たれ続けた。","en":"The secret was kept over generations.","romaji":"Sono himitsu wa sedai ni watatte tamotsu sareta."}],"example":"彼女は一年にわたって日本語を勉強しました。","exampleMeaning":"She studied Japanese for over a year."},{"pattern":"～に先立ち (〜ni sakidachi)","meaning":"Express an action or event that occurs before another; 'before', 'prior to', 'preceding'.","formation":"Noun + に先立ち / Verb-dictionary form + に先立って","examples":[{"jp":"会議に先立ち、資料を確認しましょう。","en":"Before the meeting, let's check the materials.","romaji":"Kaigi ni sakidachi, shiryou wo kakunin shimashou."},{"jp":"出発に先立ち、荷物を整理しました。","en":"Before departure, I organized my luggage.","romaji":"Shuppatsu ni sakidachi, nimotsu wo seiri shimashita."},{"jp":"就寝に先立ち、歯を磨きます。","en":"Before going to bed, I brush my teeth.","romaji":"Shuushin ni sakidachi, ha wo migakimasu."},{"jp":"映画の上映に先立ち、予告編が放映されます。","en":"Before the movie screening, the trailers are shown.","romaji":"Eiga no jouei ni sakidachi, yokokuhen ga houei saremasu."}],"example":"会議に先立ち、資料を確認しましょう。","exampleMeaning":"Before the meeting, let's check the materials."},{"pattern":"～に反して (〜ni hanshite)","meaning":"Contrary to, against, in spite of","formation":"Noun + に反して","examples":[{"jp":"天気予報に反して、今日は雨が降っている。","en":"Contrary to the weather forecast, it is raining today.","romaji":"Tenki yohou ni hanshite, kyou wa ame ga futte iru."},{"jp":"彼の予想に反して、試合に勝った。","en":"We won the match against his prediction.","romaji":"Kare no yosou ni hanshite, shiai ni katta."},{"jp":"両親の意見に反して、彼と結婚した。","en":"I married him against my parents' opinion.","romaji":"Ryoushin no iken ni hanshite, kare to kekkon shita."},{"jp":"この映画は批評家の評価に反して大ヒットした。","en":"This movie became a big hit contrary to the critics' ratings.","romaji":"Kono eiga wa hihyouka no hyouka ni hanshite daihitto shita."}],"example":"天気予報に反して、今日は雨が降っている。","exampleMeaning":"Contrary to the weather forecast, it is raining today."},{"pattern":"～に基づいて (〜ni motozuite)","meaning":"Based on, according to, depending on","formation":"Noun + に基づいて","examples":[{"jp":"研究結果に基づいて、新しい治療法が開発されました。","en":"A new treatment method was developed based on the research results.","romaji":"Kenkyuu kekka ni motozuite, atarashii chiryouhou ga kaihatsu saremashita."},{"jp":"法律に基づいて、犯罪者は逮捕されました。","en":"The criminal was arrested according to the law.","romaji":"Houritsu ni motozuite, hanzaisha wa taiho saremashita."},{"jp":"そのデータに基づいて、結論を出すことができます。","en":"We can draw conclusions based on that data.","romaji":"Sono deeta ni motozuite, ketsuron o dasu koto ga dekimasu."},{"jp":"お客様の要望に基づいて、商品の改善が行われます。","en":"Product improvements will be made based on customer requests.","romaji":"Okyakusama no youbou ni motozuite, shouhin no kaizen ga okonawaremasu."}],"example":"研究結果に基づいて、新しい治療法が開発されました。","exampleMeaning":"A new treatment method was developed based on the research results."},{"pattern":"～に対して (〜ni taishite)","meaning":"Expresses 'toward', 'against', 'in contrast to', or 'in response to'.","formation":"Noun + に対して","examples":[{"jp":"日本の文化に対して尊敬の念を持っています。","en":"I have a sense of respect towards Japanese culture.","romaji":"Nihon no bunka ni taishite sonkei no nen wo motte imasu."},{"jp":"彼に対して無礼な態度を取らないでください。","en":"Please don't have a rude attitude towards him.","romaji":"Kare ni taishite burei na taido wo toranaide kudasai."},{"jp":"先生の質問に対して、彼女はすぐに答えました。","en":"In response to the teacher's question, she answered immediately.","romaji":"Sensei no shitsumon ni taishite, kanojo wa sugu ni kotaemashita."},{"jp":"男性に対して、女性は同じ仕事でも低い給料をもらっている。","en":"In contrast to men, women receive lower salaries for the same job.","romaji":"Dansei ni taishite, josei wa onaji shigoto demo hikui kyuuryou wo moratte iru."}],"example":"日本の文化に対して尊敬の念を持っています。","exampleMeaning":"I have a sense of respect towards Japanese culture."},{"pattern":"～に応えて (〜ni kotaete)","meaning":"Responding to; living up to; meeting.","formation":"Noun + に応えて","examples":[{"jp":"お客様の要望に応えて、新しいメニューを作りました。","en":"Responding to the customers' requests, we created a new menu.","romaji":"Okyaku-sama no youbou ni kotaete, atarashii menyuu o tsukurimashita."},{"jp":"彼はチームの期待に応えて素晴らしいプレーを見せた。","en":"He lived up to the team's expectations and showed a great performance.","romaji":"Kare wa chiimu no kitai ni kotaete, subarashii puree o miseta."},{"jp":"政府は国民の声に応えて、新しい法律を制定した。","en":"The government enacted a new law in response to the voice of the people.","romaji":"Seifu wa kokumin no koe ni kotaete, atarashii houritsu o seitei shita."},{"jp":"企業は環境問題に応えて、環境に優しい製品を開発している。","en":"Companies are developing environmentally friendly products in response to environmental issues.","romaji":"Kigyou wa kankyou mondai ni kotaete, kankyou ni yasashii seihin o kaihatsu shite iru."}],"example":"お客様の要望に応えて、新しいメニューを作りました。","exampleMeaning":"Responding to the customers' requests, we created a new menu."},{"pattern":"～に応じて (〜ni oujite)","meaning":"In accordance with, depending on, in response to.","formation":"Noun + に応じて","examples":[{"jp":"仕事の量に応じて給料が変わります。","en":"The salary changes depending on the amount of work.","romaji":"Shigoto no ryou ni oujite kyuuryou ga kawarimasu."},{"jp":"季節に応じて服装を選びましょう。","en":"Choose your clothes according to the season.","romaji":"Kisetsu ni oujite fukusou wo erabimashou."},{"jp":"お客様の希望に応じてプランを提案します。","en":"We propose plans according to the customers' wishes.","romaji":"Okyakusama no kibou ni oujite puran wo teian shimasu."},{"jp":"年齢に応じて健康診断項目が異なります。","en":"Health check items vary depending on age.","romaji":"Nenrei ni oujite kenkou shindan koumoku ga kotonarimasu."}],"example":"仕事の量に応じて給料が変わります。","exampleMeaning":"The salary changes depending on the amount of work."},{"pattern":"～に決まっている (〜ni kimatte iru)","meaning":"Express certainty; 'it is obvious', 'it must be', 'no doubt'.","formation":"Verb-casual + に決まっている, い-Adjective + に決まっている, な-Adjective + だに決まっている, Noun + だに決まっている","examples":[{"jp":"こんなに暑い日に運動したら、汗をかくに決まっている。","en":"It's obvious that you'll sweat if you exercise on such a hot day.","romaji":"Konna ni atsui hi ni undou shitara, ase wo kaku ni kimatte iru."},{"jp":"彼が試験に落ちたら、がっかりするに決まっている。","en":"If he fails the exam, it's obvious he will be disappointed.","romaji":"Kare ga shiken ni ochitara, gakkari suru ni kimatte iru."},{"jp":"彼女はいつも遅れるから、今日も遅れるに決まっている。","en":"She's always late, so it's obvious she'll be late today too.","romaji":"Kanojo wa itsumo okureru kara, kyou mo okureru ni kimatte iru."},{"jp":"このゲームは楽しいに決まっている。","en":"It's obvious that this game is fun.","romaji":"Kono geemu wa tanoshii ni kimatte iru."}],"example":"こんなに暑い日に運動したら、汗をかくに決まっている。","exampleMeaning":"It's obvious that you'll sweat if you exercise on such a hot day."},{"pattern":"～に沿って (〜ni sotte)","meaning":"Along with; in accordance with; following","formation":"Noun + に沿って","examples":[{"jp":"川に沿って歩いていくと、橋が見えてきます。","en":"If you walk along the river, you will see a bridge.","romaji":"Kawa ni sotte aruite iku to, hashi ga miete kimasu."},{"jp":"このレシピに沿って料理を作れば、間違いありません。","en":"If you cook according to this recipe, there will be no mistakes.","romaji":"Kono reshipi ni sotte ryouri wo tsukureba, machigai arimasen."},{"jp":"規則に沿って行動しなければなりません。","en":"We must act in accordance with the rules.","romaji":"Kisoku ni sotte koudou shinakereba narimasen."},{"jp":"山道に沿って進むと、小さな神社があります。","en":"If you follow the mountain path, there is a small shrine.","romaji":"Yamamichi ni sotte susumu to, chiisana jinja ga arimasu."}],"example":"川に沿って歩いていくと、橋が見えてきます。","exampleMeaning":"If you walk along the river, you will see a bridge."},{"pattern":"～に過ぎない (〜ni suginai)","meaning":"Expresses that something is 'just' or 'nothing more than'; 'merely', 'only', 'simply'.","formation":"Verb-casual + に過ぎない, い-Adjective + に過ぎない, な-Adjective + に過ぎない, Noun + に過ぎない","examples":[{"jp":"彼の失敗はミスに過ぎない。","en":"His failure is nothing more than a mistake.","romaji":"Kare no shippai wa misu ni suginai."},{"jp":"この試験は簡単な問題に過ぎない。","en":"This test is nothing more than a simple question.","romaji":"Kono shiken wa kantan na mondai ni suginai."},{"jp":"彼女は友達に過ぎない。","en":"She is nothing more than a friend.","romaji":"Kanojo wa tomodachi ni suginai."},{"jp":"その発言は冗談に過ぎない。","en":"That remark is nothing more than a joke.","romaji":"Sono hatsugen wa joudan ni suginai."}],"example":"彼の失敗はミスに過ぎない。","exampleMeaning":"His failure is nothing more than a mistake."},{"pattern":"～に関わって (〜ni kakawatte)","meaning":"Indicates that something is related to or influenced by a certain matter or factor; 'concerning', 'in connection with', 'regarding'.","formation":"Verb-casual + に関わって, い-Adjective + に関わって, な-Adjective + に関わって, Noun + に関わって","examples":[{"jp":"試験の内容に関わって、先生に質問があります。","en":"I have a question for the teacher regarding the content of the exam.","romaji":"Shiken no naiyou ni kakawatte, sensei ni shitsumon ga arimasu."},{"jp":"このプロジェクトに関わって、意見があれば、遠慮なく言ってください。","en":"If you have any opinions regarding this project, please feel free to express them.","romaji":"Kono purojekuto ni kakawatte, iken ga areba, enryo naku itte kudasai."},{"jp":"健康に関わって、食生活はとても重要です。","en":"Regarding health, dietary habits are very important.","romaji":"Kenkou ni kakawatte, shokuseikatsu wa totemo juuyou desu."},{"jp":"その事件に関わって、彼も少し疑われています。","en":"He is also somewhat suspected in connection with the incident.","romaji":"Sono jiken ni kakawatte, kare mo sukoshi utagawarete imasu."}],"example":"試験の内容に関わって、先生に質問があります。","exampleMeaning":"I have a question for the teacher regarding the content of the exam."},{"pattern":"～に限り (〜ni kagiri)","meaning":"Expresses limitation; 'only', 'limited to', 'exclusive to'.","formation":"Noun + に限り","examples":[{"jp":"今日に限り、この商品が半額です。","en":"Today only, this product is half price.","romaji":"Kyou ni kagiri, kono shouhin ga hangaku desu."},{"jp":"このクーポンはこの店に限り有効です。","en":"This coupon is valid only at this store.","romaji":"Kono kuupon wa kono mise ni kagiri yuukou desu."},{"jp":"会員に限り、無料でこのサービスを利用できます。","en":"Only members can use this service for free.","romaji":"Kaiin ni kagiri, muryou de kono saabisu wo riyou dekimasu."},{"jp":"この特典は先着10名に限ります。","en":"This benefit is limited to the first 10 people.","romaji":"Kono tokuten wa senchaku 10-mei ni kagirimasu."}],"example":"今日に限り、この商品が半額です。","exampleMeaning":"Today only, this product is half price."},{"pattern":"～に際して (〜ni saishite)","meaning":"Used to express the moment or the occasion of an action; 'at the time of', 'upon', 'when'.","formation":"Noun + に際して","examples":[{"jp":"卒業式に際して、校長先生がスピーチをします。","en":"At the graduation ceremony, the principal gives a speech.","romaji":"Sotsugyoushiki ni saishite, kouchou sensei ga supiichi wo shimasu."},{"jp":"この仕事に際して、責任感が大切です。","en":"Responsibility is important when doing this job.","romaji":"Kono shigoto ni saishite, sekininkan ga taisetsu desu."},{"jp":"留学に際して、ビザの手続きが必要です。","en":"Visa procedures are necessary when studying abroad.","romaji":"Ryuugaku ni saishite, biza no tetsuzuki ga hitsuyou desu."},{"jp":"結婚式に際して、両親に感謝の気持ちを伝えました。","en":"At the time of the wedding ceremony, I conveyed my gratitude to my parents.","romaji":"Kekkonshiki ni saishite, ryoushin ni kansha no kimochi wo tsutaemashita."}],"example":"卒業式に際して、校長先生がスピーチをします。","exampleMeaning":"At the graduation ceremony, the principal gives a speech."},{"pattern":"～ねばならない (〜neba naranai)","meaning":"Expresses obligation or necessity; 'must', 'have to', 'need to'.","formation":"Verb-ない form → (remove い) → ね + ばならない","examples":[{"jp":"試験に合格するために、もっと勉強せねばならない。","en":"To pass the exam, I must study more.","romaji":"Shiken ni goukaku suru tame ni, motto benkyou se neba naranai."},{"jp":"飛行機に間に合うためには、急がねばならない。","en":"To catch the flight, I must hurry.","romaji":"Hikouki ni maniau tame ni wa, isoga neba naranai."},{"jp":"６時までに帰らねばならない。","en":"I have to go home by 6 o'clock.","romaji":"Roku ji made ni kaera neba naranai."},{"jp":"この仕事を今日中に終わらせねばならない。","en":"I need to finish this work by the end of the day.","romaji":"Kono shigoto wo kyoujuu ni owarase neba naranai."}],"example":"試験に合格するために、もっと勉強せねばならない。","exampleMeaning":"To pass the exam, I must study more."},{"pattern":"～のみならず～も (〜nomi narazu 〜mo)","meaning":"Not only... but also; as well as.","formation":"Verb-casual + のみならず + (も), い-Adjective + のみならず + (も), な-Adjective + のみならず + (も), Noun + のみならず + (も)","examples":[{"jp":"彼は英語のみならず、フランス語も話せます。","en":"He can speak not only English but also French.","romaji":"Kare wa eigo nomi narazu, furansugo mo hanasemasu."},{"jp":"このレストランは美味しいのみならず、雰囲気も素晴らしいです。","en":"Not only is this restaurant delicious, but the atmosphere is also great.","romaji":"Kono resutoran wa oishii nomi narazu, fun'iki mo subarashii desu."},{"jp":"このアプリは便利のみならず、安全性も高いです。","en":"This app is not only convenient but also highly secure.","romaji":"Kono apuri wa benri nomi narazu, anzen-sei mo takai desu."},{"jp":"彼女は頭が良いのみならず、スポーツも得意です。","en":"She is not only smart but also good at sports.","romaji":"Kanojo wa atama ga ii nomi narazu, supootsu mo tokui desu."}],"example":"彼は英語のみならず、フランス語も話せます。","exampleMeaning":"He can speak not only English but also French."},{"pattern":"～のももっともだ (〜no mo mottomo da)","meaning":"Express that something is understandable or reasonable.","formation":"Verb-casual + のももっともだ, い-Adjective + のももっともだ, な-Adjective + なのももっともだ, Noun + なのももっともだ","examples":[{"jp":"彼が緊張するのももっともだ。","en":"It's understandable that he is nervous.","romaji":"Kare ga kinchou suru no mo mottomo da."},{"jp":"この問題が難しいのももっともだ。","en":"It's reasonable that this problem is difficult.","romaji":"Kono mondai ga muzukashii no mo mottomo da."},{"jp":"彼女が幸せなのももっともだ。","en":"It's understandable that she is happy.","romaji":"Kanojo ga shiawase na no mo mottomo da."},{"jp":"彼がリーダーなのももっともだ。","en":"It's reasonable that he is the leader.","romaji":"Kare ga riidaa na no mo mottomo da."}],"example":"彼が緊張するのももっともだ。","exampleMeaning":"It's understandable that he is nervous."},{"pattern":"〜の上では (〜no ue de wa)","meaning":"Indicates 'on the basis of', 'in terms of', or 'from the standpoint of'.","formation":"Noun or Phrase + の上では","examples":[{"jp":"効率の上では、この方法が最適です。","en":"In terms of efficiency, this method is the best.","romaji":"Kouritsu no ue de wa, kono houhou ga saiteki desu."},{"jp":"法律の上では、彼の行為は違法ではありません。","en":"From a legal standpoint, his actions are not illegal.","romaji":"Houritsu no ue de wa, kare no koui wa ihan dewa arimasen."},{"jp":"味の上では、このレストランは評価が高いです。","en":"In terms of taste, this restaurant has a high rating.","romaji":"Aji no ue de wa, kono resutoran wa hyouka ga takai desu."},{"jp":"成績の上では、彼はクラスで一番優秀です。","en":"On the basis of grades, he is the most outstanding student in the class.","romaji":"Seiseki no ue de wa, kare wa kurasu de ichiban yuushuu desu."}],"example":"効率の上では、この方法が最適です。","exampleMeaning":"In terms of efficiency, this method is the best."},{"pattern":"～の下で (〜no shita de)","meaning":"Under the context or condition of; under.","formation":"Verb-casual + の下で, い-Adjective + の下で, な-Adjective + の下で, Noun + の下で","examples":[{"jp":"先生の下で勉強するのはとても楽しいです。","en":"Studying under the teacher is very enjoyable.","romaji":"Sensei no shita de benkyou suru no wa totemo tanoshii desu."},{"jp":"晴天の下でピクニックをしましょう。","en":"Let's have a picnic under the clear sky.","romaji":"Seiten no shita de pikunikku wo shimashou."},{"jp":"緊張感の下で、彼女はスピーチに成功しました。","en":"Under pressure, she succeeded in her speech.","romaji":"Kinchoukan no shita de, kanojo wa supiichi ni seikou shimashita."},{"jp":"親の愛情の下で、子供たちは幸せに育ちます。","en":"Under the love of their parents, children grow up happily.","romaji":"Oya no aijou no shita de, kodomo-tachi wa shiawase ni sodachimasu."}],"example":"先生の下で勉強するのはとても楽しいです。","exampleMeaning":"Studying under the teacher is very enjoyable."},{"pattern":"～ばかりか〜も (〜bakari ka 〜 mo)","meaning":"Expresses 'not only... but also'; emphasizing the extent of something.","formation":"Noun/Verb/Adjective + ばかりか + Noun/Verb/Adjective + も","examples":[{"jp":"彼はかわいいばかりか、賢くもある。","en":"He is not only cute but also smart.","romaji":"Kare wa kawaii bakari ka, kashikoku mo aru."},{"jp":"このレストランは味が良いばかりかサービスも素晴らしいです。","en":"This restaurant not only has great taste but also wonderful service.","romaji":"Kono resutoran wa aji ga yoi bakari ka saabisu mo subarashii desu."},{"jp":"彼女は日本語が上手ばかりか英語も話せる。","en":"She can speak not only Japanese but also English.","romaji":"Kanojo wa nihongo ga jouzu bakari ka eigo mo hanaseru."},{"jp":"彼は歌が上手いばかりかダンスもうまい。","en":"He is not only good at singing but also dancing.","romaji":"Kare wa uta ga umai bakari ka dansu mo umai."}],"example":"彼はかわいいばかりか、賢くもある。","exampleMeaning":"He is not only cute but also smart."},{"pattern":"～ばかりだ (〜bakari da)","meaning":"Express a continuing state or negative tendency; 'just', 'only', 'always'.","formation":"Verb-てform + ばかりだ, い-Adjective + ばかりだ, な-Adjective + ばかりだ, Noun + ばかりだ","examples":[{"jp":"彼は文句を言ってばかりだ。","en":"He is always complaining.","romaji":"Kare wa monku wo itte bakari da."},{"jp":"この映画は面白くなくて、退屈してばかりだ。","en":"This movie isn't interesting, and I'm just bored.","romaji":"Kono eiga wa omoshirokunakute, taikutsu shite bakari da."},{"jp":"彼女は暇でいるばかりだ。","en":"She is always just idling around with nothing to do.","romaji":"Kanojo wa hima de iru bakari da."},{"jp":"最近、仕事の失敗ばかりだ。","en":"Lately, it’s just been one failure at work after another.","romaji":"Saikin, shigoto no shippai bakari da."}],"example":"彼は文句を言ってばかりだ。","exampleMeaning":"He is always complaining."},{"pattern":"～ばかりに (〜bakari ni)","meaning":"Express an undesired situation or result caused by something; 'simply because', 'due to', 'on account of'.","formation":"Verb-casual + ばかりに, い-Adjective + ばかりに, な-Adjective + なばかりに, Noun + なばかりに","examples":[{"jp":"雨が降ったばかりに、試合が中止になりました。","en":"Simply because it rained, the match was cancelled.","romaji":"Ame ga futta bakari ni, shiai ga chuushi ni narimashita."},{"jp":"彼が遅れたばかりに、私たちも遅刻しました。","en":"Because he was late, we ended up being late too.","romaji":"Kare ga okureta bakari ni, watashitachi mo chikoku shimashita."},{"jp":"忘れ物をしたばかりに、買い物に戻らなければなりません。","en":"Simply because I forgot something, I have to go back to the store.","romaji":"Wasuremono wo shita bakari ni, kaimono ni modoranakereba narimasen."},{"jp":"彼女が美人なばかりに、みんなが彼女を羨んでいます。","en":"Just because she is beautiful, everyone is envious of her.","romaji":"Kanojo ga bijin na bakari ni, minna ga kanojo wo urayande imasu."}],"example":"雨が降ったばかりに、試合が中止になりました。","exampleMeaning":"Simply because it rained, the match was cancelled."},{"pattern":"～ば～というものでもない (〜ba 〜to iu mono demo nai)","meaning":"Not necessarily true that if A, then B.","formation":"Verb-ば form + というものでもない","examples":[{"jp":"高いものがいいものばかりではない。","en":"Expensive things are not always good.","romaji":"Takai mono ga ii mono bakari de wa nai."},{"jp":"英語ができれば、成功するというものでもない。","en":"Just because you can speak English doesn’t mean you’ll succeed.","romaji":"Eigo ga dekireba, seikou suru to iu mono demo nai."},{"jp":"見た目が美しいからといって、心も美しいというものでもない。","en":"Just because someone is beautiful on the outside, it doesn’t mean they’re beautiful on the inside.","romaji":"Mitame ga utsukushii kara to itte, kokoro mo utsukushii to iu mono demo nai."},{"jp":"有名大学に入れば、将来が安泰だというものでもない。","en":"Getting into a famous university doesn’t guarantee a secure future.","romaji":"Yuumei daigaku ni haireba, shourai ga antai da to iu mono demo nai."}],"example":"高いものがいいものばかりではない。","exampleMeaning":"Expensive things are not always good."},{"pattern":"～はともかく～は (〜wa tomokaku 〜wa)","meaning":"Used to compare or contrast two elements; 'as for...'.","formation":"Noun1 はともかく Noun2 は","examples":[{"jp":"デザインはともかく、機能はこの携帯電話が一番です。","en":"As for design, the functionality of this phone is the best.","romaji":"Dezain wa tomokaku, kinou wa kono keitai denwa ga ichiban desu."},{"jp":"彼の容姿はともかく、性格は素晴らしいです。","en":"Putting aside his looks, his personality is wonderful.","romaji":"Kare no youshi wa tomokaku, seikaku wa subarashii desu."},{"jp":"料理の味はともかく、盛り付けは綺麗です。","en":"Putting aside the taste of the food, the presentation is beautiful.","romaji":"Ryouri no aji wa tomokaku, moritsuke wa kirei desu."},{"jp":"値段はともかく、このバッグの質は良いです。","en":"Ignoring the price, this bag’s quality is good.","romaji":"Nedan wa tomokaku, kono baggu no shitsu wa yoi desu."}],"example":"デザインはともかく、機能はこの携帯電話が一番です。","exampleMeaning":"As for design, the functionality of this phone is the best."},{"pattern":"～はまだしも (〜wa mada shimo)","meaning":"Expresses that while the first item is somewhat acceptable, the second item is not.","formation":"Noun1 + はまだしも + Noun2","examples":[{"jp":"失敗するのはまだしも、やらないで後悔する方がつらい。","en":"Failing is one thing, but regretting not even trying is worse.","romaji":"Shippai suru no wa mada shimo, yaranai de koukai suru hou ga tsurai."},{"jp":"このピザは野菜が少ないのはまだしも、味も悪い。","en":"It’s not just that this pizza has few vegetables, it also tastes bad.","romaji":"Kono piza wa yasai ga sukunai no wa mada shimo, aji mo warui."},{"jp":"たまに遅刻するのはまだしも、連絡もせずに遅刻するのは許せない。","en":"Being late occasionally might be forgivable, but being late without any contact is unacceptable.","romaji":"Tama ni chikoku suru no wa mada shimo, renraku mo sezu ni chikoku suru no wa yurusenai."},{"jp":"難しい質問に答えられないのはまだしも、簡単な質問にも答えられないのは問題だ。","en":"It’s one thing not to be able to answer difficult questions, but it’s a real problem if you can’t even answer simple ones.","romaji":"Muzukashii shitsumon ni kotaerarenai no wa mada shimo, kantan na shitsumon ni mo kotaerarenai no wa mondai da."}],"example":"失敗するのはまだしも、やらないで後悔する方がつらい。","exampleMeaning":"Failing is one thing, but regretting not even trying is worse."},{"pattern":"～はもとより (〜wa moto yori)","meaning":"Expressing that something is obvious, and there is also something else.","formation":"Noun1 + はもとより, Noun2 + も","examples":[{"jp":"英語はもとより、スペイン語も勉強しています。","en":"I'm studying not only English, but also Spanish.","romaji":"Eigo wa moto yori, supeingo mo benkyou shite imasu."},{"jp":"彼女は料理はもとより、お菓子作りも得意です。","en":"She’s not only good at cooking, but also at making sweets.","romaji":"Kanojo wa ryouri wa moto yori, okashi tsukuri mo tokui desu."},{"jp":"このホテルは部屋の清潔さはもとより、サービスも素晴らしいです。","en":"This hotel not only has clean rooms but also great service.","romaji":"Kono hoteru wa heya no seiketsusa wa moto yori, saabisu mo subarashii desu."},{"jp":"彼は音楽はもとより、絵も上手です。","en":"He’s not only good at music, but also skilled at drawing.","romaji":"Kare wa ongaku wa moto yori, e mo jouzu desu."}],"example":"英語はもとより、スペイン語も勉強しています。","exampleMeaning":"I'm studying not only English, but also Spanish."},{"pattern":"～は抜きにして (〜wa nuki ni shite)","meaning":"Leaving aside, excluding.","formation":"Noun + は抜きにして","examples":[{"jp":"値段は抜きにして、味は美味しい。","en":"Leaving aside the price, the taste is delicious.","romaji":"Nedan wa nuki ni shite, aji wa oishii."},{"jp":"彼の性格は抜きにして、彼の実力は認めざるを得ない。","en":"Putting aside his personality, I have to acknowledge his ability.","romaji":"Kare no seikaku wa nuki ni shite, kare no jitsuryoku wa mitomezaru o enai."},{"jp":"デザインは抜きにして、この携帯電話の機能は優れています。","en":"Leaving aside the design, this phone’s features are excellent.","romaji":"Dezain wa nuki ni shite, kono keitai denwa no kinou wa sugurete imasu."},{"jp":"運転の速さは抜きにして、彼女は親切で信頼できる運転手だ。","en":"Leaving aside her driving speed, she's a kind and trustworthy driver.","romaji":"Unten no hayasa wa nuki ni shite, kanojo wa shinsetsu de shinrai dekiru untenshu da."}],"example":"値段は抜きにして、味は美味しい。","exampleMeaning":"Leaving aside the price, the taste is delicious."},{"pattern":"～べきではない (〜beki dewa nai)","meaning":"Express that an action should not be done; 'should not', 'ought not to'.","formation":"Verb-dictionary form + べき + ではない","examples":[{"jp":"遅れる理由がないなら、遅れるべきではありません。","en":"If there's no reason to be late, you shouldn’t be late.","romaji":"Okureru riyuu ga nai nara, okureru beki dewa arimasen."},{"jp":"子供に悪口を言うべきではありません。","en":"You shouldn’t say hurtful things to children.","romaji":"Kodomo ni waruguchi o iu beki dewa arimasen."},{"jp":"この薬は一度に飲みすぎるべきではない。","en":"You should not take too much of this medicine at once.","romaji":"Kono kusuri wa ichido ni nomisugiru beki dewa nai."},{"jp":"知らない人と個人情報を共有するべきではない。","en":"You shouldn't share personal information with strangers.","romaji":"Shiranai hito to kojin jouhou o kyouyuu suru beki dewa nai."}],"example":"遅れる理由がないなら、遅れるべきではありません。","exampleMeaning":"If there's no reason to be late, you shouldn’t be late."},{"pattern":"～まい (〜mai)","meaning":"Express a negative conjecture or determination; 'probably not' or 'I will not'.","formation":"Verb-dictionary form + まい","examples":[{"jp":"彼は今晩来るまい。","en":"He probably won't come tonight.","romaji":"Kare wa konban kuru mai."},{"jp":"こんなに遅れては、電車に間に合うまい。","en":"Being this late, I probably won't make it for the train.","romaji":"Konnani okurete wa, densha ni maniau mai."},{"jp":"あの人は絶対に忘れるまい。","en":"That person will definitely not forget.","romaji":"Ano hito wa zettai ni wasureru mai."},{"jp":"私は二度とその失敗を繰り返すまい。","en":"I will not repeat that mistake again.","romaji":"Watashi wa nidoto sono shippai o kurikaesu mai."}],"example":"彼は今晩来るまい。","exampleMeaning":"He probably won't come tonight."},{"pattern":"～まで～て (〜made 〜te)","meaning":"Express doing something until a certain time or condition; 'until', 'to'.","formation":"Time/Noun + まで + Verb(て-form)","examples":[{"jp":"9時まで働いて、その後休憩しました。","en":"I worked until 9 o'clock, and then took a break.","romaji":"Ku-ji made hataraite, sono ato kyuukei shimashita."},{"jp":"夜まで勉強して、試験に合格しました。","en":"I studied until night, and passed the exam.","romaji":"Yoru made benkyou shite, shiken ni goukaku shimashita."},{"jp":"最後のページまで読んで、本を閉じました。","en":"I read until the last page, then closed the book.","romaji":"Saigo no peeji made yonde, hon o tojimashita."},{"jp":"電車が着くまで待って、友達と会いました。","en":"I waited until the train arrived, and then met my friend.","romaji":"Densha ga tsuku made matte, tomodachi to aimashita."}],"example":"9時まで働いて、その後休憩しました。","exampleMeaning":"I worked until 9 o'clock, and then took a break."},{"pattern":"～ままに (〜mama ni)","meaning":"Act according to; leave as is; unchanged.","formation":"Verb-て + まま, い-Adjective + のまま, な-Adjective + なまま, Noun + のまま","examples":[{"jp":"子供が寝ているままに、静かに部屋を出ました。","en":"I quietly left the room while the child was still sleeping.","romaji":"Kodomo ga nete iru mama ni, shizuka ni heya o demashita."},{"jp":"窓が開いたままで、寒くなりました。","en":"It got cold with the window left open.","romaji":"Mado ga aita mama de, samuku narimashita."},{"jp":"彼は元気なままで老人ホームに入りました。","en":"He entered the nursing home while still in good health.","romaji":"Kare wa genki na mama de roujin hoomu ni hairimashita."},{"jp":"昔の思い出のままに、この町に戻りました。","en":"I returned to this town with my old memories intact.","romaji":"Mukashi no omoide no mama ni, kono machi ni modorimashita."}],"example":"子供が寝ているままに、静かに部屋を出ました。","exampleMeaning":"I quietly left the room while the child was still sleeping."},{"pattern":"～もかまわず (〜mo kamawazu)","meaning":"Express indifference or disregard; 'without hesitating', 'without worrying about'.","formation":"Verb-dictionary form + もかまわず, Noun + もかまわず","examples":[{"jp":"彼は周りの人もかまわず、大声で話しました。","en":"Without worrying about the people around him, he spoke loudly.","romaji":"Kare wa mawari no hito mo kamawazu, oogoe de hanashimashita."},{"jp":"彼女は時間もかまわず、ゆっくりと本を読み続けました。","en":"She kept reading the book leisurely, without worrying about the time.","romaji":"Kanojo wa jikan mo kamawazu, yukkuri to hon o yomitsuzukemashita."},{"jp":"彼は寒さもかまわず、外で運動しました。","en":"He exercised outside without worrying about the cold.","romaji":"Kare wa samusa mo kamawazu, soto de undou shimashita."},{"jp":"彼女は危険もかまわず、火事の中に飛び込んで助けに行きました。","en":"She jumped into the fire without fear of danger to help.","romaji":"Kanojo wa kiken mo kamawazu, kaji no naka ni tobikonde tasuke ni ikimashita."}],"example":"彼は周りの人もかまわず、大声で話しました。","exampleMeaning":"Without worrying about the people around him, he spoke loudly."},{"pattern":"～ものか (〜mono ka)","meaning":"Definitely not; no way; no chance.","formation":"Verb-casual + ものか, い-Adjective + ものか, な-Adjective + (な)ものか, Noun + (な)ものか","examples":[{"jp":"そんなこと、僕がやりたいものか。","en":"No way do I want to do such a thing.","romaji":"Sonna koto, boku ga yaritai mono ka."},{"jp":"こんな仕事、誰が引き受けようものか。","en":"Who on earth would take on a job like this? (No one would!)","romaji":"Konna shigoto, dare ga hikiukeyou mono ka."},{"jp":"誰が彼に助けを求めようものか。","en":"Who would ever ask him for help? (Certainly no one!)","romaji":"Dare ga kare ni tasuke o motomeyou mono ka."},{"jp":"この寒い日に外で遊ぶなんて、無理なものか。","en":"There's no way we can play outside on a day this cold.","romaji":"Kono samui hi ni soto de asobu nante, muri na mono ka."}],"example":"そんなこと、僕がやりたいものか。","exampleMeaning":"No way do I want to do such a thing."},{"pattern":"～ものがある (〜mono ga aru)","meaning":"Express a strong impression or feeling; 'there's something about it that...'","formation":"Verb-casual + ものがある, い-Adjective + ものがある, な-Adjective + なものがある","examples":[{"jp":"彼のスピーチには心を打たれるものがある。","en":"There's something moving about his speech.","romaji":"Kare no supiichi ni wa kokoro o utareru mono ga aru."},{"jp":"この映画には考えさせられるものがある。","en":"There's something about this movie that really makes you think.","romaji":"Kono eiga ni wa kangaesaserareru mono ga aru."},{"jp":"彼の言うことにも一理あるものがある。","en":"There's a certain point in what he says.","romaji":"Kare no iu koto ni mo ichiri aru mono ga aru."},{"jp":"毎日忙しすぎる生活には少し息苦しいものがある。","en":"There's something a bit suffocating about being so busy every day.","romaji":"Mainichi isogashisugiru seikatsu ni wa sukoshi ikigurushii mono ga aru."}],"example":"彼のスピーチには心を打たれるものがある。","exampleMeaning":"There's something moving about his speech."},{"pattern":"～ものだ (〜mono da)","meaning":"Expresses something natural or expected; 'it is normal that...', 'should', 'ought to'.","formation":"Verb-dictionary form + ものだ, な-Adjective + なものだ, (Also: Verb-た form + ものだ for recollections)","examples":[{"jp":"若い時はたくさん遊ぶものだ。","en":"It is natural to have a lot of fun when you are young.","romaji":"Wakai toki wa takusan asobu mono da."},{"jp":"約束をしたら、守るものだ。","en":"If you make a promise, you should keep it.","romaji":"Yakusoku o shitara, mamoru mono da."},{"jp":"お客さんが来ると、お茶を出すものだ。","en":"When guests arrive, it's customary to serve tea.","romaji":"Okyakusan ga kuru to, ocha o dasu mono da."},{"jp":"人生は困難に立ち向かうものだ。","en":"In life, one ought to face hardships.","romaji":"Jinsei wa konnan ni tachimukau mono da."}],"example":"若い時はたくさん遊ぶものだ。","exampleMeaning":"It is natural to have a lot of fun when you are young."},{"pattern":"～ものだから (〜mono dakara)","meaning":"Express the reason or cause for something; 'because', 'since', 'due to'.","formation":"Verb-plain + ものだから, い-Adjective + ものだから, な-Adjective + なものだから, Noun + なものだから","examples":[{"jp":"試験が近いものだから、毎日勉強しています。","en":"Because the exam is near, I'm studying every day.","romaji":"Shiken ga chikai mono dakara, mainichi benkyou shiteimasu."},{"jp":"このレストランはとても人気があるものだから、予約しないと席がないかもしれません。","en":"Because this restaurant is very popular, there might not be any seats if we don't reserve.","romaji":"Kono resutoran wa totemo ninki ga aru mono dakara, yoyaku shinai to seki ga nai kamoshiremasen."},{"jp":"彼は若いものだから、まだたくさんの経験を積んでいない。","en":"Because he is young, he hasn't accumulated much experience yet.","romaji":"Kare wa wakai mono dakara, mada takusan no keiken wo tsunde inai."},{"jp":"今日は寒いものだから、手袋を持って行きましょう。","en":"Since it's cold today, let's bring gloves.","romaji":"Kyou wa samui mono dakara, tebukuro wo motte ikimashou."}],"example":"試験が近いものだから、毎日勉強しています。","exampleMeaning":"Because the exam is near, I'm studying every day."},{"pattern":"～ものではない (〜mono dewa nai)","meaning":"Expresses a strong negative suggestion or prohibition: 'should not', 'must not'.","formation":"Verb-dictionary form + ものではない","examples":[{"jp":"そんなことを言うものではありません。","en":"You should not say such a thing.","romaji":"Sonna koto o iu mono dewa arimasen."},{"jp":"公共の場で大声を出すものではない。","en":"You should not raise your voice in public places.","romaji":"Koukyou no ba de oogoe o dasu mono dewa nai."},{"jp":"彼の秘密を他の人に教えるものではありません。","en":"You must not tell his secret to other people.","romaji":"Kare no himitsu o hoka no hito ni oshieru mono dewa arimasen."},{"jp":"安全な場所では遊んでいいが、危険なところで遊ぶものではない。","en":"It's okay to play in safe places, but you should not play somewhere dangerous.","romaji":"Anzen na basho de wa asonde ii ga, kiken na tokoro de asobu mono dewa nai."}],"example":"そんなことを言うものではありません。","exampleMeaning":"You should not say such a thing."},{"pattern":"～ものなら (〜mono nara)","meaning":"Expresses a conditional wish or unlikely possibility; 'if only', 'if it were possible'.","formation":"Verb-(potential/plain) form + ものなら, etc.","examples":[{"jp":"帰れるものなら、今すぐ国へ帰りたい。","en":"If I could possibly go back, I'd return to my country right now.","romaji":"Kaereru mono nara, ima sugu kuni e kaeritai."},{"jp":"できるものなら、世界を一周してみたい。","en":"If it were possible, I'd love to travel around the world.","romaji":"Dekiru mono nara, sekai o isshuu shite mitai."},{"jp":"やり直せるものなら、子供の頃に戻りたい。","en":"If I could redo my life, I'd go back to my childhood.","romaji":"Yarinaoseru mono nara, kodomo no koro ni modoritai."},{"jp":"元気になれるものなら、どんな薬でも試したい。","en":"If it could make me healthy, I'd try any medicine.","romaji":"Genki ni nareru mono nara, donna kusuri demo tameshitai."}],"example":"帰れるものなら、今すぐ国へ帰りたい。","exampleMeaning":"If I could possibly go back, I'd return to my country right now."},{"pattern":"～ものの、～ (〜mono no、～)","meaning":"Indicates contrast or contradiction between two clauses; 'although', 'but'.","formation":"Verb-casual + ものの, い-Adjective + ものの, な-Adjective + なものの, Noun + であるものの","examples":[{"jp":"早起きしたものの、バスに間に合わなかった。","en":"Even though I got up early, I didn't catch the bus in time.","romaji":"Hayaoki shita mono no, basu ni maniawanakatta."},{"jp":"この部屋は広いものの、家具が少ない。","en":"Although this room is spacious, there isn't much furniture.","romaji":"Kono heya wa hiroi mono no, kagu ga sukunai."},{"jp":"彼女は美しいものの、性格が悪い。","en":"She is beautiful, but her personality is bad.","romaji":"Kanojo wa utsukushii mono no, seikaku ga warui."},{"jp":"彼は有名な歌手であるものの、コンサートにあまり人が来なかった。","en":"Although he is a famous singer, not many people came to his concert.","romaji":"Kare wa yuumei na kashu de aru mono no, konsaato ni amari hito ga konakatta."}],"example":"早起きしたものの、バスに間に合わなかった。","exampleMeaning":"Even though I got up early, I didn't catch the bus in time."},{"pattern":"～も～ば～も～ (〜mo〜ba〜mo〜)","meaning":"Lists multiple attributes or actions applying to the same subject: 'both…and…', 'not only…but also…'.","formation":"Noun/Verb/Adjective + も + (Verb/Adjective in ば-form) + も + (Verb/Adjective)","examples":[{"jp":"彼は勉強もできればスポーツもできる。","en":"He is good at studying and also at sports.","romaji":"Kare wa benkyou mo dekireba supootsu mo dekiru."},{"jp":"このレストランは値段も安ければ味もいい。","en":"This restaurant is cheap, and the food is also good.","romaji":"Kono resutoran wa nedan mo yasukereba aji mo ii."},{"jp":"彼女はピアノも弾けばギターも弾く。","en":"She plays both the piano and the guitar.","romaji":"Kanojo wa piano mo hikeba gitaa mo hiku."},{"jp":"人生には楽しい時もあれば辛い時もある。","en":"In life, there are both fun times and tough times.","romaji":"Jinsei ni wa tanoshii toki mo areba tsurai toki mo aru."}],"example":"彼は勉強もできればスポーツもできる。","exampleMeaning":"He is good at studying and also at sports."},{"pattern":"～も同然だ (〜mo douzen da)","meaning":"Indicates 'as good as', 'virtually', or 'practically' the same as something.","formation":"Noun + (も)同然だ, Verb-casual + (も)同然だ, etc.","examples":[{"jp":"彼とは長い付き合いだから、家族も同然だ。","en":"I've known him for so long that he's practically family.","romaji":"Kare to wa nagai tsukiai dakara, kazoku mo douzen da."},{"jp":"毎日遅刻するなんて、来ていないも同然だ。","en":"Being late every single day is as good as not coming at all.","romaji":"Mainichi chikoku suru nante, kite inai mo douzen da."},{"jp":"彼女と私は幼なじみで、姉妹も同然の仲です。","en":"She and I are childhood friends, practically like sisters.","romaji":"Kanojo to watashi wa osananajimi de, shimai mo douzen no naka desu."},{"jp":"こんなに少ない給料じゃ、ただ働きも同然だ。","en":"With such a small salary, it's practically like working for free.","romaji":"Konna ni sukunai kyuuryou ja, tadabataraki mo douzen da."}],"example":"彼とは長い付き合いだから、家族も同然だ。","exampleMeaning":"I've known him for so long that he's practically family."},{"pattern":"～やら～やら (〜yara〜yara)","meaning":"Expresses various items or actions, 'things like..., and so on'.","formation":"Verb-casual + やら, い-Adjective + やら, な-Adjective + やら, Noun + やら","examples":[{"jp":"宿題やら掃除やら、やることがたくさんある。","en":"I have lots of things to do, like homework and cleaning.","romaji":"Shukudai yara souji yara, yaru koto ga takusan aru."},{"jp":"野菜やら果物やら、色々な食べ物を買いました。","en":"I bought all sorts of foods, such as vegetables and fruits.","romaji":"Yasai yara kudamono yara, iroiro na tabemono wo kaimashita."},{"jp":"彼女は歌がうまいやら踊れるやら、本当に多才だ。","en":"She’s really talented—she can sing well, dance, and so on.","romaji":"Kanojo wa uta ga umai yara odoreru yara, hontou ni tasai da."},{"jp":"お店にはバッグやら靴やらアクセサリーやらが置いてある。","en":"The store has all kinds of items like bags, shoes, accessories, etc.","romaji":"Omise ni wa baggu yara kutsu yara akusesarii yara ga oite aru."}],"example":"宿題やら掃除やら、やることがたくさんある。","exampleMeaning":"I have lots of things to do, like homework and cleaning."},{"pattern":"～ようがない (〜you ga nai)","meaning":"Expresses that there is no way (method) to do something; it's impossible to do.","formation":"Verb-ます stem + ようがない","examples":[{"jp":"彼の連絡先がわからないので、助けようがない。","en":"I don't know his contact information, so there's no way I can help him.","romaji":"Kare no renrakusaki ga wakaranai node, tasukeyou ga nai."},{"jp":"ここまで壊れてしまったら、もう直しようがない。","en":"Now that it's broken this badly, there's no way to fix it.","romaji":"Koko made kowarete shimattara, mou naoshiyou ga nai."},{"jp":"証拠が全くないから、彼が犯人だと証明しようがない。","en":"There’s no evidence at all, so there’s no way to prove he’s the culprit.","romaji":"Shouko ga mattaku nai kara, kare ga hannin da to shoumeishiyou ga nai."},{"jp":"突然英語で話しかけられて、何と答えればいいか分からず答えようがなかった。","en":"I was suddenly spoken to in English and didn’t know how to respond, so there was no way for me to reply.","romaji":"Totsuzen eigo de hanashikakerarete, nan to kotaereba ii ka wakarazu kotaeyou ga nakatta."}],"example":"彼の連絡先がわからないので、助けようがない。","exampleMeaning":"I don't know his contact information, so there's no way I can help him."},{"pattern":"～よりほかない (〜yori hoka nai)","meaning":"Express that there is no other choice; 'have no choice but', 'cannot do anything but'.","formation":"Verb-dictionary form + よりほかない","examples":[{"jp":"試験が近いので、勉強するよりほかない。","en":"Since the exam is near, there is no choice but to study.","romaji":"Shiken ga chikai node, benkyou suru yori hoka nai."},{"jp":"風邪がひどいので、早く寝るよりほかない。","en":"My cold is severe, so I have no choice but to go to bed early.","romaji":"Kaze ga hidoi node, hayaku neru yori hoka nai."},{"jp":"バスが来ないので、歩くよりほかない。","en":"Since the bus isn't coming, I have no choice but to walk.","romaji":"Basu ga konai node, aruku yori hoka nai."},{"jp":"お金がないので、安いものを買うよりほかない。","en":"Since I have no money, I have no choice but to buy cheap things.","romaji":"Okane ga nai node, yasui mono o kau yori hoka nai."}],"example":"試験が近いので、勉強するよりほかない。","exampleMeaning":"Since the exam is near, there is no choice but to study."},{"pattern":"～わけがない (〜wake ga nai)","meaning":"Expresses 'there’s no way' or 'it’s impossible', indicating a high degree of certainty.","formation":"Verb-casual + わけがない, い-Adjective + わけがない, な-Adjective + なわけがない, Noun + のわけがない","examples":[{"jp":"彼が怪我をしたから、試合に勝てるわけがない。","en":"He got injured, so there's no way he can win the match.","romaji":"Kare ga kega wo shita kara, shiai ni kateru wake ga nai."},{"jp":"嘘ばかり言っている人を、信じるわけがない。","en":"There's no way I can believe someone who constantly lies.","romaji":"Uso bakari itte iru hito wo, shinjiru wake ga nai."},{"jp":"彼女は忙しいから、このパーティーに来るわけがない。","en":"She's busy, so there's no way she can come to this party.","romaji":"Kanojo wa isogashii kara, kono paatii ni kuru wake ga nai."},{"jp":"昨日はずっと寝ていたから、その事件を知るわけがない。","en":"I was asleep all day yesterday, so there's no way I could know about that incident.","romaji":"Kinou wa zutto nete ita kara, sono jiken wo shiru wake ga nai."}],"example":"彼が怪我をしたから、試合に勝てるわけがない。","exampleMeaning":"He got injured, so there's no way he can win the match."},{"pattern":"～わけだ (〜wake da)","meaning":"Express a logical conclusion or reason; 'it means', 'no wonder', 'the reason is'.","formation":"Verb-casual + わけだ, い-Adjective + わけだ, な-Adjective + なわけだ, Noun + のわけだ","examples":[{"jp":"彼女が遅れたのは、電車が遅れたわけだ。","en":"The reason she was late is that the train was delayed.","romaji":"Kanojo ga okureta no wa, densha ga okureta wake da."},{"jp":"授業が面白かったから、みんな熱心に聞いていたわけだ。","en":"The class was interesting, so that's why everyone was listening intently.","romaji":"Jugyou ga omoshirokatta kara, minna nesshin ni kiiteita wake da."},{"jp":"彼はとても忙しいですから、休みがほとんどないわけだ。","en":"He's really busy, which is why he hardly has any time off.","romaji":"Kare wa totemo isogashii desu kara, yasumi ga hotondo nai wake da."},{"jp":"この問題が難しいから、全然わからないわけだ。","en":"This problem is tough, so no wonder I don't understand it at all.","romaji":"Kono mondai ga muzukashii kara, zenzen wakaranai wake da."}],"example":"彼女が遅れたのは、電車が遅れたわけだ。","exampleMeaning":"The reason she was late is that the train was delayed."},{"pattern":"～わけではない (〜wake dewa nai)","meaning":"Not necessarily; it doesn't mean that ~.","formation":"Verb-plain + わけではない, い-Adjective + わけではない, な-Adjective + だわけではない, Noun + だわけではない","examples":[{"jp":"彼が勉強しないわけではないが、成績があまり良くない。","en":"It's not that he doesn't study, but his grades aren't very good.","romaji":"Kare ga benkyou shinai wake dewa nai ga, seiseki ga amari yoku nai."},{"jp":"このレストランが高いわけではないけど、毎日通うには少し高いね。","en":"It's not that this restaurant is expensive, but it's a bit too pricey to go there every day.","romaji":"Kono resutoran ga takai wake dewa nai kedo, mainichi kayou ni wa sukoshi takai ne."},{"jp":"彼女が優しくないわけではないが、時々話し方がきついことがある。","en":"It's not that she's unkind, but sometimes her manner of speaking can be harsh.","romaji":"Kanojo ga yasashikunai wake dewa nai ga, tokidoki hanashikata ga kitsui koto ga aru."},{"jp":"彼が忙しいわけではないが、時間を上手に使えていないようだ。","en":"It's not that he's busy; he just doesn't seem to use his time effectively.","romaji":"Kare ga isogashii wake dewa nai ga, jikan o jouzu ni tsukaete inai you da."}],"example":"彼が勉強しないわけではないが、成績があまり良くない。","exampleMeaning":"It's not that he doesn't study, but his grades aren't very good."},{"pattern":"～わけにはいかない (〜wake ni wa ikanai)","meaning":"Expresses that one cannot (or must not) do something due to responsibility, social pressure, etc.","formation":"Verb-dictionary form + わけにはいかない","examples":[{"jp":"試験が近いから、遊ぶわけにはいかない。","en":"Since the exam is close, I can't afford to just play around.","romaji":"Shiken ga chikai kara, asobu wake ni wa ikanai."},{"jp":"田中さんが待っているので、遅れるわけにはいかない。","en":"Mr. Tanaka is waiting, so I absolutely must not be late.","romaji":"Tanaka-san ga matteiru node, okureru wake ni wa ikanai."},{"jp":"子供たちのために、この仕事を辞めるわけにはいかない。","en":"For the sake of my kids, I can't afford to quit this job.","romaji":"Kodomo-tachi no tame ni, kono shigoto o yameru wake ni wa ikanai."},{"jp":"この問題は重要だから、無視するわけにはいかない。","en":"This issue is important, so I can't simply ignore it.","romaji":"Kono mondai wa juuyou dakara, mushi suru wake ni wa ikanai."}],"example":"試験が近いから、遊ぶわけにはいかない。","exampleMeaning":"Since the exam is close, I can't afford to just play around."},{"pattern":"～をきっかけに (〜wo kikkake ni)","meaning":"Indicates that something serves as a trigger or starting point for another action/event.","formation":"Noun + をきっかけに","examples":[{"jp":"結婚をきっかけに、彼は真剣に仕事を頑張り始めた。","en":"Getting married was the catalyst for him to start working seriously.","romaji":"Kekkon o kikkake ni, kare wa shinken ni shigoto o ganbarihajimeta."},{"jp":"あの出会いをきっかけに、私たちは友達になりました。","en":"That encounter led us to become friends.","romaji":"Ano deai o kikkake ni, watashitachi wa tomodachi ni narimashita."},{"jp":"コンサートをきっかけに、彼女は音楽の道に進むことを決めました。","en":"Inspired by the concert, she decided to pursue music.","romaji":"Konsaato o kikkake ni, kanojo wa ongaku no michi ni susumu koto o kimemashita."},{"jp":"留学をきっかけに、私の外国語スキルが向上しました。","en":"Studying abroad gave me the chance to improve my foreign language skills.","romaji":"Ryuugaku o kikkake ni, watashi no gaikokugo sukiru ga koujou shimashita."}],"example":"結婚をきっかけに、彼は真剣に仕事を頑張り始めた。","exampleMeaning":"Getting married was the catalyst for him to start working seriously."},{"pattern":"～を～として (〜wo〜toshite)","meaning":"Express 'as', 'in the capacity of', or 'taking something as...'.","formation":"Noun1 + を + Noun2 + として","examples":[{"jp":"彼は教師を職業として働いています。","en":"He works as a teacher.","romaji":"Kare wa kyoushi o shokugyou toshite hataraite imasu."},{"jp":"彼女はリーダーを役割として受け入れました。","en":"She accepted the role of leader.","romaji":"Kanojo wa riidaa o yakuwari toshite ukeiremashita."},{"jp":"私たちは彼を仲間として信頼しています。","en":"We trust him as one of our own (a close companion).","romaji":"Watashitachi wa kare o nakama toshite shinrai shite imasu."},{"jp":"このアーティストは伝統を基盤として作品を作ります。","en":"This artist creates works with tradition as the foundation.","romaji":"Kono aatisuto wa dentou o kiban toshite sakuhin o tsukurimasu."}],"example":"彼は教師を職業として働いています。","exampleMeaning":"He works as a teacher."},{"pattern":"～を中心に (〜wo chuushin ni)","meaning":"Indicates that something is centered around or focused on a main topic or area.","formation":"Noun + を中心に","examples":[{"jp":"このイベントは音楽を中心に楽しまれています。","en":"This event is mainly enjoyed for its music.","romaji":"Kono ibento wa ongaku o chuushin ni tanoshimarete imasu."},{"jp":"彼の仕事は東京を中心に行われています。","en":"His work is primarily conducted in and around Tokyo.","romaji":"Kare no shigoto wa Toukyou o chuushin ni okonawarete imasu."},{"jp":"彼女は健康を中心に本を書いています。","en":"She’s writing a book focusing on health.","romaji":"Kanojo wa kenkou o chuushin ni hon o kaite imasu."},{"jp":"最近の研究は環境保護を中心に行われている。","en":"Recent research is being carried out with a primary focus on environmental protection.","romaji":"Saikin no kenkyuu wa kankyou hogo o chuushin ni okonawarete iru."}],"example":"このイベントは音楽を中心に楽しまれています。","exampleMeaning":"This event is mainly enjoyed for its music."},{"pattern":"～を問わず (〜wo towazu)","meaning":"Means 'regardless of' or 'irrespective of'.","formation":"Noun + を問わず","examples":[{"jp":"このイベントは、年齢を問わず、誰でも参加できます。","en":"This event is open to everyone, regardless of age.","romaji":"Kono ibento wa, nenrei o towazu, dare demo sanka dekimasu."},{"jp":"このスーパーは、日曜日を問わず、毎日開いています。","en":"This supermarket is open every day, regardless of Sunday.","romaji":"Kono suupaa wa, nichiyoubi o towazu, mainichi aite imasu."},{"jp":"彼女は、暑さ寒さを問わず、毎朝散歩をしています。","en":"She takes a walk every morning, no matter the heat or cold.","romaji":"Kanojo wa, atsusa samusa o towazu, maiasa sanpo o shite imasu."},{"jp":"社長は、国籍を問わず、すべての社員を平等に扱っています。","en":"The company president treats all employees equally, regardless of nationality.","romaji":"Shachou wa, kokuseki o towazu, subete no shain o byoudou ni atsukatte imasu."}],"example":"このイベントは、年齢を問わず、誰でも参加できます。","exampleMeaning":"This event is open to everyone, regardless of age."},{"pattern":"～を込めて (〜wo komete)","meaning":"To express that something is done with a certain feeling, intention, or emotion.","formation":"Feeling/emotion/intention Noun + を + 込めて + Verb","examples":[{"jp":"愛を込めて料理を作りました。","en":"I cooked the meal with love.","romaji":"Ai wo komete ryouri wo tsukurimashita."},{"jp":"感謝を込めて先生にお礼の手紙を書きました。","en":"I wrote a thank-you letter to my teacher, filled with gratitude.","romaji":"Kansha wo komete sensei ni orei no tegami wo kakimashita."},{"jp":"彼は全力を込めて最後の瞬間まで戦いました。","en":"He fought until the last moment with all his strength.","romaji":"Kare wa zenryoku wo komete saigo no shunkan made tatakaimashita."},{"jp":"彼女は悲しみを込めて友達へ別れの言葉を伝えました。","en":"She conveyed her farewell words to her friend with sadness.","romaji":"Kanojo wa kanashimi wo komete tomodachi e wakare no kotoba wo tsutaemashita."}],"example":"愛を込めて料理を作りました。","exampleMeaning":"I cooked the meal with love."},{"pattern":"～を通じて (〜wo tsuujite)","meaning":"Expresses 'through', 'throughout', or 'during'.","formation":"Noun + を通じて","examples":[{"jp":"インターネットを通じて友達と連絡を取ります。","en":"I keep in touch with my friends through the internet.","romaji":"Intaanetto wo tsuujite tomodachi to renraku wo torimasu."},{"jp":"彼は一日を通じて熱心に働いています。","en":"He works diligently throughout the day.","romaji":"Kare wa ichinichi wo tsuujite nesshin ni hataraite imasu."},{"jp":"このイベントは週末を通じて開催されます。","en":"This event will take place throughout the weekend.","romaji":"Kono ibento wa shuumatsu wo tsuujite kaisai saremasu."},{"jp":"その花は春を通じて咲いています。","en":"The flowers bloom throughout the spring.","romaji":"Sono hana wa haru wo tsuujite saiteimasu."}],"example":"インターネットを通じて友達と連絡を取ります。","exampleMeaning":"I keep in touch with my friends through the internet."},{"pattern":"～を頼りに (〜wo tayori ni)","meaning":"To rely on or depend on something or someone.","formation":"Noun + を頼りに","examples":[{"jp":"彼女は地図を頼りに旅行をしている。","en":"She is traveling relying on a map.","romaji":"Kanojo wa chizu wo tayori ni ryokou wo shite iru."},{"jp":"多くの人が彼の力を頼りに生活している。","en":"Many people are living depending on his strength.","romaji":"Ooku no hito ga kare no chikara wo tayori ni seikatsu shite iru."},{"jp":"このプロジェクトでは、君のスキルを頼りにしています。","en":"In this project, we are counting on your skills.","romaji":"Kono purojekuto de wa, kimi no sukiru wo tayori ni shiteimasu."},{"jp":"彼は友達の助けを頼りに問題を解決しようとした。","en":"He tried to solve the problem relying on his friend's help.","romaji":"Kare wa tomodachi no tasuke wo tayori ni mondai wo kaiketsu shiyou to shita."}],"example":"彼女は地図を頼りに旅行をしている。","exampleMeaning":"She is traveling relying on a map."},{"pattern":"～一方 (〜ippou)","meaning":"Indicates that while one action or situation is happening, another action or situation is also occurring or is in contrast.","formation":"Verb-casual + 一方(で), い-Adjective + 一方(で), な-Adjective + な/である一方(で), Noun + である一方(で)","examples":[{"jp":"技術が進化する一方、生活が忙しくなっている。","en":"While technology advances, life is getting busier.","romaji":"Gijutsu ga shinka suru ippou, seikatsu ga isogashiku natte iru."},{"jp":"日本語が上達する一方、英語力が下がっている気がする。","en":"While my Japanese improves, I feel like my English ability is declining.","romaji":"Nihongo ga joutatsu suru ippou, eigo-ryoku ga sagatte iru ki ga suru."},{"jp":"この料理は美味しい一方、ちょっと高いです。","en":"While this dish is delicious, it’s a bit expensive.","romaji":"Kono ryouri wa oishii ippou, chotto takai desu."},{"jp":"彼は優しい一方、厳しい面もある。","en":"While he is kind, he also has a strict side.","romaji":"Kare wa yasashii ippou, kibishii men mo aru."}],"example":"技術が進化する一方、生活が忙しくなっている。","exampleMeaning":"While technology advances, life is getting busier."},{"pattern":"～一方だ (〜ippou da)","meaning":"Expresses that a situation or condition is continuing to increase or decrease in one direction.","formation":"Verb-dictionary form + 一方だ","examples":[{"jp":"世界の人口は増える一方だ。","en":"The world's population continues to increase.","romaji":"Sekai no jinkou wa fueru ippou da."},{"jp":"この町の治安は悪化する一方だ。","en":"Public safety in this town is getting worse and worse.","romaji":"Kono machi no chian wa akka suru ippou da."},{"jp":"僕の日本語は上達する一方だ。","en":"My Japanese keeps improving.","romaji":"Boku no nihongo wa joutatsu suru ippou da."},{"jp":"夏になると、暑さが厳しくなる一方だ。","en":"As summer arrives, it just keeps getting hotter.","romaji":"Natsu ni naru to, atsusa ga kibishiku naru ippou da."}],"example":"世界の人口は増える一方だ。","exampleMeaning":"The world's population continues to increase."},{"pattern":"～上で (〜ue de)","meaning":"Used to express that something is done after or on the basis of something else; 'after', 'upon'.","formation":"Verb-ますstem + 上で, Noun + の上で","examples":[{"jp":"調査を行った上で、結論を出しましょう。","en":"Let's draw a conclusion after conducting the investigation.","romaji":"Chousa wo okonatta ue de, ketsuron wo dashimashou."},{"jp":"就職活動を終えた上で、進学するかどうか決めます。","en":"I will decide whether to continue my studies after finishing my job hunting.","romaji":"Shuushoku katsudou wo oeta ue de, shingaku suru ka dou ka kimemasu."},{"jp":"試着した上で、この服を買うかどうか考えます。","en":"I'll think about whether to buy these clothes after trying them on.","romaji":"Shichaku shita ue de, kono fuku wo kau ka dou ka kangaemasu."},{"jp":"経験者の意見を聞いた上で、プロジェクトの方向性を決定しましょう。","en":"Let's decide the direction of the project after listening to those with experience.","romaji":"Keiken sha no iken wo kiita ue de, purojekuto no houkousei wo kettei shimashou."}],"example":"調査を行った上で、結論を出しましょう。","exampleMeaning":"Let's draw a conclusion after conducting the investigation."},{"pattern":"～上に (〜ue ni)","meaning":"Express 'in addition to', 'besides', 'not only... but also'.","formation":"Verb-plain + 上に, い-Adjective + 上に, な-Adjective + な上に, Noun + の上に","examples":[{"jp":"彼は頭がいい上に、スポーツも得意です。","en":"In addition to being smart, he is also good at sports.","romaji":"Kare wa atama ga ii ue ni, supo-tsu mo tokui desu."},{"jp":"このドレスは美しい上に、値段も安いです。","en":"This dress is not only beautiful but also affordable.","romaji":"Kono doresu wa utsukushii ue ni, nedan mo yasui desu."},{"jp":"彼女は優しい上に、料理も上手です。","en":"Besides being kind, she is also good at cooking.","romaji":"Kanojo wa yasashii ue ni, ryouri mo jouzu desu."},{"jp":"彼は社長の上に、有名な作家でもある。","en":"Not only is he a company president, but he is also a famous writer.","romaji":"Kare wa shachou no ue ni, yuumei na sakka demo aru."}],"example":"彼は頭がいい上に、スポーツも得意です。","exampleMeaning":"In addition to being smart, he is also good at sports."},{"pattern":"～上は","meaning":"Expresses 'now that', 'since', or 'once'.","formation":"Verb-casual + 上は, い-Adjective + 上は, な-Adjective + な上は, Noun + の上は","examples":[{"jp":"試験に合格した上は、パーティーを開こう。","en":"Now that I've passed the exam, let's have a party.","romaji":"Shiken ni goukaku shita ue wa, paatii wo hirakou."},{"jp":"この仕事を引き受けた上は、最後までやり遂げるつもりだ。","en":"Now that I have taken on this job, I intend to see it through to the end.","romaji":"Kono shigoto wo hikiuketa ue wa, saigo made yaritogeru tsumori da."},{"jp":"親切だと言われた上は、手伝ってあげよう。","en":"Since you said I'm kind, I'll help you out.","romaji":"Shinsetsu da to iwareta ue wa, tetsudatte ageyou."},{"jp":"甘いものが好きな上は、このデザートをきっと気に入るでしょう。","en":"Now that you like sweets, you'll surely enjoy this dessert.","romaji":"Amai mono ga suki na ue wa, kono dezaato wo kitto ki ni iru deshou."}],"example":"試験に合格した上は、パーティーを開こう。","exampleMeaning":"Now that I've passed the exam, let's have a party."},{"pattern":"～以上 (〜ijou)","meaning":"Expresses 'since' or 'as long as' in a conditional context.","formation":"Verb-casual + 以上, い-Adjective + 以上, な-Adjective + な以上, Noun + の以上","examples":[{"jp":"彼は忙しい以上、手伝いに行っても無駄だろう。","en":"Since he's busy, it would be pointless to try helping him.","romaji":"Kare wa isogashii ijou, tetsudai ni itte mo muda darou."},{"jp":"約束した以上、守るべきだ。","en":"Since I made a promise, I should keep it.","romaji":"Yakusoku shita ijou, mamoru beki da."},{"jp":"締め切りが近い以上、全力で仕事をしなければならない。","en":"As long as the deadline is near, I have to work with all my might.","romaji":"Shimekiri ga chikai ijou, zenryoku de shigoto wo shinakereba naranai."},{"jp":"彼女は大学生である以上、勉強が優先されるべきだ。","en":"Since she's a college student, studying should be her priority.","romaji":"Kanojo wa daigakusei de aru ijou, benkyou ga yuusen sareru beki da."}],"example":"彼は忙しい以上、手伝いに行っても無駄だろう。","exampleMeaning":"Since he's busy, it would be pointless to try helping him."},{"pattern":"～以来 (〜irai)","meaning":"Indicates something happening 'since', 'ever since', or 'after' a particular time.","formation":"Verb-past + 以来, い-Adjective + 以来, Noun + 以来","examples":[{"jp":"卒業以来、彼女に会っていない。","en":"I haven't seen her since we graduated.","romaji":"Sotsugyou irai, kanojo ni atte inai."},{"jp":"子供が生まれて以来、忙しくなった。","en":"I've been busy ever since my child was born.","romaji":"Kodomo ga umarete irai, isogashiku natta."},{"jp":"東京に引っ越して以来、友達が増えた。","en":"I've made more friends since I moved to Tokyo.","romaji":"Toukyou ni hikkoshite irai, tomodachi ga fueta."},{"jp":"あの映画を見た以来、彼女は怖がりになった。","en":"She's been easily frightened ever since she watched that movie.","romaji":"Ano eiga wo mita irai, kanojo wa kowagari ni natta."}],"example":"卒業以来、彼女に会っていない。","exampleMeaning":"I haven't seen her since we graduated."},{"pattern":"～切る (〜kiru)","meaning":"To do something completely or thoroughly.","formation":"Verb-stem + 切る","examples":[{"jp":"彼は試験勉強をがんばり切るつもりだ。","en":"He intends to give his absolute all to exam study.","romaji":"Kare wa shiken benkyou o ganbari kiru tsumori da."},{"jp":"この仕事を終わり切るまで、帰らないでください。","en":"Please don't go home until you've completely finished this job.","romaji":"Kono shigoto o owari kiru made, kaeranai de kudasai."},{"jp":"友達と喧嘩して、何も言い切れなかった。","en":"I argued with my friend and couldn't say everything I wanted to say.","romaji":"Tomodachi to kenka shite, nanimo iikirenakatta."},{"jp":"彼らは、そのゲームをやり切ることができました。","en":"They were able to complete that game thoroughly.","romaji":"Karera wa, sono geemu o yarikiru koto ga dekimashita."}],"example":"彼は試験勉強をがんばり切るつもりだ。","exampleMeaning":"He intends to give his absolute all to exam study."},{"pattern":"～反面 (〜hanmen)","meaning":"Express contrast between two aspects; 'on the one hand', 'on the other hand'.","formation":"Verb-casual + 反面, い-Adjective + 反面, な-Adjective + である反面, Noun + である反面","examples":[{"jp":"この車は速い反面、燃費が悪いです。","en":"On the one hand, this car is fast, but on the other hand, it has poor fuel efficiency.","romaji":"Kono kuruma wa hayai hanmen, nenpi ga warui desu."},{"jp":"彼は頭がいい反面、運動が苦手です。","en":"On the one hand, he is smart, but on the other hand, he's not good at sports.","romaji":"Kare wa atama ga ii hanmen, undou ga nigate desu."},{"jp":"彼女は親切である反面、面倒見が良すぎることがある。","en":"On the one hand, she is kind, but on the other hand, she can be too helpful.","romaji":"Kanojo wa shinsetsu de aru hanmen, mendoumi ga yoi sugiru koto ga aru."},{"jp":"この仕事は給料が高い反面、ストレスがたくさんあります。","en":"On the one hand, this job pays well, but on the other hand, it's quite stressful.","romaji":"Kono shigoto wa kyuuryou ga takai hanmen, sutoresu ga takusan arimasu."}],"example":"この車は速い反面、燃費が悪いです。","exampleMeaning":"On the one hand, this car is fast, but on the other hand, it has poor fuel efficiency."},{"pattern":"～向け (〜muke)","meaning":"Indicating target or intended audience.","formation":"Noun + 向け","examples":[{"jp":"この雑誌は若者向けです。","en":"This magazine is aimed at young people.","romaji":"Kono zasshi wa wakamono-muke desu."},{"jp":"スーパーで家族向けの食品セットが売っています。","en":"The supermarket sells food sets intended for families.","romaji":"Suupaa de kazoku-muke no shokuhin setto ga utte imasu."},{"jp":"このアプリは初心者向けに作られています。","en":"This application is designed for beginners.","romaji":"Kono apuri wa shoshinsha-muke ni tsukurarete imasu."},{"jp":"このレストランはビーガン向けのメニューが充実しています。","en":"This restaurant has an extensive menu aimed at vegans.","romaji":"Kono resutoran wa bi-gan-muke no menyu ga juujitsu shite imasu."}],"example":"この雑誌は若者向けです。","exampleMeaning":"This magazine is aimed at young people."},{"pattern":"～恐れがある (〜osore ga aru)","meaning":"Express a concern or fear that something undesirable might occur.","formation":"Verb-dictionary form + 恐れがある","examples":[{"jp":"地震が来る恐れがあるため、避難所に行ってください。","en":"Please go to the evacuation center because there is a risk of an earthquake.","romaji":"Jishin ga kuru osore ga aru tame, hinanjo ni itte kudasai."},{"jp":"彼は事故に遭う恐れがあるので、注意して運転してください。","en":"There's a possibility he might have an accident, so please drive carefully.","romaji":"Kare wa jiko ni au osore ga aru node, chuui shite unten shite kudasai."},{"jp":"この薬を飲みすぎると、副作用の恐れがある。","en":"If you take too much of this medicine, there is a risk of side effects.","romaji":"Kono kusuri wo nomisugiru to, fukusayou no osore ga aru."},{"jp":"低い予算でこのプロジェクトを進めると、品質が低くなる恐れがある。","en":"If we proceed with this project on a low budget, the quality may suffer.","romaji":"Hikui yosan de kono purojekuto wo susumeru to, hinshitsu ga hikuku naru osore ga aru."}],"example":"地震が来る恐れがあるため、避難所に行ってください。","exampleMeaning":"Please go to the evacuation center because there is a risk of an earthquake."},{"pattern":"～折には (〜ori ni wa)","meaning":"Expresses 'when' or 'in case of' specific situations or timings.","formation":"Verb-dictionary form + 折には, Verb-た form + 折には, い-Adjective + 折には, な-Adjective + な折には, Noun + の折には","examples":[{"jp":"喉が渇く折には、このペットボトルの水を飲んでください。","en":"When you get thirsty, please drink water from this bottle.","romaji":"Nodo ga kawaku ori ni wa, kono pettobotoru no mizu o nonde kudasai."},{"jp":"この地域に来る折には、この神社に必ずお参りしましょう。","en":"When you visit this area, make sure to go to this shrine.","romaji":"Kono chiiki ni kuru ori ni wa, kono jinja ni kanarazu omairi shimashou."},{"jp":"彼が元気じゃない折には、具合が悪いか尋ねてください。","en":"If he doesn't seem well, please ask if he's feeling sick.","romaji":"Kare ga genki ja nai ori ni wa, guai ga warui ka tazunete kudasai."},{"jp":"チャンスがある折には、躊躇せずに行動しましょう。","en":"When you have an opportunity, act without hesitation.","romaji":"Chansu ga aru ori ni wa, chuucho sezu ni koudou shimashou."}],"example":"喉が渇く折には、このペットボトルの水を飲んでください。","exampleMeaning":"When you get thirsty, please drink water from this bottle."},{"pattern":"～末","meaning":"Express the outcome after a period of time or series of actions; 'after', 'as a result of'.","formation":"Noun + 末","examples":[{"jp":"長い議論の末、ようやく意見がまとまった。","en":"After a long discussion, we finally reached a consensus.","romaji":"Nagai giron no sue, youyaku iken ga matomatta."},{"jp":"一週間の勉強の末、試験に合格した。","en":"After a week of studying, I passed the exam.","romaji":"Isshuukan no benkyou no sue, shiken ni goukaku shita."},{"jp":"何度も失敗の末、成功を手に入れた。","en":"After many failures, I finally achieved success.","romaji":"Nando mo shippai no sue, seikou wo te ni ireta."},{"jp":"彼との別れの末、新しい人生を始めた。","en":"After breaking up with him, I started a new life.","romaji":"Kare to no wakare no sue, atarashii jinsei wo hajimeta."}],"example":"長い議論の末、ようやく意見がまとまった。","exampleMeaning":"After a long discussion, we finally reached a consensus."},{"pattern":"～次第 (〜shidai)","meaning":"Expresses 'as soon as' (when used with Verb-ますstem) or 'depending on' (when used with a noun).","formation":"Verb-ますstem + 次第, Noun + 次第","examples":[{"jp":"仕事が終わり次第、帰ります。","en":"I will go home as soon as I finish work.","romaji":"Shigoto ga owari shidai, kaerimasu."},{"jp":"お客様のご意見次第で、サービスを改善します。","en":"We will improve our services depending on customer feedback.","romaji":"Okyakusama no goiken shidai de, saabisu wo kaizen shimasu."},{"jp":"彼の返事次第で、パーティーに行くかどうか決めます。","en":"I will decide whether or not to go to the party depending on his answer.","romaji":"Kare no henji shidai de, paatii ni iku ka dou ka kimemasu."},{"jp":"天気次第で、ピクニックを予定しています。","en":"We are planning a picnic depending on the weather.","romaji":"Tenki shidai de, pikunikku wo yotei shite imasu."}],"example":"仕事が終わり次第、帰ります。","exampleMeaning":"I will go home as soon as I finish work."},{"pattern":"～次第で (〜shidai de)","meaning":"Indicates 'depending on; based on' a certain factor or situation.","formation":"Noun + 次第で","examples":[{"jp":"仕事の終わり次第で、家に帰る時間が変わります。","en":"Depending on when I finish work, the time I go home may change.","romaji":"Shigoto no owari shidai de, ie ni kaeru jikan ga kawarimasu."},{"jp":"天気次第で、ピクニックに行く予定です。","en":"We plan to go on a picnic depending on the weather.","romaji":"Tenki shidai de, pikunikku ni iku yotei desu."},{"jp":"彼の気分次第で、パーティーに参加するかどうか決まります。","en":"Whether he participates in the party depends on his mood.","romaji":"Kare no kibun shidai de, paatii ni sanka suru ka dou ka kimarimasu."},{"jp":"会議の進行次第で、決定が変わるかもしれません。","en":"The decision may change depending on how the meeting progresses.","romaji":"Kaigi no shinkou shidai de, kettei ga kawaru kamoshiremasen."}],"example":"仕事の終わり次第で、家に帰る時間が変わります。","exampleMeaning":"Depending on when I finish work, the time I go home may change."},{"pattern":"～次第です (〜shidai desu)","meaning":"A polite/formal way to say 'it depends on...' or 'as soon as...', often used in concluding statements.","formation":"Verb-ますstem + 次第です (or Noun + 次第です)","examples":[{"jp":"天気次第ですが、明日はピクニックに行こうと思います。","en":"It depends on the weather, but I’m thinking of going for a picnic tomorrow.","romaji":"Tenki shidai desu ga, ashita wa pikunikku ni ikou to omoimasu."},{"jp":"試験の結果次第ですが、留学したいと考えています。","en":"It depends on my exam results, but I'm considering studying abroad.","romaji":"Shiken no kekka shidai desu ga, ryuugaku shitai to kangaete imasu."},{"jp":"お客様のご意見次第で新メニューを追加する次第です。","en":"We intend to add a new menu item depending on our customers’ feedback.","romaji":"Okyakusama no goiken shidai de shin menyuu wo tsuika suru shidai desu."},{"jp":"申請が完了次第ですので、手続きが終わったらパスポートを受け取れます。","en":"As soon as the application is completed, you'll be able to receive your passport.","romaji":"Shinsei ga kanryou shidai desu no de, tetsudzuki ga owattara pasupooto wo uketoremasu."}],"example":"天気次第ですが、明日はピクニックに行こうと思います。","exampleMeaning":"It depends on the weather, but I’m thinking of going for a picnic tomorrow."},{"pattern":"～気味 (〜gimi)","meaning":"Indicates a slight feeling or tendency toward a particular state.","formation":"Noun + 気味 (e.g., 風邪気味, 寝不足気味, 緊張気味)","examples":[{"jp":"最近寝不足気味で、ちょっと疲れています。","en":"Lately, I'm feeling somewhat sleep-deprived and a bit tired.","romaji":"Saikin nebusoku gimi de, chotto tsukarete imasu."},{"jp":"この部屋は暗い気味だから、もっと明るい照明をつけよう。","en":"This room is a bit dark, so let's install brighter lighting.","romaji":"Kono heya wa kurai gimi dakara, motto akarui shoumei wo tsukeyou."},{"jp":"彼女は緊張気味で話していました。","en":"She was speaking somewhat nervously.","romaji":"Kanojo wa kinchou gimi de hanashite imashita."},{"jp":"彼の声は風邪気味だったね。","en":"His voice sounded like he might have a slight cold.","romaji":"Kare no koe wa kaze gimi datta ne."}],"example":"最近寝不足気味で、ちょっと疲れています。","exampleMeaning":"Lately, I'm feeling somewhat sleep-deprived and a bit tired."},{"pattern":"～限り (〜kagiri)","meaning":"Expresses 'as long as', 'while', or 'to the extent that' a certain condition holds true.","formation":"Verb-casual + 限り, い-Adjective + 限り, な-Adjective + な限り, Noun + の限り","examples":[{"jp":"元気な限り、運動し続けます。","en":"As long as I'm healthy, I'll keep exercising.","romaji":"Genki na kagiri, undou shi tsuzukemasu."},{"jp":"お金がある限り、旅行を楽しみたい。","en":"As long as I have money, I'd like to travel.","romaji":"Okane ga aru kagiri, ryokou o tanoshimitai."},{"jp":"彼が話し続ける限り、このプロジェクトのメリットが伝わるでしょう。","en":"As long as he keeps talking about it, the benefits of this project will be conveyed.","romaji":"Kare ga hanashi tsudzukeru kagiri, kono purojekuto no meritto ga tsutawaru deshou."},{"jp":"勉強する限り、試験に合格できる可能性が高まります。","en":"As long as you study, you'll have a higher chance of passing the exam.","romaji":"Benkyou suru kagiri, shiken ni goukaku dekiru kanousei ga takamarimasu."}],"example":"元気な限り、運動し続けます。","exampleMeaning":"As long as I'm healthy, I'll keep exercising."},{"pattern":"～際に (〜sai ni)","meaning":"Means 'when', 'while', or 'on the occasion of' a certain event or situation.","formation":"Verb-casual + 際に, い-Adjective + 際に, な-Adjective + な際に, Noun + の際に","examples":[{"jp":"出発の際に、パスポートを忘れないでください。","en":"When departing, please don't forget your passport.","romaji":"Shuppatsu no sai ni, pasupooto wo wasurenai de kudasai."},{"jp":"地震が起こる際に、すぐに避難してください。","en":"When an earthquake occurs, please evacuate immediately.","romaji":"Jishin ga okoru sai ni, sugu ni hinan shite kudasai."},{"jp":"日本へ来る際に、お土産をたくさん買うつもりです。","en":"When I come to Japan, I plan to buy lots of souvenirs.","romaji":"Nihon e kuru sai ni, omiyage wo takusan kau tsumori desu."},{"jp":"面接の際に、スーツを着用してください。","en":"Please wear a suit when attending the interview.","romaji":"Mensetsu no sai ni, suutsu wo chakuyou shite kudasai."}],"example":"出発の際に、パスポートを忘れないでください。","exampleMeaning":"When departing, please don't forget your passport."}]
